                                const isCustom = !['개별박스','선물포장','선물포장+라벨부착','에어캡포장','기타',''].includes(p.packaging);
                                const selected = p.packaging===u || (u==='기타' && isCustom);
                                return `<option ${selected?'selected':''}>${u}</option>`;
