// ===== 웹푸시 알림 (PWA) =====
const PUSH_VAPID_PUBLIC = 'BO51LjQZu_swVb0UvfhAv9eTcT9gvbEkaxKlzRjRnVlin8-67Ynhv94urY7knMFb7vA4Q1NFs2J1Yxvs_Z_D6e0';

function urlBase64ToUint8Array(base64String) {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const raw = atob(base64);
    const arr = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) arr[i] = raw.charCodeAt(i);
    return arr;
}

// ===== 안드로이드 네이티브(FCM) 푸시 =====
// 안드로이드 앱(WebView)에서만 동작. 네이티브가 토큰을 받아 window.klpOnPushToken 으로 넘겨준다.
function registerAndroidPushIfNeeded() {
    if (window.AndroidBridge && typeof window.AndroidBridge.requestPushToken === 'function') {
        window.AndroidBridge.requestPushToken();
    }
}

// 안드로이드 홈 화면 위젯에 요약 + 오늘 할 일 목록(완료 토큰 포함) 전달
let _widgetLastPush = 0;
async function syncAndroidWidget(todayItems, summary) {
    if (!(window.AndroidBridge && typeof window.AndroidBridge.updateWidget === 'function')) return;
    const now = Date.now();
    if (now - _widgetLastPush < 15000) return;   // 과도한 호출 방지 (15초 쓰로틀)
    _widgetLastPush = now;
    let tasks = [];
    try {
        const ids = (todayItems || []).map(t => t.id).filter(Boolean);
        let tokens = {};
        if (ids.length) {
            const { data: { session } } = await sb.auth.getSession();
            const at = session && session.access_token;
            if (at) {
                const r = await fetch('/api/widget-task-tokens', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + at },
                    body: JSON.stringify({ ids }),
                });
                if (r.ok) { const j = await r.json(); tokens = j.tokens || {}; }
            }
        }
        tasks = (todayItems || []).map(t => ({
            id: t.id, task: t.task || '', done: !!t.done, token: tokens[t.id] || '',
        }));
    } catch (e) { /* 토큰 발급 실패해도 요약은 보냄 */ }
    try {
        window.AndroidBridge.updateWidget(JSON.stringify({ ...summary, tasks, updatedAt: Date.now() }));
    } catch (e) { /* 무시 */ }
}

// 네이티브에서 FCM 토큰을 전달받아 로그인 사용자와 함께 push_subscriptions 에 저장
window.klpOnPushToken = async function (token) {
    try {
        if (!token) return;
        const row = {
            endpoint: token,                 // FCM 토큰을 endpoint(unique)로 사용
            platform: 'android',
            user_name: (typeof currentUser !== 'undefined' && currentUser && currentUser.name) || '',
        };
        const { error } = await sb.from('push_subscriptions').upsert(row, { onConflict: 'endpoint' });
        if (error) console.error('FCM 토큰 저장 실패', error);
        else console.log('FCM 토큰 등록 완료');
    } catch (e) {
        console.error('klpOnPushToken 오류', e);
    }
};

// "알림 켜기" 버튼 → 권한 요청 + 구독 + Supabase 저장
async function enablePushNotifications() {
    if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) {
        showToast('이 기기/브라우저는 알림을 지원하지 않습니다');
        return;
    }
    try {
        const perm = await Notification.requestPermission();
        if (perm !== 'granted') {
            showToast(perm === 'denied' ? '알림이 차단되어 있어요. 브라우저 설정에서 허용해주세요.' : '알림 권한이 필요합니다.');
            refreshPushButton();
            return;
        }
        const reg = await navigator.serviceWorker.ready;
        let sub = await reg.pushManager.getSubscription();
        if (!sub) {
            sub = await reg.pushManager.subscribe({
                userVisibleOnly: true,
                applicationServerKey: urlBase64ToUint8Array(PUSH_VAPID_PUBLIC),
            });
        }
        const j = sub.toJSON();
        const row = {
            endpoint: j.endpoint,
            p256dh: j.keys && j.keys.p256dh,
            auth: j.keys && j.keys.auth,
            user_name: (typeof currentUser !== 'undefined' && currentUser && currentUser.name) || '',
        };
        const { error } = await sb.from('push_subscriptions').upsert(row, { onConflict: 'endpoint' });
        if (error) { showToast('알림 등록 실패: ' + error.message); return; }
        showToast('🔔 알림이 켜졌습니다');
        refreshPushButton();
    } catch (e) {
        console.error('알림 설정 실패', e);
        showToast('알림 설정 실패: ' + (e && e.message ? e.message : e));
    }
}

function refreshPushButton() {
    const btn = document.getElementById('pushToggleBtn');
    if (!btn) return;
    const supported = ('serviceWorker' in navigator) && ('PushManager' in window) && ('Notification' in window);
    if (!supported) { btn.style.display = 'none'; return; }
    btn.style.display = 'flex';
    const lbl = document.getElementById('pushToggleLabel');
    if (Notification.permission === 'granted') { if (lbl) lbl.textContent = '알림 켜짐 (재등록)'; btn.style.opacity = '0.7'; }
    else if (Notification.permission === 'denied') { if (lbl) lbl.textContent = '알림 차단됨'; btn.style.opacity = '1'; }
    else { if (lbl) lbl.textContent = '알림 켜기'; btn.style.opacity = '1'; }
}

// 그룹 지정값(개인이 아닌 공통/그룹) — 이 경우엔 전체 발송
const PUSH_GROUP_NAMES = ['전체', '임원', '대표님'];

// 이벤트 발생 시 서버로 발송 요청 (fire-and-forget — UI 막지 않음)
// targets: 받을 사람 이름 배열(당사자만). null/빈배열이면 전체 발송.
function triggerPush(title, body, url, targets, taskId) {
    (async () => {
        try {
            const { data } = await sb.auth.getSession();
            const token = data && data.session && data.session.access_token;
            if (!token) return;
            const payload = { title: title, body: body, url: url || '/' };
            if (Array.isArray(targets) && targets.length) payload.targets = targets;
            if (taskId != null) payload.taskId = taskId;
            await fetch('/api/send-push', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
                body: JSON.stringify(payload),
            });
        } catch (e) { console.warn('알림 발송 실패', e); }
    })();
}

function notifyNewProject(p) {
    if (!p) return;
    const who = (p.manager || (Array.isArray(p.assignees) ? p.assignees.join(', ') : '') || '').trim();
    const body = ((p.client ? p.client + ' ' : '') + (p.name || '') + (who ? ' (담당: ' + who + ')' : '')).trim();
    // 담당자 개인에게만: assignees + manager 첫 단어("김현호 팀장"→"김현호"). 개인 담당 없으면 알림 안 보냄(전체 발송 제거).
    const names = [];
    if (Array.isArray(p.assignees)) names.push(...p.assignees);
    if (p.manager) names.push(String(p.manager).trim().split(/\s+/)[0]);
    const targets = Array.from(new Set(names.filter(n => n && !PUSH_GROUP_NAMES.includes(n))));
    if (!targets.length) return; // 개인 담당자 없음 → 알림 없음
    triggerPush('🆕 새 프로젝트', body || '새 프로젝트가 등록되었습니다', '/#projects-domestic', targets);
}

function notifyNewTask(t) {
    if (!t) return;
    // 담당자 개인에게만: 전체/임원/대표님 같은 공통 건은 알림 안 보냄(전체 발송 제거).
    if (!t.assignee || PUSH_GROUP_NAMES.includes(t.assignee)) return;
    const body = (t.assignee + ' · ' + (t.task || '')).trim();
    triggerPush('🆕 새 할 일', body, '/#daily', [t.assignee], t.id);
}

