// =====================================
// Supabase: daily_tasks & deliveries
// =====================================
function taskToDb(t) {
    return {
        task: t.task,
        date: t.date,
        assignee: t.assignee,
        target: t.target || '',
        priority: t.priority || '🟡 보통',
        done: !!t.done,
        deadline: t.deadline || null,
        label: t.label || '',
        client: t.client || '',
        linked_group: t.linkedGroup || null,
        is_deadline_copy: !!t.isDeadlineCopy,
        project_id: t.projectId || null,
        completed_at: t.completedAt || null,
        note: t.note || null
    };
}
function taskFromDb(r) {
    return {
        id: r.id,
        task: r.task,
        date: r.date,
        assignee: r.assignee,
        target: r.target || '',
        priority: r.priority || '🟡 보통',
        done: !!r.done,
        deadline: r.deadline || '',
        label: r.label || '',
        client: r.client || '',
        linkedGroup: r.linked_group || null,
        isDeadlineCopy: !!r.is_deadline_copy,
        projectId: r.project_id || null,
        completedAt: r.completed_at || null,
        note: r.note || '',
        // 타임박스(내 하루) 공유 필드
        startMin: (r.start_min !== undefined ? r.start_min : null),
        durationMin: (r.duration_min !== undefined ? r.duration_min : null),
        big3Rank: (r.big3_rank !== undefined ? r.big3_rank : null),
        category: r.category || null
    };
}

// ===== BIG 3 (일일계획표 ↔ 타임박스 공유) =====
// 할 일 제목 앞 별 — 클릭으로 BIG 3 지정/해제
function big3Star(t) {
    const on = t.big3Rank != null;
    return `<span class="daily-big3 ${on ? 'on' : ''}" title="${on ? 'BIG 3 해제' : '오늘 꼭 마쳐야 할 일(BIG 3)로 지정'}" onclick="event.stopPropagation();toggleBig3(${t.id})">${on ? '⭐' : '☆'}</span>`;
}
async function toggleBig3(id) {
    const t = dailyTasks.find(x => x.id === id);
    if (!t) return;
    let rank = null;
    if (t.big3Rank == null) {
        // 그 담당자의 오늘 활성 BIG 3 개수 (미완료 이월분 + 오늘 것)
        const today = getTodayStr();
        const mine = dailyTasks.filter(x => x.assignee === t.assignee && x.big3Rank != null && (!x.done || x.date === today));
        if (mine.length >= 3) { alert(`⭐ ${t.assignee}의 BIG 3가 이미 3개로 가득 찼습니다.\n\n"${t.task}"은(는) 등록되지 않았습니다.\n먼저 기존 BIG 3 중 하나의 ⭐를 눌러 해제한 뒤 다시 시도해주세요.`); return; }
        const used = mine.map(x => x.big3Rank);
        rank = 1; while (used.includes(rank) && rank < 3) rank++;
    }
    const { data, error } = await sb.from('daily_tasks').update({ big3_rank: rank }).eq('id', id).select('id');
    if (error || !data || !data.length) { showToast('저장 실패' + (error ? ': ' + error.message : '')); return; }
    t.big3Rank = rank;
    try { if (typeof _tbxTasks !== 'undefined') { const x = _tbxTasks.find(y => y.id === id); if (x) x.big3_rank = rank; } } catch (_) {}
    renderDaily();
    try { if (typeof tbxRenderAll === 'function') tbxRenderAll(); } catch (_) {}
    showToast(rank != null ? `⭐ BIG 3 ${rank}순위로 지정` : 'BIG 3 해제됨');
}
async function loadDailyTasksFromDb() {
    try {
        // 일일계획은 kanban/캘린더 렌더라 "더 보기" 버튼이 부적절.
        // pageSize 100 으로 단계 로드 후, 남은 페이지를 자동 fetch (1500 행 safety cap)
        // 최신부터 불러와야 상한을 넘어도 오래된 것만 빠진다 (예전엔 오래된 것부터라 1500건 넘으면 새 할 일이 안 보일 뻔함)
        _dailyTasksPagination = await paginatedLoad('daily_tasks', {
            pageSize: 500,
            orderBy: 'id', orderDir: 'desc'
        });
        const SAFETY_CAP = 20000;
        while (_dailyTasksPagination.hasMore && _dailyTasksPagination.data.length < SAFETY_CAP) {
            const n = _dailyTasksPagination.data.length;
            await _dailyTasksPagination.loadMore();
            if (_dailyTasksPagination.data.length === n) break;
        }
        _dailyTasksPagination.data.sort((a, b) => a.id - b.id);   // 화면은 예전처럼 id 오름차순
        dailyTasks.length = 0;
        _dailyTasksPagination.data.forEach(r => dailyTasks.push(taskFromDb(r)));
        cacheWrite('dailyTasks', dailyTasks);
    } catch (err) {
        console.error('일일계획 로드 실패:', err.message);
        showToast('일일계획 로드 실패: ' + err.message);
    }
}

let dailyTasksChannel = null;
// ===== 전체 테이블 실시간 구독 =====
let _domesticRealtimeChannel = null;
let _tempRealtimeChannel = null;
let _deliveriesRealtimeChannel = null;
let _clientsRealtimeChannel = null;
let _planningRealtimeChannel = null;
let _planningRefreshTimer = null;

function scheduleRerender(fn, delay = 200) {
    // 단순 debounce — 여러 이벤트가 연달아 와도 한 번만 실행
    let t = scheduleRerender._timers || (scheduleRerender._timers = new Map());
    const prev = t.get(fn);
    if (prev) clearTimeout(prev);
    t.set(fn, setTimeout(() => { t.delete(fn); fn(); }, delay));
}

// 실시간 변경 1행을 페이지네이션 원본(raw rows)에 직접 반영 — 전체 재다운로드 방지 (Egress 절감).
// 반영 성공 시 true. 페이지네이션이 아직 없으면 false → 호출부에서 전체 로드로 폴백.
function _mergeRealtimeRow(pagination, payload, sortFn) {
    if (!pagination || !Array.isArray(pagination.data)) return false;
    const type = payload && payload.eventType;
    const newRow = payload && payload.new;
    const oldRow = payload && payload.old;
    const arr = pagination.data;
    if (type === 'INSERT' && newRow && newRow.id != null) {
        if (!arr.find(r => r.id === newRow.id)) {
            arr.unshift(newRow);
            if (typeof pagination.total === 'number') pagination.total++;
        }
    } else if (type === 'UPDATE' && newRow && newRow.id != null) {
        const i = arr.findIndex(r => r.id === newRow.id);
        if (i >= 0) arr[i] = newRow;
        else {
            arr.unshift(newRow);
            if (typeof pagination.total === 'number') pagination.total++;
        }
    } else if (type === 'DELETE' && oldRow && oldRow.id != null) {
        const i = arr.findIndex(r => r.id === oldRow.id);
        if (i >= 0) {
            arr.splice(i, 1);
            if (typeof pagination.total === 'number') pagination.total = Math.max(0, pagination.total - 1);
        }
    } else {
        return false;
    }
    if (sortFn) arr.sort(sortFn);
    return true;
}

