function adSetSource(mode) {
    _adSourceMode = mode;
    renderAdStudio();
}

function _adRenderProductPreview() {
    const box = document.getElementById('adProductPreview');
    if (!box) return;
    if (!_adProduct || !_adProduct.imageUrl) { box.innerHTML = ''; return; }
    // 업로드 직후 크게 보여줌 — 여기서 이미 잘려 보이면 저장 단계/원본 파일 문제로 즉시 판별 가능
    box.innerHTML = `<div style="margin-top:10px">
        <img src="${escHtml(_adProduct.imageUrl)}" style="max-width:220px;max-height:180px;object-fit:contain;border-radius:10px;border:1px solid var(--gray-200);background:#fff;padding:4px">
        <div style="margin-top:6px"><span style="font-weight:700">${escHtml(_adProduct.name || '')}</span>
        <span style="font-size:12px;color:var(--gray-500);margin-left:6px">${escHtml(String(_adProduct.price || ''))}</span></div>
        <div style="font-size:12px;color:var(--gray-500);margin-top:2px">↑ 이 미리보기가 잘려 보이면 알려주세요 (원본 파일 또는 저장 단계 문제)</div>
    </div>`;
}

function adPickDbProduct(id) {
    const p = productsDB.find(x => String(x.id) === String(id));
    if (!p) { _adProduct = null; _adRenderProductPreview(); return; }
    const priceStr = p.unitPrice ? (Number(p.unitPrice).toLocaleString() + '원' + (p.vatIncluded ? ' (VAT포함)' : '')) : '';
    _adProduct = { id: p.id, name: p.name, price: priceStr, imageUrl: p.image || '', points: p.description || '' };
    _adRenderProductPreview();
}

// 업로드 이미지 → 최대 1200px로 리사이즈한 data URL
// createImageBitmap: 파일을 통째로 확실히 디코드(부분 디코드로 절반이 회색으로 남는 문제 방지, EXIF 회전 반영)
async function _adFileToDataUrl(file, maxDim) {
    const drawToDataUrl = (src, w0, h0) => {
        const scale = Math.min(1, (maxDim || 1200) / Math.max(w0, h0));
        const w = Math.round(w0 * scale), h = Math.round(h0 * scale);
        const c = document.createElement('canvas'); c.width = w; c.height = h;
        const ctx = c.getContext('2d');
        ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); // PNG 투명 배경 → 흰색
        ctx.drawImage(src, 0, 0, w, h);
        return c.toDataURL('image/jpeg', 0.9);
    };
    // 1) 최우선: createImageBitmap (완전 디코드 보장)
    try {
        if (typeof createImageBitmap === 'function') {
            const bmp = await createImageBitmap(file);
            const out = drawToDataUrl(bmp, bmp.width, bmp.height);
            if (bmp.close) bmp.close();
            return out;
        }
    } catch (_) { /* 아래 폴백으로 */ }
    // 2) 폴백: FileReader + Image (+ decode()로 전체 디코드 대기)
    return new Promise((resolve, reject) => {
        const fr = new FileReader();
        fr.onload = () => {
            const img = new Image();
            img.onload = async () => {
                try { if (img.decode) await img.decode(); } catch (_) {}
                try { resolve(drawToDataUrl(img, img.naturalWidth, img.naturalHeight)); }
                catch (e) { reject(e); }
            };
            img.onerror = () => reject(new Error('이미지 로드 실패'));
            img.src = fr.result;
        };
        fr.onerror = () => reject(new Error('파일 읽기 실패'));
        fr.readAsDataURL(file);
    });
}

async function adOnUpload(input) {
    const file = input.files && input.files[0];
    if (!file) return;
    try {
        const dataUrl = await _adFileToDataUrl(file, 1200);
        if (!_adProduct) _adProduct = {};
        _adProduct.imageUrl = dataUrl;   // 원본 그대로 사용(자동 크롭 없음)
        _adProduct.id = null;
        // 이름/가격/포인트는 아래 입력칸에서 수집 시 채움
        _adRenderProductPreview();
    } catch (e) { showToast('이미지 처리 실패: ' + (e.message || e)); }
}

function _adCollectInputs() {
    if (_adSourceMode === 'upload') {
        const name = (document.getElementById('adUpName') || {}).value || '';
        const price = (document.getElementById('adUpPrice') || {}).value || '';
        const points = (document.getElementById('adUpPoints') || {}).value || '';
        if (!_adProduct) _adProduct = {};
        _adProduct.name = name.trim();
        _adProduct.price = price.trim();
        _adProduct.points = points.trim();
    }
    _adSettings = {
        goal: (document.getElementById('adGoal') || {}).value || '',
        tone: (document.getElementById('adTone') || {}).value || '',
        target: (document.getElementById('adTarget') || {}).value || '',
        emphasis: (document.getElementById('adEmphasis') || {}).value || ''
    };
}

async function generateAdMaterials() {
    _adCollectInputs();
    if (!_adProduct || !_adProduct.name) { showToast('제품을 먼저 선택/입력해주세요'); return; }
    if (!_adProduct.imageUrl) { showToast('제품 사진이 필요합니다'); return; }
    const { data } = await sb.auth.getSession();
    const token = data && data.session && data.session.access_token;
    if (!token) { showToast('다시 로그인해주세요'); return; }

    const btn = document.getElementById('adGenerateBtn');
    if (btn) { btn.disabled = true; btn.textContent = 'AI가 만드는 중… (최대 30초)'; }
    const headers = { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token };
    const prodForApi = { name: _adProduct.name, price: _adProduct.price, points: _adProduct.points };

    const [copyRes, imgRes] = await Promise.allSettled([
        fetch('/api/ad-copy', { method: 'POST', headers, body: JSON.stringify({ product: prodForApi, settings: _adSettings }) })
            .then(r => r.json().then(j => ({ ok: r.ok, j }))),
        fetch('/api/ad-image', { method: 'POST', headers, body: JSON.stringify({ product: prodForApi, settings: _adSettings, count: 2, styleRefs: _adStyleRefs, blend: _adBlend, productImage: _adBlend ? (_adProduct && _adProduct.imageUrl) : undefined }) })
            .then(r => r.json().then(j => ({ ok: r.ok, j })))
    ]);

    const variants = (copyRes.status === 'fulfilled' && copyRes.value.ok) ? (copyRes.value.j.variants || []) : [];
    const images = (imgRes.status === 'fulfilled' && imgRes.value.ok) ? (imgRes.value.j.images || []) : [];

    if (btn) { btn.disabled = false; btn.textContent = '✨ 다시 생성'; }

    // 각 요청의 에러 메시지(+상세)를 추출 — 실패 원인을 화면에 그대로 노출
    const errOf = (r) => {
        if (r.status !== 'fulfilled') return (r.reason && r.reason.message) || '네트워크 오류';
        if (r.value.ok) return '';
        const j = r.value.j || {};
        return (j.error || '실패') + (j.detail ? (' — ' + j.detail) : '');
    };
    const copyErr = errOf(copyRes);
    const imgErr = errOf(imgRes);

    if (!variants.length && !images.length) {
        const area = document.getElementById('adResultsArea');
        if (area) area.innerHTML = `<div style="background:var(--white);border:1px solid var(--toss-red,#E03131);border-radius:12px;padding:16px">
            <div style="font-weight:800;color:var(--toss-red,#E03131);margin-bottom:8px">생성 실패</div>
            <div style="font-size:13px;line-height:1.8;color:var(--gray-800)">
              • 문구(Claude): ${copyErr ? escHtml(copyErr) : '알 수 없음'}<br>
              • 이미지(OpenAI): ${imgErr ? escHtml(imgErr) : '알 수 없음'}
            </div>
            <div style="font-size:12px;color:var(--gray-500);margin-top:10px">이 화면을 캡처해서 알려주시면 원인을 정확히 잡을 수 있어요.</div>
        </div>`;
        showToast('생성 실패 — 아래 상세를 확인하세요');
        return;
    }
    const respBlend = (imgRes.status === 'fulfilled' && imgRes.value.ok && imgRes.value.j.blend) || false;
    _adResults = { variants, images, selCopy: 0, selImg: 0, composed: null, imgErr: imgErr, blend: respBlend };
    if (!variants.length) showToast('문구 생성 실패: ' + (copyErr || '알 수 없음'));
    if (!images.length && imgErr) showToast('이미지 생성 실패: ' + imgErr);
    renderAdResults();
}

function renderAdResults() {
    const area = document.getElementById('adResultsArea');
    if (!area || !_adResults) return;
    const r = _adResults;
    const v = r.variants[r.selCopy] || {};

    const imgThumbs = r.images.length
        ? r.images.map((src, i) => `<img src="${escHtml(src)}" onclick="adPickImg(${i})" style="width:96px;height:96px;object-fit:cover;border-radius:10px;cursor:pointer;border:3px solid ${i === r.selImg ? 'var(--blue)' : 'transparent'}">`).join('')
        : `<div style="font-size:13px;color:var(--gray-700);line-height:1.6">AI 배경 이미지가 생성되지 않았습니다${r.imgErr ? ' — <b style="color:var(--toss-red,#E03131)">' + escHtml(r.imgErr) + '</b>' : ''}.<br><span style="color:var(--gray-500)">지금은 파란 배경으로 대체되며, 문구·형식·다운로드는 정상 사용할 수 있어요.</span></div>`;

    const copyCards = r.variants.map((c, i) => `
        <div onclick="adPickCopy(${i})" style="border:2px solid ${i === r.selCopy ? 'var(--blue)' : 'var(--gray-200)'};border-radius:10px;padding:12px;cursor:pointer;min-width:200px;flex:1">
            <div style="font-weight:800;font-size:14px">${escHtml(c.headline || '')}</div>
            <div style="font-size:12px;color:var(--gray-500);margin-top:4px">${escHtml(c.sub || '')}</div>
        </div>`).join('');

    area.innerHTML = `
    <div style="background:var(--white);border:1px solid var(--gray-200);border-radius:14px;padding:20px">
      <div style="font-weight:800;font-size:15px;margin-bottom:12px">3. 배경 선택</div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px">${imgThumbs}</div>

      <div style="font-weight:800;font-size:15px;margin-bottom:12px">4. 문구 선택 & 수정</div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px">${copyCards}</div>
      <div class="form-group"><label class="form-label">헤드라인</label><input type="text" class="form-input" id="adEditHeadline" value="${escHtml(v.headline || '')}" oninput="adEditCopy('headline',this.value)"></div>
      <div class="form-group"><label class="form-label">보조 문구</label><input type="text" class="form-input" id="adEditSub" value="${escHtml(v.sub || '')}" oninput="adEditCopy('sub',this.value)"></div>
      <div class="form-group"><label class="form-label">본문</label><textarea class="form-input" rows="2" oninput="adEditCopy('body',this.value)" style="resize:vertical">${escHtml(v.body || '')}</textarea></div>
      <div class="form-group"><label class="form-label">CTA(행동 유도)</label><input type="text" class="form-input" id="adEditCta" value="${escHtml(v.cta || '')}" oninput="adEditCopy('cta',this.value)"></div>

      <div style="font-weight:800;font-size:15px;margin:18px 0 12px">5. 미리보기 & 내보내기</div>
      ${(_adProduct && _adProduct.imageUrl) ? `<div style="margin-bottom:12px">
        <div style="font-size:12px;color:var(--gray-500);margin-bottom:6px">합성에 쓰는 제품 이미지 (이게 잘려 보이면 원본/저장 문제):</div>
        <img src="${escHtml(_adProduct.imageUrl)}" style="height:96px;border-radius:8px;border:1px solid var(--gray-200);background:#fff;padding:4px;object-fit:contain">
      </div>` : ''}
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px">
        ${AD_FORMATS.map(f => `<button class="filter-chip ${_adFormat === f.key ? 'active' : ''}" onclick="adSetFormat('${f.key}')">${f.label}</button>`).join('')}
      </div>
      <div id="adPreview" style="margin-bottom:14px"></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button class="form-submit" style="flex:0 0 auto;padding:10px 16px" onclick="adDownloadImage()">🖼️ 이미지 다운로드</button>
        <button class="form-submit" style="flex:0 0 auto;padding:10px 16px;background:var(--gray-100);color:var(--gray-800)" onclick="adCopyKakao()">💬 카톡 문구 복사</button>
        <button class="form-submit" style="flex:0 0 auto;padding:10px 16px;background:var(--gray-100);color:var(--gray-800)" onclick="adCopyEmail()">✉️ 이메일 문구 복사</button>
        <button class="form-submit" style="flex:0 0 auto;padding:10px 16px;background:var(--gray-100);color:var(--gray-800)" onclick="saveAdCampaign()">💾 캠페인 저장</button>
      </div>
    </div>`;

    composeAdImage();
}

function adPickImg(i) { if (!_adResults) return; _adResults.selImg = i; renderAdResults(); }
function adPickCopy(i) { if (!_adResults) return; _adResults.selCopy = i; renderAdResults(); }
function adEditCopy(field, val) {
    if (!_adResults) return;
    const v = _adResults.variants[_adResults.selCopy]; if (!v) return;
    v[field] = val;
    clearTimeout(_adEditCopy._t);
    _adEditCopy._t = setTimeout(composeAdImage, 400); // 타이핑 중 과도한 재합성 방지
}

// 출력 형식: 카톡 정사각 / 이메일 가로형 / A4 인쇄 세로
const AD_FORMATS = [
    { key: 'kakao', label: '카톡·SNS (정사각)', w: 1080, h: 1080 },
    { key: 'email', label: '이메일 (가로형)', w: 1200, h: 628 },
    { key: 'print', label: 'A4 인쇄 (세로)', w: 1240, h: 1754 }
];
let _adFormat = 'kakao';
function adSetFormat(key) { _adFormat = key; renderAdResults(); }

// 선택 배경 + 제품 카드 + 또렷한 한글 텍스트를 선택 형식(정사각/가로/세로)으로 합성.
// 제품 사진은 <img object-fit>가 html2canvas에서 잘려서 background-size:contain 사용.
async function composeAdImage() {
    if (!_adResults) return;
    const r = _adResults;
    const v = r.variants[r.selCopy] || {};
    const bg = r.images[r.selImg] || '';
    const preview = document.getElementById('adPreview');
    if (typeof html2canvas === 'undefined') { if (preview) preview.innerHTML = '<div style="color:var(--toss-red)">합성 라이브러리 로드 실패</div>'; return; }

    const fmt = AD_FORMATS.find(f => f.key === _adFormat) || AD_FORMATS[0];
    const W = fmt.w, H = fmt.h;
    const px = n => Math.round(n) + 'px';
    const esc = escHtml;
    const prod = (_adProduct && _adProduct.imageUrl) || '';
    const bgStyle = bg
        ? `background-image:url('${bg}');background-size:cover;background-position:center`
        : 'background:linear-gradient(135deg,#1F85FF,#0F6CD9)';
    // 제품 사진은 html2canvas에 맡기지 않음(큰 이미지를 절반만 그리는 버그).
    // stage에는 흰 카드만 두고, 합성이 끝난 캔버스 위에 drawImage로 직접 그림(2단계).
    let cardGeom = null; // {x, y, size}
    const productCard = (size, x, y) => {
        if (!prod || r.blend) return ''; // 녹이기 모드: 제품이 배경에 이미 합성됨 → 카드 없음
        cardGeom = { x: Math.round(x), y: Math.round(y), size: Math.round(size) };
        return `<div style="position:absolute;left:${px(x)};top:${px(y)};width:${px(size)};height:${px(size)};background:#fff;border-radius:${px(28)};box-shadow:0 20px 60px rgba(0,0,0,.28)"></div>`;
    };

    let inner;
    if (W > H) {
        // 가로형(이메일): 제품 좌측 · 문구 우측
        const s = W / 1200;
        inner = `
          <div style="position:absolute;inset:0;${bgStyle}"></div>
          <div style="position:absolute;inset:0;background:linear-gradient(to right,rgba(0,0,0,.12) 0%,rgba(0,0,0,0) 30%,rgba(0,0,0,.78) 72%)"></div>
          ${productCard(H * 0.78, H * 0.11, (H - H * 0.78) / 2)}
          <div style="position:absolute;top:50%;right:${px(W * 0.05)};transform:translateY(-50%);width:${px(W * 0.46)};color:#fff;text-align:right">
            <div style="font-size:${px(58 * s)};font-weight:900;line-height:1.12;letter-spacing:-1px;text-shadow:0 2px 12px rgba(0,0,0,.35)">${esc(v.headline || '')}</div>
            <div style="font-size:${px(26 * s)};font-weight:600;margin-top:${px(10)};opacity:.95">${esc(v.sub || '')}</div>
            ${_adProduct && _adProduct.price ? `<div style="font-size:${px(30 * s)};font-weight:800;margin-top:${px(12)}">${esc(String(_adProduct.price))}</div>` : ''}
            ${v.cta ? `<div style="display:inline-block;margin-top:${px(20)};background:#1F85FF;color:#fff;font-size:${px(26 * s)};font-weight:800;padding:${px(12)} ${px(28)};border-radius:999px">${esc(v.cta)}</div>` : ''}
          </div>`;
    } else {
        // 정사각/세로(카톡·A4): 제품 상단 · 문구 하단
        const s = W / 1080;
        inner = `
          <div style="position:absolute;inset:0;${bgStyle}"></div>
          <div style="position:absolute;inset:0;background:linear-gradient(to bottom,rgba(0,0,0,0) 42%,rgba(0,0,0,.75) 100%)"></div>
          ${productCard(W * 0.54, (W - W * 0.54) / 2, H * 0.06)}
          <div style="position:absolute;left:${px(W * 0.06)};right:${px(W * 0.06)};bottom:${px(H * 0.05)};color:#fff">
            <div style="font-size:${px(64 * s)};font-weight:900;line-height:1.15;letter-spacing:-1px;text-shadow:0 2px 12px rgba(0,0,0,.35)">${esc(v.headline || '')}</div>
            <div style="font-size:${px(30 * s)};font-weight:600;margin-top:${px(12)};opacity:.95">${esc(v.sub || '')}</div>
            ${_adProduct && _adProduct.price ? `<div style="font-size:${px(34 * s)};font-weight:800;margin-top:${px(14)}">${esc(String(_adProduct.price))}</div>` : ''}
            ${v.cta ? `<div style="display:inline-block;margin-top:${px(22)};background:#1F85FF;color:#fff;font-size:${px(30 * s)};font-weight:800;padding:${px(14)} ${px(34)};border-radius:999px">${esc(v.cta)}</div>` : ''}
          </div>`;
    }

    const stage = document.createElement('div');
    stage.style.cssText = `position:fixed;left:-10000px;top:0;width:${W}px;height:${H}px;overflow:hidden;font-family:Pretendard,sans-serif`;
    stage.innerHTML = inner;
    document.body.appendChild(stage);
    try {
        const h2c = await html2canvas(stage, { width: W, height: H, scale: 1, useCORS: true, backgroundColor: '#ffffff', logging: false });
        // html2canvas가 돌려준 캔버스는 잔여 컨텍스트 상태 때문에 추가 drawImage가 무시됨(검증됨)
        // → 새 캔버스에 복사한 뒤 그 위에 제품 사진을 직접 그림
        const canvas = document.createElement('canvas');
        canvas.width = W; canvas.height = H;
        const cx = canvas.getContext('2d');
        cx.drawImage(h2c, 0, 0);
        if (cardGeom && prod) {
            const pim = await new Promise((ok, bad) => {
                const im = new Image();
                im.onload = () => ok(im);
                im.onerror = () => bad(new Error('제품 이미지 로드 실패'));
                im.src = prod;
            });
            const inset = cardGeom.size * 0.06;
            const box = cardGeom.size - inset * 2;
            const ar = (pim.naturalWidth || 1) / (pim.naturalHeight || 1);
            const iw = ar >= 1 ? box : box * ar;
            const ih = ar >= 1 ? box / ar : box;
            cx.save();
            cx.beginPath();
            if (cx.roundRect) cx.roundRect(cardGeom.x + 2, cardGeom.y + 2, cardGeom.size - 4, cardGeom.size - 4, 26);
            else cx.rect(cardGeom.x + 2, cardGeom.y + 2, cardGeom.size - 4, cardGeom.size - 4);
            cx.clip();
            cx.drawImage(pim, cardGeom.x + (cardGeom.size - iw) / 2, cardGeom.y + (cardGeom.size - ih) / 2, iw, ih);
            cx.restore();
        }
        r.composed = canvas.toDataURL('image/png');
        if (preview) preview.innerHTML = `<img src="${r.composed}" style="width:100%;max-width:${W > H ? 520 : 380}px;border-radius:14px;border:1px solid var(--gray-200)">`;
    } catch (e) {
        if (preview) preview.innerHTML = `<div style="color:var(--toss-red);font-size:13px">미리보기 합성 실패: ${esc(e.message || String(e))}</div>`;
    } finally {
        document.body.removeChild(stage);
    }
}

function adDownloadImage() {
    if (!_adResults || !_adResults.composed) { showToast('아직 미리보기가 준비되지 않았어요'); return; }
    const a = document.createElement('a');
    a.download = 'KLP_광고_' + _adFormat + '_' + getTodayStr() + '.png';
    a.href = _adResults.composed;
    a.click();
}
function adCopyKakao() {
    if (!_adResults) return;
    const v = _adResults.variants[_adResults.selCopy] || {};
    const text = [v.headline, '', v.body, v.cta, '', v.hashtags].filter(x => x != null).join('\n');
    navigator.clipboard.writeText(text).then(() => showToast('카톡 문구를 복사했어요')).catch(() => showToast('복사 실패'));
}
function adCopyEmail() {
    if (!_adResults) return;
    const v = _adResults.variants[_adResults.selCopy] || {};
    const text = '[제목] ' + (v.emailSubject || '') + '\n\n' + (v.emailBody || '');
    navigator.clipboard.writeText(text).then(() => showToast('이메일 문구를 복사했어요')).catch(() => showToast('복사 실패'));
}

async function saveAdCampaign() {
    if (!_adResults) { showToast('생성 후 저장할 수 있어요'); return; }
    const v = _adResults.variants[_adResults.selCopy] || {};
    const row = {
        author: (typeof currentUser !== 'undefined' && currentUser && currentUser.name) || '',
        product_id: (_adProduct && _adProduct.id) || null,
        product_snapshot: _adProduct ? { name: _adProduct.name, price: _adProduct.price, imageUrl: _adProduct.imageUrl, points: _adProduct.points } : null,
        settings: _adSettings,
        copy: v,
        bg_image: _adResults.images[_adResults.selImg] || null,
        status: '작성'
    };
    const { error } = await sb.from('ad_campaigns').insert(row);
    if (error) { showToast('저장 실패: ' + error.message); return; }
    showToast('캠페인이 저장되었습니다');
    loadAdCampaigns();
}

async function loadAdCampaigns() {
    const area = document.getElementById('adRecentArea');
    if (!area) return;
    try {
        const { data, error } = await sb.from('ad_campaigns').select('id,created_at,product_snapshot,copy').order('created_at', { ascending: false }).limit(10);
        if (error) throw error;
        if (!data || !data.length) { area.innerHTML = ''; return; }
        const items = data.map(c => {
            const nm = (c.product_snapshot && c.product_snapshot.name) || '(제품)';
            const hl = (c.copy && c.copy.headline) || '';
            return `<div onclick="adOpenCampaign(${c.id})" style="padding:10px 12px;border:1px solid var(--gray-200);border-radius:10px;cursor:pointer;display:flex;justify-content:space-between;gap:10px">
                <span style="font-weight:700">${escHtml(nm)}</span>
                <span style="color:var(--gray-500);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(hl)}</span></div>`;
        }).join('');
        area.innerHTML = `<div style="font-weight:800;font-size:15px;margin-bottom:10px">최근 저장한 광고</div><div style="display:flex;flex-direction:column;gap:8px">${items}</div>`;
    } catch (e) { area.innerHTML = ''; }
}

async function adOpenCampaign(id) {
    try {
        const { data, error } = await sb.from('ad_campaigns').select('*').eq('id', id).single();
        if (error) throw error;
        const snap = data.product_snapshot || {};
        _adProduct = { id: data.product_id, name: snap.name, price: snap.price, imageUrl: snap.imageUrl, points: snap.points };
        _adSettings = data.settings || {};
        _adResults = { variants: [data.copy || {}], images: data.bg_image ? [data.bg_image] : [], selCopy: 0, selImg: 0, composed: null };
        renderAdResults();
        document.getElementById('adResultsArea').scrollIntoView({ behavior: 'smooth' });
    } catch (e) { showToast('불러오기 실패: ' + (e.message || e)); }
}

// ===== 회의록 =====================================================
// 회의록 담당자/참석자 목록 — KLP는 기존 고정, 신규 회사는 자기 멤버
function meetingStaffList() { return _isKlpCompany() ? ['대표님', '이현주', '김현호', '유지은', '구정두'] : companyPeople(); }
const MEETING_STATUSES = ['작성중', '공유됨', '완료'];

let _meetings = [];            // 목록에 그릴 회의 배열 (DB row 그대로)
let _meetingsPage = null;      // paginatedLoad 상태
let _meetingEditingId;         // undefined=목록, null=새 회의록, 숫자=편집 중
let _meetingDraft = null;      // 편집 중인 회의 객체
let _meetingActions = [];      // 편집 중인 회의의 액션아이템
let _meetingActionDone = {};   // { daily_task_id: true/false } — daily_tasks.done 사본
let _meetingListRerender = {};  // { Agenda: fn, Decisions: fn } — 목록만 다시 그리는 함수(AI 채우기 등에서 사용)
let _meetingsSearch = '';
let _meetingDirty = false;     // 편집 중 저장하지 않은 변경이 있는가
let _meetingDailyDate = '';    // 편집 화면 하단 일일계획표가 보여주는 날짜
// 하단 일일계획표에 보여줄 담당자 (임원·구정두 제외)
const MEETING_DAILY_COLUMNS = ['전체', '대표님', '이현주', '김현호', '유지은'];
let _meetingMonth = '';        // 월간 달력이 보여주는 달 (YYYY-MM)
let _meetingReviewId = null;   // 이행 점검 패널이 보고 있는 지난 회의 id
// 담당자별 색 (월간 달력 칩 왼쪽 띠)
const MEETING_ASSIGNEE_COLORS = {
    '전체': '#8b95a1', '대표님': '#8b5cf6', '이현주': '#3182f6', '김현호': '#f97316', '유지은': '#30c85e'
};

// 안건 항목: {text, done}. 예전 데이터(문자열 배열)도 받아서 변환한다.
function _normMeetingAgenda(a) {
    if (!Array.isArray(a)) return [];
    return a.map(it => (typeof it === 'string')
        ? { text: it, done: false }
        : { text: (it && it.text) || '', done: !!(it && it.done) });
}

function _meetingRowDefaults(r) {
    return {
        id: r.id,
        author: r.author || '',
        title: r.title || '',
        meetAt: r.meet_at || '',
        location: r.location || '',
        attendees: Array.isArray(r.attendees) ? r.attendees : [],
        externalAttendees: r.external_attendees || '',
        client: r.client || '',
        agenda: _normMeetingAgenda(r.agenda),
        content: r.content || '',
        decisions: Array.isArray(r.decisions) ? r.decisions : [],
        status: r.status || '작성중',
        isPrivate: !!r.is_private
    };
}

// 논의 내용은 HTML(이미지 포함). 옛 데이터는 plain text라 <가 없으면 텍스트로 취급해 줄바꿈만 살린다.
function _meetingContentHtml(raw) {
    if (!raw) return '';
    // 진짜 태그(<p>, </div>, <br/>)가 있어야 HTML로 본다. "<태그>" 같은 글자는 평문 취급.
    if (!/<\/?[a-z][a-z0-9]*(\s|\/?>)/i.test(raw)) return escHtml(raw).replace(/\n/g, '<br>');
    return planningSanitizeHtml(raw);
}

// 이 회의록을 고칠 수 있는가? — 회사 구성원(로그인 사용자)이면 누구나 수정 가능.
// (볼 수 있는 회의만 편집기에 뜨고, RLS UPDATE도 "볼 수 있으면 수정" 이라 화면·DB가 일치)
function _meetingCanEdit() {
    return !!(currentUser && currentUser.name);
}
// 삭제는 작성자·관리자만 (RLS meetings_delete 와 동일)
function _meetingCanDelete() {
    if (_meetingEditingId === null) return false;              // 새 회의록은 삭제 개념 없음
    if (!currentUser || !currentUser.name || !_meetingDraft) return false;
    return _meetingDraft.author === currentUser.name || ADMIN_ROLES.includes(currentUser.role);
}

// 전원 선택 버튼의 상태·문구를 참석자 목록과 맞춘다.
function _syncMeetingAllBtn() {
    const btn = document.getElementById('meetingAttAll');
    if (!btn || !_meetingDraft) return;
    const everyone = meetingStaffList().every(n => _meetingDraft.attendees.includes(n));
    btn.classList.toggle('on', everyone);
    btn.textContent = everyone ? '전원 해제' : '전원 선택';
}

// 날짜 입력이 비었거나 손상된 경우 null. (new Date('...').toISOString()은 RangeError를 던진다)
function _meetingIsoOrNull(v) {
    if (!v) return null;
    const d = new Date(v);
    return isNaN(d.getTime()) ? null : d.toISOString();
}

function _meetingToDb(m) {
    return {
        author: m.author || null,
        title: m.title,
        meet_at: _meetingIsoOrNull(m.meetAt),
        location: m.location || null,
        attendees: m.attendees || [],
        external_attendees: m.externalAttendees || null,
        client: m.client || null,
        agenda: m.agenda || [],
        content: m.content || null,
        decisions: m.decisions || [],
        status: m.status || '작성중',
        is_private: !!m.isPrivate
    };
}

// datetime-local 입력값 ↔ ISO
function _meetingLocalDateTime(iso) {
    if (!iso) return '';
    const d = new Date(iso);
    if (isNaN(d)) return '';
    const pad = (n) => String(n).padStart(2, '0');
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
        'T' + pad(d.getHours()) + ':' + pad(d.getMinutes());
}
function _meetingDateLabel(iso) {
    if (!iso) return '-';
    const d = new Date(iso);
    if (isNaN(d)) return '-';
    const pad = (n) => String(n).padStart(2, '0');
    return d.getFullYear() + '.' + pad(d.getMonth() + 1) + '.' + pad(d.getDate()) + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
}

async function loadMeetings() {
    try {
        _meetingsPage = await paginatedLoad('meetings', {
            pageSize: 30, orderBy: 'meet_at', orderDir: 'desc', secondaryOrderBy: 'id', secondaryOrderDir: 'desc'
        });
        await loadAllPages(_meetingsPage);   // 검색·필터·연결이 전체 기준이 되도록 전부 불러옴
        _meetings = _meetingsPage.data || [];
    } catch (e) {
        console.error('loadMeetings failed', e);
        showToast('회의록 불러오기 실패: ' + (e.message || e));
        _meetings = [];
    }
}

// 목록에 진행률을 보여주려면 각 회의의 액션아이템 + 연결된 할 일의 done이 필요하다.
// 한 번에 다 긁어와 메모리에서 집계 (건수가 작음).
async function _meetingLoadProgress(ids) {
    const map = {}; // meetingId -> { total, done }
    if (!ids.length) return map;
    const { data: acts, error } = await sb.from('meeting_actions')
        .select('meeting_id, daily_task_id').in('meeting_id', ids);
    if (error) { console.error(error); return map; }
    const taskIds = (acts || []).map(a => a.daily_task_id).filter(Boolean);
    const doneMap = {};
    if (taskIds.length) {
        const { data: tasks } = await sb.from('daily_tasks').select('id, done').in('id', taskIds);
        (tasks || []).forEach(t => { doneMap[t.id] = !!t.done; });
    }
    (acts || []).forEach(a => {
        if (!map[a.meeting_id]) map[a.meeting_id] = { total: 0, done: 0 };
        map[a.meeting_id].total++;
        if (a.daily_task_id && doneMap[a.daily_task_id]) map[a.meeting_id].done++;
    });
    return map;
}

async function renderMeetings() {
    const box = document.getElementById('meetingsBody');
    if (!box) return;
    if (_meetingEditingId !== undefined) { renderMeetingEditor(); return; }
    box.innerHTML = '<div style="padding:40px;text-align:center;color:var(--gray-500)">불러오는 중…</div>';
    await loadMeetings();
    // 로딩 중 사용자가 F2 등으로 편집기를 열었다면 목록으로 덮어쓰지 않는다
    if (_meetingEditingId !== undefined) return;
    await _renderMeetingList();
}

async function _renderMeetingList() {
    const box = document.getElementById('meetingsBody');
    if (!box) return;
    const progress = await _meetingLoadProgress(_meetings.map(m => m.id));

    const q = _meetingsSearch.trim().toLowerCase();
    const rows = _meetings.filter(m => !q ||
        (m.title || '').toLowerCase().includes(q) ||
        (m.content || '').toLowerCase().includes(q));

    box.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px">
        <input id="meetingsSearch" type="text" placeholder="제목·내용 검색" value="${escHtml(_meetingsSearch)}"
               style="flex:1;max-width:320px;padding:10px 14px;border:1px solid var(--gray-200);border-radius:8px;font-size:14px">
        <button class="btn-primary" id="meetingNewBtn" title="단축키 F2">+ 새 회의록 <span style="opacity:.55;font-size:11px;font-weight:600">F2</span></button>
      </div>
      <div class="table-wrap">
        <table class="data-table">
          <thead><tr>
            <th style="width:150px">일시</th><th>제목</th><th style="width:200px">참석자</th>
            <th style="width:110px">액션아이템</th><th style="width:90px">상태</th>
          </tr></thead>
          <tbody id="meetingsTbody"></tbody>
        </table>
      </div>
      <div id="meetingsMore"></div>`;

    const tb = document.getElementById('meetingsTbody');
    if (!rows.length) {
        tb.innerHTML = '<tr><td colspan="5" style="padding:40px;text-align:center;color:var(--gray-500)">회의록이 없습니다. 오른쪽 위 “+ 새 회의록”을 눌러 시작하세요.</td></tr>';
    } else {
        tb.innerHTML = rows.map(m => {
            const p = progress[m.id] || { total: 0, done: 0 };
            const att = (Array.isArray(m.attendees) ? m.attendees : []).join(', ');
            return `<tr class="meeting-row" data-mid="${m.id}" style="cursor:pointer">
              <td>${escHtml(_meetingDateLabel(m.meet_at))}</td>
              <td>${m.is_private ? '🔒 ' : ''}${escHtml(m.title || '(제목 없음)')}</td>
              <td>${escHtml(att)}</td>
              <td>${p.total ? (p.done + ' / ' + p.total) : '-'}</td>
              <td>${escHtml(m.status || '작성중')}</td>
            </tr>`;
        }).join('');
    }

    renderLoadMoreButton(document.getElementById('meetingsMore'), _meetingsPage, () => {
        _meetings = _meetingsPage.data || [];
        _renderMeetingList();
    });

    document.getElementById('meetingNewBtn').addEventListener('click', () => openMeetingEditor(null));
    const s = document.getElementById('meetingsSearch');
    s.addEventListener('input', () => { _meetingsSearch = s.value; });
    s.addEventListener('keydown', (e) => { if (e.key === 'Enter') _renderMeetingList(); });
    tb.querySelectorAll('.meeting-row').forEach(tr => {
        tr.addEventListener('click', () => openMeetingEditor(Number(tr.dataset.mid)));
    });
}

async function openMeetingEditor(id) {
    _meetingEditingId = id; // null = 신규
    _meetingDirty = false;
    startMeetingAutoSave();   // 편집 여는 동안 30초마다 자동 저장
    _meetingReviewId = null; // 회의 바뀌면 이행 점검 패널 접힘
    if (id === null) {
        const now = new Date();
        _meetingDraft = _meetingRowDefaults({
            author: (currentUser && currentUser.name) || '',
            title: '', meet_at: now.toISOString(), attendees: [], status: '작성중'
        });
        _meetingActions = [];
        _meetingActionDone = {};
        renderMeetingEditor();
        return;
    }
    const { data, error } = await sb.from('meetings').select('*').eq('id', id).single();
    if (error) { console.error(error); showToast('회의록 불러오기 실패: ' + error.message); _meetingEditingId = undefined; renderMeetings(); return; }
    _meetingDraft = _meetingRowDefaults(data);
    await loadMeetingActions(id);
    renderMeetingEditor();
}

function closeMeetingEditor() {
    if (_meetingDirty && !confirm('저장하지 않은 내용이 있습니다. 목록으로 나가면 사라집니다. 나가시겠어요?')) return;
    stopMeetingAutoSave();
    _meetingDirty = false;
    _meetingEditingId = undefined;
    _meetingDraft = null;
    _meetingActions = [];
    renderMeetings();
}

// 안건/결정 목록의 행 HTML (부분 재렌더에서도 재사용)
function _meetingListRowsHtml(kind, items, check) {
    const lo = kind.toLowerCase();
    return items.map((v, i) => {
        const text = check ? (v.text || '') : v;
        const done = check ? !!v.done : false;
        return `<div class="meeting-list-row${done ? ' item-done' : ''}" data-${lo}-row="${i}">
            <span class="meeting-drag-handle" draggable="true" data-${lo}-drag="${i}" title="드래그해서 순서 변경">⠿</span>
            ${check ? `<input type="checkbox" class="meeting-item-check" data-${lo}-check="${i}" ${done ? 'checked' : ''} title="완료 표시">` : ''}
            <input type="text" data-${lo}-i="${i}" value="${escHtml(text)}">
            <button type="button" class="meeting-del" data-${lo}-del="${i}">✕</button>
        </div>`;
    }).join('');
}

function renderMeetingEditor() {
    const box = document.getElementById('meetingsBody');
    if (!box || !_meetingDraft) return;
    const m = _meetingDraft;

    const allOn = meetingStaffList().every(n => m.attendees.includes(n));
    const attendeeChips =
      `<button type="button" class="meeting-chip meeting-chip-all${allOn ? ' on' : ''}" id="meetingAttAll">${allOn ? '전원 해제' : '전원 선택'}</button>` +
      meetingStaffList().map(n => `
      <label class="meeting-chip${m.attendees.includes(n) ? ' on' : ''}">
        <input type="checkbox" data-att="${escHtml(n)}" ${m.attendees.includes(n) ? 'checked' : ''} hidden>${escHtml(n)}
      </label>`).join('');

    // check=true 이면 각 항목에 완료 체크박스 (안건용). 항목은 {text,done} 객체.
    const listEditor = (kind, items, check) => `
      <div id="meeting${kind}List">${_meetingListRowsHtml(kind, items, check)}</div>
      <button type="button" class="btn-ghost" id="meeting${kind}Add">+ 추가</button>`;

    const canEdit = _meetingCanEdit();

    box.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
        <button class="btn-ghost" id="meetingBackBtn">← 목록</button>
        <div style="display:flex;gap:8px;align-items:center">
          ${canEdit ? '<span id="meetingAutoSaveStatus" style="font-size:12px;color:var(--gray-500)">30초마다 자동 저장됩니다</span>' : ''}
          ${canEdit ? '' : `<span style="font-size:13px;color:var(--gray-500)">읽기 전용 — 작성자(${escHtml(m.author || '?')})와 관리자만 수정할 수 있습니다</span>`}
          ${_meetingCanDelete() ? '<button class="btn-danger" id="meetingDeleteBtn">삭제</button>' : ''}
          ${canEdit ? '<button class="btn-primary" id="meetingSaveBtn">저장</button>' : ''}
        </div>
      </div>

      <div class="card" style="padding:20px;margin-bottom:16px">
        <div class="field"><label>제목</label>
          <input id="meetingTitle" type="text" value="${escHtml(m.title)}" placeholder="예: 2월 신제품 킥오프"></div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:14px">
          <div class="field"><label>일시</label>
            <input id="meetingMeetAt" type="datetime-local" value="${_meetingLocalDateTime(m.meetAt)}"></div>
          <div class="field"><label>장소</label>
            <input id="meetingLocation" type="text" value="${escHtml(m.location)}" placeholder="회의실 / 온라인"></div>
        </div>
        <div class="field" style="margin-top:14px"><label>참석자 (직원)</label>
          <div id="meetingAttendees" class="meeting-chips">${attendeeChips}</div></div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:14px">
          <div class="field"><label>외부 참석자</label>
            <input id="meetingExternal" type="text" value="${escHtml(m.externalAttendees)}" placeholder="예: OO상사 김부장"></div>
          <div class="field"><label>거래처</label>
            <input id="meetingClient" type="text" value="${escHtml(m.client)}"></div>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:14px">
          <div class="field"><label>상태</label>
            <select id="meetingStatus">${MEETING_STATUSES.map(s => `<option${s === m.status ? ' selected' : ''}>${s}</option>`).join('')}</select></div>
          <div class="field"><label>공개 범위</label>
            <label style="display:flex;align-items:center;gap:8px;padding-top:8px">
              <input id="meetingPrivate" type="checkbox" ${m.isPrivate ? 'checked' : ''}> 🔒 비공개 (참석자·작성자·관리자만)
            </label></div>
        </div>
      </div>

      <div class="card" style="padding:20px;margin-bottom:16px" id="meetingReviewCard">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap">
          <h3 style="margin:0">📌 지난 회의 이행 점검 <span style="font-weight:400;color:var(--gray-500);font-size:13px">— 지난 회의에서 시킨 일이 됐는지 확인</span></h3>
          <div style="display:flex;gap:8px;align-items:center">
            <select id="meetingReviewSelect" style="display:none"></select>
            <button type="button" class="btn-ghost" id="meetingReviewBtn">지난 회의 불러오기</button>
          </div>
        </div>
        <div id="meetingReviewBox" style="margin-top:12px"></div>
      </div>

      <div class="card" style="padding:20px;margin-bottom:16px" id="meetingDailyCard"></div>

      <div class="card" style="padding:20px;margin-bottom:16px">
        <h3 style="margin:0 0 12px">안건</h3>
        ${listEditor('Agenda', m.agenda, true)}
      </div>

      <div class="card" style="padding:20px;margin-bottom:16px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;gap:8px;flex-wrap:wrap">
          <h3 style="margin:0">논의 내용</h3>
          <div style="display:flex;gap:8px;align-items:center">
            <button type="button" class="btn-primary" id="meetingAiBtn" style="font-size:13px" title="논의 내용을 읽고 결정사항·액션아이템을 자동으로 정리합니다">🤖 AI로 결정·액션 뽑기</button>
            <label class="btn-ghost" style="margin:0">
              🖼 이미지 넣기
              <input type="file" id="meetingImageFile" accept="image/*" multiple hidden>
            </label>
          </div>
        </div>
        <div id="meetingContent" class="meeting-content" contenteditable="true"
             data-placeholder="내용을 입력하세요. 이미지는 붙여넣기(Ctrl+V) 하거나 끌어다 놓으세요.">${_meetingContentHtml(m.content)}</div>
      </div>

      <div class="card" style="padding:20px;margin-bottom:16px">
        <h3 style="margin:0 0 12px">결정사항</h3>
        ${listEditor('Decisions', m.decisions)}
      </div>

      <div class="card" style="padding:20px;margin-bottom:16px" id="meetingActionsCard"></div>

      <div class="card" style="padding:20px" id="meetingMonthlyCard"></div>`;

    _bindMeetingEditor();
    renderMeetingActions();
    // 회의 일시는 UTC로 저장되므로 로컬 날짜로 환산해서 쓴다 (그냥 자르면 하루 어긋남)
    const localDate = _meetingLocalDateTime(m.meetAt).slice(0, 10) || getTodayStr();
    _meetingDailyDate = localDate;
    _meetingMonth = localDate.slice(0, 7);
    renderMeetingDailyBoard();
    renderMeetingMonthlyBoard();
    if (_meetingReviewId) openMeetingReview(); // 재렌더 후 이행 점검 패널 복원
}

function _bindMeetingEditor() {
    document.getElementById('meetingBackBtn').addEventListener('click', closeMeetingEditor);
    const save = document.getElementById('meetingSaveBtn');
    if (save) save.addEventListener('click', saveMeeting);
    const del = document.getElementById('meetingDeleteBtn');
    if (del) del.addEventListener('click', deleteMeeting);
    // 삭제는 작성자·관리자만 — 그 외에는 삭제 버튼 숨김
    if (del && !_meetingCanDelete()) del.style.display = 'none';

    // 수정 권한이 없으면(비로그인 등) 입력 자체를 잠근다 (DB가 조용히 거부하는 것보다 낫다)
    if (!_meetingCanEdit()) {
        const box = document.getElementById('meetingsBody');
        box.querySelectorAll('input, select, textarea').forEach(el => { el.disabled = true; });
        box.querySelectorAll('.meeting-del, #meetingAgendaAdd, #meetingDecisionsAdd, #meetingAttAll').forEach(el => { el.disabled = true; });
        const ce = document.getElementById('meetingContent');
        if (ce) ce.setAttribute('contenteditable', 'false');
        return; // 나머지 편집 핸들러는 달지 않는다
    }

    document.querySelectorAll('#meetingAttendees input[data-att]').forEach(cb => {
        cb.addEventListener('change', () => {
            const n = cb.dataset.att;
            const on = cb.checked;
            const set = new Set(_meetingDraft.attendees);
            if (on) set.add(n); else set.delete(n);
            _meetingDraft.attendees = meetingStaffList().filter(x => set.has(x));
            cb.parentElement.classList.toggle('on', on);
            _syncMeetingAllBtn();
        });
    });

    const reviewBtn = document.getElementById('meetingReviewBtn');
    if (reviewBtn) reviewBtn.addEventListener('click', () => openMeetingReview());
    const reviewSel = document.getElementById('meetingReviewSelect');
    if (reviewSel) reviewSel.addEventListener('change', () => {
        _meetingReviewId = Number(reviewSel.value) || null;
        renderMeetingReviewPanel();
    });

    const allBtn = document.getElementById('meetingAttAll');
    if (allBtn) allBtn.addEventListener('click', () => {
        const everyone = meetingStaffList().every(n => _meetingDraft.attendees.includes(n));
        _meetingDraft.attendees = everyone ? [] : meetingStaffList().slice();
        document.querySelectorAll('#meetingAttendees input[data-att]').forEach(cb => {
            cb.checked = !everyone;
            cb.parentElement.classList.toggle('on', !everyone);
        });
        _syncMeetingAllBtn();
    });

    // 안건/결정 목록: 추가·삭제·순서변경 시 전체가 아니라 이 목록만 다시 그린다
    // (전체 재렌더는 아래 점검 패널·보드까지 재로딩돼 화면이 밀림)
    const bindList = (kind, key, check) => {
        const lower = kind.toLowerCase();
        const listEl = document.getElementById('meeting' + kind + 'List');
        if (!listEl) { const ab = document.getElementById('meeting' + kind + 'Add'); if (!ab) return; }

        const rerender = () => {
            if (!listEl) return;
            listEl.innerHTML = _meetingListRowsHtml(kind, _meetingDraft[key], check);
            bindRows();
        };
        _meetingListRerender[kind] = rerender; // 외부(AI 채우기)에서 이 목록만 다시 그릴 수 있게

        function bindRows() {
            if (!listEl) return;
            listEl.querySelectorAll(`[data-${lower}-i]`).forEach(inp => {
                inp.addEventListener('input', () => {
                    const i = Number(inp.dataset[lower + 'I']);
                    if (check) _meetingDraft[key][i].text = inp.value;
                    else _meetingDraft[key][i] = inp.value;
                });
            });
            if (check) {
                listEl.querySelectorAll(`[data-${lower}-check]`).forEach(cb => {
                    cb.addEventListener('change', () => {
                        _meetingDraft[key][Number(cb.dataset[lower + 'Check'])].done = cb.checked;
                        cb.closest('.meeting-list-row').classList.toggle('item-done', cb.checked);
                        _meetingDirty = true;
                    });
                });
            }
            listEl.querySelectorAll(`[data-${lower}-del]`).forEach(btn => {
                btn.addEventListener('click', () => {
                    _meetingDraft[key].splice(Number(btn.dataset[lower + 'Del']), 1);
                    _meetingDirty = true;
                    rerender();
                });
            });
            let dragFrom = null;
            listEl.querySelectorAll('.meeting-drag-handle').forEach(h => {
                h.addEventListener('dragstart', (e) => {
                    dragFrom = Number(h.dataset[lower + 'Drag']);
                    e.dataTransfer.effectAllowed = 'move';
                    try { e.dataTransfer.setData('text/plain', String(dragFrom)); } catch (_) {}
                    h.closest('.meeting-list-row').classList.add('mlr-dragging');
                });
                h.addEventListener('dragend', () => {
                    dragFrom = null;
                    listEl.querySelectorAll('.meeting-list-row').forEach(r => r.classList.remove('mlr-dragging', 'mlr-over'));
                });
            });
            listEl.querySelectorAll('.meeting-list-row').forEach(row => {
                row.addEventListener('dragover', (e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; row.classList.add('mlr-over'); });
                row.addEventListener('dragleave', () => row.classList.remove('mlr-over'));
                row.addEventListener('drop', (e) => {
                    e.preventDefault();
                    row.classList.remove('mlr-over');
                    let from = dragFrom;
                    if (from == null) { const d = Number(e.dataTransfer.getData('text/plain')); from = isNaN(d) ? null : d; }
                    const to = Number(row.dataset[lower + 'Row']);
                    if (from == null || isNaN(from) || isNaN(to) || from === to) return;
                    const arr = _meetingDraft[key];
                    const [moved] = arr.splice(from, 1);
                    arr.splice(to, 0, moved);
                    _meetingDirty = true;
                    rerender();
                });
            });
        }

        bindRows();
        const addBtn = document.getElementById('meeting' + kind + 'Add');
        if (addBtn) addBtn.addEventListener('click', () => {
            _meetingDraft[key].push(check ? { text: '', done: false } : '');
            _meetingDirty = true;
            rerender();
            const inputs = listEl ? listEl.querySelectorAll(`[data-${lower}-i]`) : [];
            const last = inputs[inputs.length - 1];
            if (last) last.focus({ preventScroll: true }); // 포커스만, 화면 스크롤 안 함
        });
    };
    bindList('Agenda', 'agenda', true);
    bindList('Decisions', 'decisions', false);
    _bindMeetingContentImages();
    const aiBtn = document.getElementById('meetingAiBtn');
    if (aiBtn) aiBtn.addEventListener('click', aiFillMeeting);

    // 어디든 손대면 "미저장" 표시 (저장 시 해제).
    // #meetingsBody는 재렌더돼도 유지되므로 리스너는 딱 한 번만 단다.
    const box = document.getElementById('meetingsBody');
    if (!box.dataset.dirtyBound) {
        box.dataset.dirtyBound = '1';
        ['input', 'change'].forEach(ev => box.addEventListener(ev, () => {
            if (_meetingEditingId !== undefined) _meetingDirty = true;
        }));
    }
}

// 논의 내용에 이미지 붙여넣기 / 끌어다 놓기 / 파일 선택
function _bindMeetingContentImages() {
    const ce = document.getElementById('meetingContent');
    if (!ce) return;

    // 저장된 내용을 다시 열 때: 이미지 래퍼를 원자 요소로(커서 진입·타이핑 방지) + 리사이즈 유지
    ce.querySelectorAll('.mtg-img').forEach(w => w.setAttribute('contenteditable', 'false'));

    ce.addEventListener('paste', (e) => {
        const files = [...((e.clipboardData && e.clipboardData.files) || [])].filter(f => f.type.startsWith('image/'));
        if (!files.length) return;           // 글자 붙여넣기는 기본 동작에 맡긴다
        e.preventDefault();
        _meetingUploadImages(files);
    });

    ce.addEventListener('dragover', (e) => { e.preventDefault(); ce.classList.add('drag'); });
    ce.addEventListener('dragleave', () => ce.classList.remove('drag'));
    ce.addEventListener('drop', (e) => {
        ce.classList.remove('drag');
        const files = [...((e.dataTransfer && e.dataTransfer.files) || [])].filter(f => f.type.startsWith('image/'));
        if (!files.length) return;
        e.preventDefault();
        _meetingUploadImages(files);
    });

    const picker = document.getElementById('meetingImageFile');
    if (picker) picker.addEventListener('change', () => {
        const files = [...picker.files].filter(f => f.type.startsWith('image/'));
        picker.value = '';
        if (files.length) _meetingUploadImages(files);
    });
}

// 커서 위치(없으면 맨 끝)에 노드를 넣는다.
function _meetingInsertNode(node) {
    const ce = document.getElementById('meetingContent');
    if (!ce) return;
    const sel = window.getSelection();
    if (sel && sel.rangeCount && ce.contains(sel.anchorNode)) {
        const range = sel.getRangeAt(0);
        range.deleteContents();
        range.insertNode(node);
        range.setStartAfter(node);
        range.collapse(true);
        sel.removeAllRanges();
        sel.addRange(range);
    } else {
        ce.appendChild(node);
    }
}

const MEETING_IMAGE_MAX_BYTES = 10 * 1024 * 1024;

async function _meetingUploadImages(files) {
    for (const file of files) {
        if (file.size > MEETING_IMAGE_MAX_BYTES) {
            showToast('이미지가 너무 큽니다 (10MB 이하): ' + (file.name || '붙여넣은 이미지'));
            continue;
        }
        // 업로드 중 자리표시자 — 실패하면 지운다
        const ph = document.createElement('span');
        ph.className = 'meeting-img-uploading';
        ph.textContent = '이미지 업로드 중…';
        ph.setAttribute('contenteditable', 'false');
        _meetingInsertNode(ph);
        try {
            const url = await uploadPlanningImage(file);
            // 리사이즈 가능한 래퍼로 감싼다(기본 500px, 모서리 드래그로 조절)
            const wrap = document.createElement('span');
            wrap.className = 'mtg-img';
            wrap.setAttribute('contenteditable', 'false');
            wrap.style.width = '500px';
            const img = document.createElement('img');
            img.alt = '';
            img.onload = () => { if (img.naturalWidth && img.naturalWidth < 500) wrap.style.width = img.naturalWidth + 'px'; };
            img.src = url;
            wrap.appendChild(img);
            ph.replaceWith(wrap);
        } catch (e) {
            console.error('회의록 이미지 업로드 실패', e);
            ph.remove();
            showToast('이미지 업로드 실패: ' + ((e && e.message) || e));
        }
    }
    _readMeetingFields(); // 삽입된 이미지를 초안에 반영
}

// 화면의 입력값을 초안으로 옮긴다(가공 없이).
// 재렌더 전에 반드시 호출 — 안 그러면 아직 초안에 없는 입력이 날아간다.
function _readMeetingFields() {
    if (!_meetingDraft || !document.getElementById('meetingTitle')) return;
    const v = (id) => (document.getElementById(id) || {}).value || '';
    _meetingDraft.title = v('meetingTitle');
    _meetingDraft.meetAt = v('meetingMeetAt');
    _meetingDraft.location = v('meetingLocation');
    _meetingDraft.externalAttendees = v('meetingExternal');
    _meetingDraft.client = v('meetingClient');
    _meetingDraft.status = v('meetingStatus');
    const ce = document.getElementById('meetingContent');
    if (ce) _meetingDraft.content = ce.innerHTML;
    _meetingDraft.isPrivate = !!(document.getElementById('meetingPrivate') || {}).checked;
}

// 저장 직전용 — 필드를 읽고 공백 정리 + 빈 안건/결정 제거.
function _readMeetingForm() {
    _readMeetingFields();
    _meetingDraft.title = (_meetingDraft.title || '').trim();
    _meetingDraft.location = (_meetingDraft.location || '').trim();
    _meetingDraft.externalAttendees = (_meetingDraft.externalAttendees || '').trim();
    _meetingDraft.client = (_meetingDraft.client || '').trim();
    _meetingDraft.agenda = _meetingDraft.agenda
        .map(it => ({ text: ((it && it.text) || '').trim(), done: !!(it && it.done) }))
        .filter(it => it.text);
    _meetingDraft.decisions = _meetingDraft.decisions.map(s => (s || '').trim()).filter(Boolean);
    // 붙여넣은 HTML을 정화하고, 업로드 중이던 자리표시자는 버린다
    _meetingDraft.content = planningSanitizeHtml(
        (_meetingDraft.content || '').replace(/<span class="meeting-img-uploading"[^>]*>[\s\S]*?<\/span>/g, '')
    );
}

// ===== 회의록 자동 저장 =====
// 30초마다, 바뀐 내용이 있을 때만 조용히 저장한다.
// 화면을 다시 그리지 않는다 — 재렌더하면 입력 중 커서가 튄다.
const MEETING_AUTOSAVE_MS = 30000;
let _meetingAutoSaveTimer = null;
let _meetingAutoSaving = false;
let _meetingAutoSaveFails = 0;

function startMeetingAutoSave() {
    stopMeetingAutoSave();
    _meetingAutoSaveFails = 0;
    _meetingAutoSaveTimer = setInterval(() => { autoSaveMeeting(); }, MEETING_AUTOSAVE_MS);
}
function stopMeetingAutoSave() {
    if (_meetingAutoSaveTimer) { clearInterval(_meetingAutoSaveTimer); _meetingAutoSaveTimer = null; }
}
function _setAutoSaveStatus(text, color) {
    const el = document.getElementById('meetingAutoSaveStatus');
    if (!el) return;
    el.textContent = text;
    el.style.color = color || 'var(--gray-500)';
}
// 저장용 정리본을 만든다 — _meetingDraft 를 건드리지 않는다.
// (빈 안건 행을 draft에서 지우면 화면의 입력칸과 인덱스가 어긋나 오작동한다)
function _meetingCleanCopy() {
    _readMeetingFields();
    const d = _meetingDraft;
    return Object.assign({}, d, {
        title: (d.title || '').trim(),
        location: (d.location || '').trim(),
        externalAttendees: (d.externalAttendees || '').trim(),
        client: (d.client || '').trim(),
        agenda: (d.agenda || []).map(it => ({ text: ((it && it.text) || '').trim(), done: !!(it && it.done) })).filter(it => it.text),
        decisions: (d.decisions || []).map(s => (s || '').trim()).filter(Boolean),
        content: planningSanitizeHtml((d.content || '').replace(/<span class="meeting-img-uploading"[^>]*>[\s\S]*?<\/span>/g, '')),
    });
}

async function autoSaveMeeting() {
    if (_meetingEditingId === undefined || !_meetingDraft) { stopMeetingAutoSave(); return; }
    if (_meetingAutoSaving || !_meetingDirty) return;
    if (!currentUser || !currentUser.name || !_meetingCanEdit()) return;
    if (document.querySelector('#meetingContent .meeting-img-uploading')) return; // 이미지 업로드 끝나면 다음 주기에
    const clean = _meetingCleanCopy();
    if (!clean.title) { _setAutoSaveStatus('제목을 입력하면 자동 저장됩니다'); return; }

    _meetingAutoSaving = true;
    _setAutoSaveStatus('자동 저장 중…');
    try {
        if (!clean.author) clean.author = (currentUser && currentUser.name) || '';
        const payload = _meetingToDb(clean);
        if (_meetingEditingId) {
            const { data, error } = await sb.from('meetings').update(payload).eq('id', _meetingEditingId).select('id');
            if (error) throw error;
            if (!data || !data.length) throw new Error('수정 권한 없음');
        } else {
            const { data, error } = await sb.from('meetings').insert(payload).select().single();
            if (error) throw error;
            _meetingEditingId = data.id;
            _meetingDraft.id = data.id;
            if (!_meetingDraft.author) _meetingDraft.author = clean.author;
        }
        await saveMeetingActions();
        _meetingDirty = false;
        _meetingAutoSaveFails = 0;
        const t = new Date();
        const hh = String(t.getHours()).padStart(2, '0'), mm = String(t.getMinutes()).padStart(2, '0');
        _setAutoSaveStatus(`자동 저장됨 ${hh}:${mm}`, 'var(--green)');
    } catch (e) {
        console.error('autoSaveMeeting failed', e);
        _meetingAutoSaveFails++;
        _setAutoSaveStatus('자동 저장 실패 — 저장 버튼을 눌러주세요', 'var(--red)');
        // 계속 실패하면(DB 차단 등) 그만 두드린다
        if (_meetingAutoSaveFails >= 3) stopMeetingAutoSave();
    } finally {
        _meetingAutoSaving = false;
    }
}

async function saveMeeting() {
    if (document.querySelector('#meetingContent .meeting-img-uploading')) {
        showToast('이미지 업로드가 끝난 뒤에 저장해주세요');
        return;
    }
    _readMeetingForm();
    if (!_meetingDraft.title) { showToast('제목을 입력해주세요'); return; }
    if (!currentUser || !currentUser.name) { showToast('로그인이 필요합니다'); return; }
    const btn = document.getElementById('meetingSaveBtn');
    btn.disabled = true; btn.textContent = '저장 중…';
    try {
        if (!_meetingDraft.author) _meetingDraft.author = (currentUser && currentUser.name) || '';
        const payload = _meetingToDb(_meetingDraft);
        if (_meetingEditingId) {
            // .select()로 반환 행을 확인한다 — RLS가 막으면 에러 없이 0건이 온다
            const { data, error } = await sb.from('meetings').update(payload).eq('id', _meetingEditingId).select('id');
            if (error) throw error;
            if (!data || !data.length) throw new Error('수정 권한이 없습니다 (작성자와 관리자만 수정 가능)');
        } else {
            const { data, error } = await sb.from('meetings').insert(payload).select().single();
            if (error) throw error;
            _meetingEditingId = data.id;
            _meetingDraft.id = data.id;
        }
        await saveMeetingActions();
        _meetingDirty = false;
        showToast('저장되었습니다');
        renderMeetingEditor();
    } catch (e) {
        console.error('saveMeeting failed', e);
        showToast('저장 실패: ' + (e.message || e));
    } finally {
        btn.disabled = false; btn.textContent = '저장';
    }
}

async function deleteMeeting() {
    if (!_meetingEditingId) return;
    if (!confirm('이 회의록을 삭제할까요? 액션아이템도 함께 지워집니다. (이미 보낸 일일계획표 할 일은 남습니다)')) return;
    const { data, error } = await sb.from('meetings').delete().eq('id', _meetingEditingId).select('id');
    if (error) { console.error(error); showToast('삭제 실패: ' + error.message); return; }
    if (!data || !data.length) { showToast('삭제 권한이 없습니다 (작성자와 관리자만 삭제 가능)'); return; }
    showToast('삭제되었습니다');
    _meetingDirty = false;
    closeMeetingEditor();
}

async function loadMeetingActions(meetingId) {
    _meetingActions = [];
    _meetingActionDone = {};
    if (!meetingId) return;
    const { data, error } = await sb.from('meeting_actions')
        .select('*').eq('meeting_id', meetingId).order('id', { ascending: true });
    if (error) { console.error(error); showToast('액션아이템 불러오기 실패: ' + error.message); return; }
    _meetingActions = (data || []).map(a => ({
        id: a.id, task: a.task || '', assignee: a.assignee || '',
        dueDate: a.due_date || '', dailyTaskId: a.daily_task_id || null
    }));
    // 전송된 항목의 완료 여부는 daily_tasks 가 원본
    const ids = _meetingActions.map(a => a.dailyTaskId).filter(Boolean);
    if (ids.length) {
        const { data: tasks } = await sb.from('daily_tasks').select('id, done').in('id', ids);
        (tasks || []).forEach(t => { _meetingActionDone[t.id] = !!t.done; });
    }
}

// 🤖 논의 내용을 AI가 읽고 결정사항·액션아이템을 자동으로 채운다
async function aiFillMeeting() {
    const btn = document.getElementById('meetingAiBtn');
    const ce = document.getElementById('meetingContent');
    const content = ce ? (ce.innerText || '').trim() : '';
    if (content.length < 5) { showToast('먼저 논의 내용을 작성해주세요'); return; }
    const hasExisting = (_meetingDraft.decisions && _meetingDraft.decisions.some(d => (d || '').trim()))
        || _meetingActions.some(a => (a.task || '').trim());
    if (hasExisting && !confirm('AI가 정리한 결정사항·액션아이템을 기존 목록에 추가할까요?')) return;

    btn.disabled = true; const old = btn.textContent; btn.textContent = '🤖 정리 중...';
    try {
        const { data: sess } = await sb.auth.getSession();
        const token = sess && sess.session && sess.session.access_token;
        if (!token) { showToast('세션이 만료됐습니다. 다시 로그인하세요'); btn.disabled = false; btn.textContent = old; return; }
        const attendees = (_meetingDraft.attendees || []).slice();
        const res = await fetch('/api/meeting-summarize', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
            body: JSON.stringify({ content, attendees, today: getTodayStr() }),
        });
        const data = await res.json();
        if (!res.ok) { showToast('AI 정리 실패: ' + (data.error || ('오류 ' + res.status))); btn.disabled = false; btn.textContent = old; return; }
        const decisions = Array.isArray(data.decisions) ? data.decisions : [];
        const actionItems = Array.isArray(data.actionItems) ? data.actionItems : [];
        // 결정사항 추가 + 목록만 재렌더
        if (!Array.isArray(_meetingDraft.decisions)) _meetingDraft.decisions = [];
        decisions.forEach(d => { if (d && String(d).trim()) _meetingDraft.decisions.push(String(d).trim()); });
        if (_meetingListRerender.Decisions) _meetingListRerender.Decisions();
        // 액션아이템 추가 (담당자는 선택 옵션에 있는 이름만 채택, 없으면 빈칸)
        const opts = new Set(assigneeOptionList());
        actionItems.forEach(a => {
            const assignee = opts.has(a.assignee) ? a.assignee : '';
            _meetingActions.push({ id: null, task: a.task, assignee, dueDate: a.dueDate || '', dailyTaskId: null });
        });
        renderMeetingActions();
        _meetingDirty = true;
        if (!decisions.length && !actionItems.length) showToast('AI가 뽑을 결정·액션이 없다고 판단했습니다');
        else showToast(`AI 정리 완료 — 결정 ${decisions.length}개, 액션 ${actionItems.length}개 추가됨`);
        btn.disabled = false; btn.textContent = old;
    } catch (e) {
        console.error('aiFillMeeting error', e);
        showToast('오류: ' + ((e && e.message) || e));
        btn.disabled = false; btn.textContent = old;
    }
}

function renderMeetingActions() {
    const card = document.getElementById('meetingActionsCard');
    if (!card) return;
    const sent = _meetingActions.filter(a => a.dailyTaskId).length;
    const unsent = _meetingActions.filter(a => !a.dailyTaskId && a.task.trim() && a.assignee).length;

    card.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
        <h3 style="margin:0">액션아이템 <span style="font-weight:400;color:var(--gray-500);font-size:13px">전송 ${sent} / 전체 ${_meetingActions.length}</span></h3>
        <button class="btn-primary" id="meetingSendBtn" ${unsent ? '' : 'disabled'}>일일계획표로 보내기${unsent ? ' (' + unsent + ')' : ''}</button>
      </div>
      <table class="data-table"><thead><tr>
        <th>할 일</th><th style="width:130px">담당자</th><th style="width:150px">마감일</th><th style="width:110px">상태</th><th style="width:50px"></th>
      </tr></thead><tbody id="meetingActionsTbody">
        ${_meetingActions.map((a, i) => {
            let state = '미전송';
            if (a.dailyTaskId) state = _meetingActionDone[a.dailyTaskId] ? '✅ 완료' : '📤 전송됨';
            const locked = !!a.dailyTaskId;
            return `<tr>
              <td><input type="text" data-act-task="${i}" value="${escHtml(a.task)}" ${locked ? 'disabled' : ''}></td>
              <td><select data-act-assignee="${i}" ${locked ? 'disabled' : ''}>
                <option value="">선택</option>
                ${assigneeOptionList().map(n => `<option${n === a.assignee ? ' selected' : ''}>${n}</option>`).join('')}
              </select></td>
              <td><input type="date" data-act-due="${i}" value="${escHtml(a.dueDate)}" ${locked ? 'disabled' : ''}></td>
              <td>${state}</td>
              <td>${locked ? '' : `<button type="button" class="meeting-del" data-act-del="${i}">✕</button>`}</td>
            </tr>`;
        }).join('')}
      </tbody></table>
      <button type="button" class="btn-ghost" id="meetingActionAdd" style="margin-top:10px">+ 액션아이템 추가</button>
      <p style="margin-top:10px;font-size:12px;color:var(--gray-500)">전송된 항목은 여기서 수정할 수 없습니다. 완료 체크는 <b>일일계획표</b>에서 하세요.</p>`;

    card.querySelectorAll('[data-act-task]').forEach(el => el.addEventListener('input', () => { _meetingActions[Number(el.dataset.actTask)].task = el.value; }));
    card.querySelectorAll('[data-act-assignee]').forEach(el => el.addEventListener('change', () => { _meetingActions[Number(el.dataset.actAssignee)].assignee = el.value; renderMeetingActions(); }));
    card.querySelectorAll('[data-act-due]').forEach(el => el.addEventListener('change', () => { _meetingActions[Number(el.dataset.actDue)].dueDate = el.value; }));
    card.querySelectorAll('[data-act-del]').forEach(el => el.addEventListener('click', async () => {
        if (el.disabled) return;
        el.disabled = true;
        const a = _meetingActions[Number(el.dataset.actDel)];
        if (!a) return;
        if (a.id) {
            const { error } = await sb.from('meeting_actions').delete().eq('id', a.id);
            if (error) { showToast('삭제 실패: ' + error.message); el.disabled = false; return; }
        }
        const idx = _meetingActions.indexOf(a);
        if (idx >= 0) _meetingActions.splice(idx, 1);
        renderMeetingActions();
    }));
    card.querySelector('#meetingActionAdd').addEventListener('click', () => {
        _meetingActions.push({ id: null, task: '', assignee: '', dueDate: '', dailyTaskId: null });
        renderMeetingActions();
    });
    card.querySelector('#meetingSendBtn').addEventListener('click', () => sendMeetingActionsToDaily(_meetingEditingId));

    // 읽기 전용 회의록이면 액션아이템도 잠근다
    if (!_meetingCanEdit()) {
        card.querySelectorAll('input, select, button').forEach(el => { el.disabled = true; });
    }
}

async function saveMeetingActions() {
    const mid = _meetingEditingId;
    if (!mid) return;
    for (const a of _meetingActions) {
        const task = (a.task || '').trim();
        if (!task && !a.id) continue;          // 아직 저장 안 된 빈 행은 무시
        if (a.id && a.dailyTaskId) continue;   // 전송된 항목은 잠금
        const row = { meeting_id: mid, task, assignee: a.assignee || null, due_date: a.dueDate || null };
        if (a.id) {
            const { error } = await sb.from('meeting_actions').update(row).eq('id', a.id);
            if (error) throw error;
        } else {
            const { data, error } = await sb.from('meeting_actions').insert(row).select().single();
            if (error) throw error;
            a.id = data.id;
        }
    }
}

// 편집 화면 하단: 전 직원 일일계획표를 한 줄로 (읽기 전용)
// 미완료 할 일은 날짜와 상관없이 전부, 완료 할 일은 선택한 날짜 것만 보여준다.
async function renderMeetingDailyBoard() {
    const card = document.getElementById('meetingDailyCard');
    if (!card) return;
    const date = _meetingDailyDate || getTodayStr();
    const today = getTodayStr();

    card.innerHTML = `
      <div class="meeting-daily-head">
        <h3 style="margin:0">📋 오늘 해야할 일 <span style="font-weight:400;color:var(--gray-500);font-size:13px">— 오늘까지 밀린 미완료 + 선택한 날짜의 완료건</span></h3>
        <div style="display:flex;gap:8px;align-items:center">
          <input type="date" id="meetingDailyDate" value="${escHtml(date)}">
          <button type="button" class="btn-ghost" id="meetingDailyToday">오늘</button>
        </div>
      </div>
      <div class="meeting-daily-board" id="meetingDailyBoard">
        <div style="padding:24px;color:var(--gray-500);font-size:13px">불러오는 중…</div>
      </div>`;

    const dateInput = card.querySelector('#meetingDailyDate');
    dateInput.addEventListener('change', () => {
        if (!dateInput.value) return;
        _meetingDailyDate = dateInput.value;
        renderMeetingDailyBoard();
    });
    card.querySelector('#meetingDailyToday').addEventListener('click', () => {
        _meetingDailyDate = getTodayStr();
        renderMeetingDailyBoard();
    });

    const cols = 'id, task, assignee, done, priority, client, date, linked_group';
    // ① 미완료는 날짜 무관 전부  ② 완료는 선택한 날짜 것만
    const [undone, doneToday] = await Promise.all([
        sb.from('daily_tasks').select(cols).eq('done', false),
        sb.from('daily_tasks').select(cols).eq('done', true).eq('date', date)
    ]);

    const board = document.getElementById('meetingDailyBoard');
    if (!board || _meetingDailyDate !== date) return; // 날짜를 다시 바꿨으면 늦게 온 응답은 버린다
    const error = undone.error || doneToday.error;
    if (error) {
        console.error('renderMeetingDailyBoard failed', error);
        board.innerHTML = `<div style="padding:24px;color:var(--red);font-size:13px">오늘 해야할 일을 불러오지 못했습니다 — ${escHtml(error.message)}</div>`;
        return;
    }

    // 미완료 중 미래 일정(오늘 이후)은 제외 — 지금 챙길 일만 보이게
    const undoneRows = (undone.data || []).filter(t => !(t.date && t.date > today));
    const rows = undoneRows.concat(doneToday.data || []);
    board.innerHTML = MEETING_DAILY_COLUMNS.map(col => {
        const list = rows.filter(t => t.assignee === col).sort((a, b) =>
            (a.done - b.done)                              // 미완료 먼저
            || String(a.date || '').localeCompare(String(b.date || '')) // 오래된 것 먼저
            || ((b.id || 0) - (a.id || 0)));
        const left = list.filter(t => !t.done).length;
        const overdue = list.filter(t => !t.done && t.date && t.date < today).length;
        const body = list.length
            ? list.map(t => {
                const late = !t.done && t.date && t.date < today;
                const other = t.date && t.date !== date;
                // 지연 건은 날짜 대신 "N일 지연"으로 (더 직관적)
                const daysLate = late ? Math.round((Date.parse(today) - Date.parse(t.date)) / 86400000) : 0;
                const badge = late
                    ? `<span class="mdt-date late">${daysLate}일 지연</span>`
                    : (other ? `<span class="mdt-date">${escHtml(t.date.slice(5))}</span>` : '');
                return `
                <label class="meeting-daily-task${t.done ? ' done' : ''}">
                  <input type="checkbox" class="mdt-check" data-task-id="${t.id}" ${t.done ? 'checked' : ''}>
                  <span class="mdt-pri">${escHtml((t.priority || '').slice(0, 2))}</span>
                  <span class="mdt-text">${escHtml(t.task || '')}</span>
                  ${badge}
                  ${t.client ? `<span class="mdt-client">${escHtml(t.client)}</span>` : ''}
                </label>`;
            }).join('')
            : '<div class="meeting-daily-empty">없음</div>';
        return `
          <div class="meeting-daily-col">
            <div class="meeting-daily-col-head">
              <b>${escHtml(col)}</b>
              <span class="mdt-count${left ? '' : ' zero'}">${left ? left + '건 남음' : '완료'}</span>
              ${overdue ? `<span class="mdt-overdue" title="마감일이 지난 미완료">지연 ${overdue}</span>` : ''}
            </div>
            <div class="meeting-daily-col-body">${body}</div>
          </div>`;
    }).join('');

    // 컬럼 헤더의 "N건 남음 / 완료 / 지연 N"을 현재 rows 상태로 다시 계산
    const refreshCounts = () => {
        [...board.querySelectorAll('.meeting-daily-col')].forEach(colEl => {
            const name = colEl.querySelector('b').textContent;
            const list = rows.filter(t => t.assignee === name);
            const left = list.filter(t => !t.done).length;
            const overdue = list.filter(t => !t.done && t.date && t.date < today).length;
            const cnt = colEl.querySelector('.mdt-count');
            cnt.textContent = left ? left + '건 남음' : '완료';
            cnt.classList.toggle('zero', !left);
            let od = colEl.querySelector('.mdt-overdue');
            if (overdue) {
                if (!od) { od = document.createElement('span'); od.className = 'mdt-overdue'; od.title = '마감일이 지난 미완료'; colEl.querySelector('.meeting-daily-col-head').appendChild(od); }
                od.textContent = '지연 ' + overdue;
            } else if (od) { od.remove(); }
        });
    };

    // 완료된 항목은 칸 아래로 (렌더 정렬과 동일: 미완료 먼저 → 오래된 날짜 → 최신 id)
    const reorderColumnBody = (bodyEl) => {
        if (!bodyEl) return;
        [...bodyEl.querySelectorAll('.meeting-daily-task')]
            .map(n => ({ n, t: rows.find(x => x.id === Number(n.querySelector('.mdt-check').dataset.taskId)) }))
            .filter(o => o.t)
            .sort((A, B) => (A.t.done - B.t.done)
                || String(A.t.date || '').localeCompare(String(B.t.date || ''))
                || ((B.t.id || 0) - (A.t.id || 0)))
            .forEach(o => bodyEl.appendChild(o.n)); // 정렬 순서대로 다시 붙여 재배치
    };

    // 체크박스로 완료 표시 — 원본은 일일계획표와 같은 daily_tasks.done
    board.querySelectorAll('.mdt-check').forEach(cb => {
        cb.addEventListener('change', async () => {
            const id = Number(cb.dataset.taskId);
            const t = rows.find(x => x.id === id);
            if (!t) return;
            const newDone = cb.checked;
            const nowIso = newDone ? new Date().toISOString() : null;
            const rowEl = cb.closest('.meeting-daily-task');
            const bodyEl = cb.closest('.meeting-daily-col-body');
            t.done = newDone;                      // 낙관적 반영
            rowEl.classList.toggle('done', newDone);
            refreshCounts();
            reorderColumnBody(bodyEl);             // 체크한 항목을 아래로 내림
            cb.disabled = true;
            // 연동 그룹(마감일 복사 등)까지 함께
            const { error } = t.linked_group
                ? await sb.from('daily_tasks').update({ done: newDone, completed_at: nowIso }).eq('linked_group', t.linked_group)
                : await sb.from('daily_tasks').update({ done: newDone, completed_at: nowIso }).eq('id', id);
            cb.disabled = false;
            if (error) {
                console.error('일일계획표 완료 저장 실패', error);
                showToast('완료 상태 저장 실패: ' + error.message);
                t.done = !newDone; cb.checked = !newDone; rowEl.classList.toggle('done', !newDone); refreshCounts(); reorderColumnBody(bodyEl);
                return;
            }
            // 이미 로드된 일일계획표 화면과 어긋나지 않게 로컬 배열도 맞춘다
            if (typeof dailyTasks !== 'undefined' && Array.isArray(dailyTasks)) {
                dailyTasks.forEach(dt => {
                    if (dt.id === id || (t.linked_group && dt.linkedGroup === t.linked_group)) { dt.done = newDone; dt.completedAt = nowIso; }
                });
            }
        });
    });
}

// YYYY-MM 을 delta개월 이동
function _meetingMonthShift(ym, delta) {
    let [y, mo] = ym.split('-').map(Number);
    mo += delta;
    while (mo < 1) { mo += 12; y--; }
    while (mo > 12) { mo -= 12; y++; }
    return y + '-' + String(mo).padStart(2, '0');
}

// 편집 화면 하단: 그 달의 전 직원 일정을 달력으로 (읽기 전용, 임원·구정두 제외)
async function renderMeetingMonthlyBoard() {
    const card = document.getElementById('meetingMonthlyCard');
    if (!card) return;
    const ym = _meetingMonth || getTodayStr().slice(0, 7);
    _meetingMonth = ym;
    const [y, mo] = ym.split('-').map(Number);
    const daysInMonth = new Date(y, mo, 0).getDate();     // mo는 1-based → 그 달 말일
    const firstWeekday = new Date(y, mo - 1, 1).getDay(); // 0=일
    const first = ym + '-01';
    const last = ym + '-' + String(daysInMonth).padStart(2, '0');
    const today = getTodayStr();

    card.innerHTML = `
      <div class="meeting-daily-head">
        <h3 style="margin:0">🗓 월간 계획표 <span style="font-weight:400;color:var(--gray-500);font-size:13px">— 담당자별 일정 한눈에</span></h3>
        <div style="display:flex;gap:6px;align-items:center">
          <button type="button" class="btn-ghost" id="meetingMonthPrev">‹</button>
          <span style="font-weight:700;font-size:14px;min-width:96px;text-align:center">${y}년 ${mo}월</span>
          <button type="button" class="btn-ghost" id="meetingMonthNext">›</button>
          <button type="button" class="btn-ghost" id="meetingMonthThis">이번 달</button>
        </div>
      </div>
      <div class="meeting-month-legend">
        ${MEETING_DAILY_COLUMNS.map(n => `<span class="mm-leg"><i style="background:${MEETING_ASSIGNEE_COLORS[n]}"></i>${escHtml(n)}</span>`).join('')}
      </div>
      <div class="meeting-month" id="meetingMonthGrid">
        <div class="meeting-month-loading">불러오는 중…</div>
      </div>`;

    card.querySelector('#meetingMonthPrev').addEventListener('click', () => { _meetingMonth = _meetingMonthShift(ym, -1); renderMeetingMonthlyBoard(); });
    card.querySelector('#meetingMonthNext').addEventListener('click', () => { _meetingMonth = _meetingMonthShift(ym, 1); renderMeetingMonthlyBoard(); });
    card.querySelector('#meetingMonthThis').addEventListener('click', () => { _meetingMonth = getTodayStr().slice(0, 7); renderMeetingMonthlyBoard(); });

    const { data, error } = await sb.from('daily_tasks')
        .select('id, task, assignee, done, date')
        .gte('date', first).lte('date', last);

    const grid = document.getElementById('meetingMonthGrid');
    if (!grid || _meetingMonth !== ym) return; // 달을 다시 바꿨으면 늦게 온 응답은 버린다
    if (error) {
        console.error('renderMeetingMonthlyBoard failed', error);
        grid.innerHTML = `<div class="meeting-month-loading" style="color:var(--red)">달력을 불러오지 못했습니다 — ${escHtml(error.message)}</div>`;
        return;
    }

    const byDay = {};
    (data || []).forEach(t => {
        if (!MEETING_DAILY_COLUMNS.includes(t.assignee)) return; // 임원·구정두 제외
        if (!t.date) return;
        (byDay[t.date] = byDay[t.date] || []).push(t);
    });

    const weekdays = ['일', '월', '화', '수', '목', '금', '토'];
    let cells = weekdays.map((w, i) => `<div class="mm-wd${i === 0 ? ' sun' : i === 6 ? ' sat' : ''}">${w}</div>`).join('');
    for (let i = 0; i < firstWeekday; i++) cells += '<div class="mm-cell mm-empty"></div>';
    for (let day = 1; day <= daysInMonth; day++) {
        const ds = ym + '-' + String(day).padStart(2, '0');
        const wd = (firstWeekday + day - 1) % 7;
        const tasks = (byDay[ds] || []).slice().sort((a, b) => (a.done - b.done));
        const chips = tasks.slice(0, 4).map(t =>
            `<div class="mm-task${t.done ? ' done' : ''}" style="border-left-color:${MEETING_ASSIGNEE_COLORS[t.assignee] || '#8b95a1'}" title="${escHtml(t.assignee + ' · ' + (t.task || ''))}">${escHtml(t.task || '')}</div>`).join('');
        const more = tasks.length > 4 ? `<div class="mm-more">+${tasks.length - 4}건</div>` : '';
        cells += `<div class="mm-cell${ds === today ? ' today' : ''}">
            <div class="mm-day${wd === 0 ? ' sun' : wd === 6 ? ' sat' : ''}">${day}</div>
            ${chips}${more}
          </div>`;
    }
    grid.innerHTML = cells;
}

async function sendMeetingActionsToDaily(meetingId) {
    if (!meetingId) { showToast('먼저 회의록을 저장해주세요'); return; }
    // 표에 입력만 하고 저장 안 한 항목이 있을 수 있으니 먼저 저장
    try { await saveMeetingActions(); } catch (e) { showToast('저장 실패: ' + (e.message || e)); return; }

    const targets = _meetingActions.filter(a => a.id && !a.dailyTaskId && (a.task || '').trim() && a.assignee);
    if (!targets.length) { showToast('보낼 항목이 없습니다 (담당자를 지정해주세요)'); return; }

    const btn = document.getElementById('meetingSendBtn');
    if (btn) { btn.disabled = true; btn.textContent = '전송 중…'; }

    let ok = 0, fail = 0, orphan = 0;
    for (const a of targets) {
        const saved = await dbInsertTask({
            task: a.task.trim(),
            date: a.dueDate || getTodayStr(),
            assignee: a.assignee,
            label: '회사 업무',
            client: _meetingDraft.client || '',
            note: '회의록: ' + (_meetingDraft.title || ''),
            priority: '🟡 보통',
            done: false
        });
        if (!saved || !saved.id) { fail++; continue; }
        const { error } = await sb.from('meeting_actions').update({ daily_task_id: saved.id }).eq('id', a.id);
        if (error) { console.error('daily_task_id 연결 실패', error); orphan++; continue; }
        a.dailyTaskId = saved.id;
        _meetingActionDone[saved.id] = false;
        ok++;
    }

    let msg = ok ? (ok + '건을 일일계획표로 보냈습니다') : '전송된 항목이 없습니다';
    if (fail) msg += ' · ' + fail + '건 실패';
    if (orphan) msg += ' · ' + orphan + '건은 할 일은 생성됐지만 연결에 실패했습니다. 다시 보내면 중복되니 일일계획표를 먼저 확인하세요.';
    showToast(msg);
    renderMeetingActions();
    renderMeetingDailyBoard(); // 방금 보낸 할 일이 아래 표에 바로 보이도록
}

// ── 지난 회의 이행 점검 ──────────────────────────────
// 버튼 클릭 시: 최근 회의 목록을 드롭다운에 채우고 최신 회의를 점검 대상으로 잡는다.
async function openMeetingReview() {
    const box = document.getElementById('meetingReviewBox');
    const sel = document.getElementById('meetingReviewSelect');
    const btn = document.getElementById('meetingReviewBtn');
    if (!box || !sel) return;
    if (btn) { btn.disabled = true; btn.textContent = '불러오는 중…'; }
    const { data, error } = await sb.from('meetings')
        .select('id, title, meet_at').order('meet_at', { ascending: false }).limit(30);
    if (btn) { btn.disabled = false; btn.textContent = '지난 회의 불러오기'; }
    if (error) { showToast('회의 목록 불러오기 실패: ' + error.message); return; }
    const list = (data || []).filter(m => m.id !== _meetingEditingId).slice(0, 20);
    if (!list.length) {
        box.innerHTML = '<div style="color:var(--gray-500);font-size:13px;padding:8px 0">불러올 지난 회의가 없습니다.</div>';
        return;
    }
    sel.innerHTML = list.map(m => `<option value="${m.id}">${escHtml(_meetingDateLabel(m.meet_at))} · ${escHtml(m.title || '(제목 없음)')}</option>`).join('');
    sel.style.display = '';
    if (btn) btn.style.display = 'none';
    if (!_meetingReviewId || !list.some(m => m.id === _meetingReviewId)) _meetingReviewId = list[0].id;
    sel.value = String(_meetingReviewId);
    renderMeetingReviewPanel();
}

async function renderMeetingReviewPanel() {
    const box = document.getElementById('meetingReviewBox');
    if (!box || !_meetingReviewId) return;
    box.innerHTML = '<div style="color:var(--gray-500);font-size:13px;padding:8px 0">불러오는 중…</div>';
    const rid = _meetingReviewId;
    const { data: acts, error } = await sb.from('meeting_actions')
        .select('id, task, assignee, daily_task_id, done').eq('meeting_id', rid).order('id');
    if (!document.getElementById('meetingReviewBox') || _meetingReviewId !== rid) return;
    if (error) { box.innerHTML = `<div style="color:var(--red);font-size:13px">불러오기 실패 — ${escHtml(error.message)}</div>`; return; }
    // 전송된 항목의 완료는 일일계획표가 원본, 미전송 항목은 meeting_actions.done
    const taskIds = (acts || []).map(a => a.daily_task_id).filter(Boolean);
    const doneMap = {};
    if (taskIds.length) {
        const { data: tasks } = await sb.from('daily_tasks').select('id, done').in('id', taskIds);
        (tasks || []).forEach(t => { doneMap[t.id] = !!t.done; });
    }
    // 지난 회의 안건 (완료 포함 전부 — 완료도 보이게)
    const { data: mrow } = await sb.from('meetings').select('agenda').eq('id', rid).single();
    if (!document.getElementById('meetingReviewBox') || _meetingReviewId !== rid) return;
    const agenda = _normMeetingAgenda(mrow && mrow.agenda);

    // daily_task_id가 있어도 연결된 일일계획표 항목이 삭제됐으면(doneMap에 없음) 미전송처럼 취급 → meeting_actions.done 사용
    const liveTask = (a) => a.daily_task_id != null && Object.prototype.hasOwnProperty.call(doneMap, a.daily_task_id);
    const isDone = (a) => liveTask(a) ? !!doneMap[a.daily_task_id] : !!a.done;
    const statusOf = (a) => isDone(a) ? 'done' : (liveTask(a) ? 'todo' : 'unsent');
    const byAssignee = {};
    (acts || []).forEach(a => { const k = a.assignee || '(미지정)'; (byAssignee[k] = byAssignee[k] || []).push(a); });
    const cols = assigneeOptionList().concat(['(미지정)']).filter(k => byAssignee[k] && byAssignee[k].length);

    if (!cols.length && !agenda.length) {
        box.innerHTML = '<div style="color:var(--gray-500);font-size:13px;padding:8px 0">이 회의엔 점검할 액션아이템·안건이 없습니다.</div>';
        return;
    }

    const already = (task, assignee) => _meetingActions.some(x => (x.task || '').trim() === (task || '').trim() && (x.assignee || '') === (assignee || ''));
    const carryBtn = (task, assignee) => {
        const dup = already(task, assignee);
        return `<button type="button" class="mrv-carry" data-task="${escHtml(task)}" data-assignee="${escHtml(assignee || '')}"${dup ? ' disabled' : ''}>${dup ? '추가됨' : '오늘로 ↗'}</button>`;
    };
    // kind: 'act'(액션아이템) | 'agenda'.  체크박스로 완료 토글, 완료돼도 목록 유지.
    const chk = (kind, ident, done) => `<input type="checkbox" class="mrv-chk" data-kind="${kind}" data-id="${escHtml(String(ident))}" ${done ? 'checked' : ''} title="완료 표시">`;

    const colHtml = cols.map(col => {
        const items = byAssignee[col].slice().sort((a, b) => {
            const rank = s => s === 'todo' ? 0 : s === 'unsent' ? 1 : 2;
            return rank(statusOf(a)) - rank(statusOf(b));
        });
        const left = items.filter(a => !isDone(a)).length;
        return `<div class="mrv-col">
            <div class="mrv-col-head"><b>${escHtml(col)}</b><span class="mrv-left${left ? '' : ' zero'}">${left ? left + '건 미이행' : '완료'}</span></div>
            <div class="mrv-col-body">${items.map(a => {
                const s = statusOf(a);
                return `<div class="mrv-item ${s}">
                    <div class="mrv-item-main">${chk('act', a.id, s === 'done')}<span class="mrv-text">${escHtml(a.task || '')}</span></div>
                    ${s !== 'done' ? carryBtn(a.task, a.assignee) : ''}
                </div>`;
            }).join('')}</div>
        </div>`;
    }).join('');

    const agendaHtml = agenda.length ? `
        <div class="mrv-agenda">
            <div class="mrv-agenda-title">지난 회의 안건 (담당자 미지정)</div>
            ${agenda.map((a, i) => `<div class="mrv-item ${a.done ? 'done' : 'unsent'}">
                <div class="mrv-item-main">${chk('agenda', i, a.done)}<span class="mrv-text">${escHtml(a.text)}</span></div>
                ${a.done ? '' : carryBtn(a.text, '')}
            </div>`).join('')}
        </div>` : '';

    box.innerHTML = `<div class="mrv-board">${colHtml || '<div style="color:var(--gray-500);font-size:13px">액션아이템 없음</div>'}</div>${agendaHtml}`;

    box.querySelectorAll('.mrv-carry').forEach(b => b.addEventListener('click', () => {
        if (b.disabled) return;
        _meetingActions.push({ id: null, task: b.dataset.task, assignee: b.dataset.assignee || '', dueDate: '', dailyTaskId: null });
        _meetingDirty = true;
        b.disabled = true; b.textContent = '추가됨';
        renderMeetingActions();
        showToast('오늘 액션아이템에 추가됨');
    }));

    // 체크박스 완료 토글 (완료돼도 목록에 남김)
    box.querySelectorAll('.mrv-chk').forEach(cb => cb.addEventListener('change', () => {
        toggleReviewDone(cb.dataset.kind, cb.dataset.id, cb.checked, cb, rid);
    }));
}

// 이행 점검 패널의 항목 완료 토글. act=액션아이템(전송건은 일일계획표, 미전송은 meeting_actions.done),
// agenda=지난 회의 안건(agenda[].done). 성공 시 패널 재렌더(항목은 유지).
async function toggleReviewDone(kind, ident, done, cb, rid) {
    cb.disabled = true;
    const nowIso = done ? new Date().toISOString() : null;
    try {
        if (kind === 'act') {
            const id = Number(ident);
            // meeting_actions.done 로 완료 저장 (권한 없어 0건이면 false)
            const writeActionDone = async () => {
                const { data: u, error } = await sb.from('meeting_actions').update({ done }).eq('id', id).select('id');
                if (error) throw error;
                return !!(u && u.length);
            };
            // 이 액션아이템이 전송됐는지(daily_task_id) 확인
            const { data: a } = await sb.from('meeting_actions').select('daily_task_id').eq('id', id).single();
            if (a && a.daily_task_id) {
                const { data: upd, error } = await sb.from('daily_tasks').update({ done, completed_at: nowIso }).eq('id', a.daily_task_id).select('id');
                if (error) throw error;
                // 연결된 일일계획표 항목이 삭제됐으면 0건 → meeting_actions.done 로 대체 저장
                if (!upd || !upd.length) {
                    if (!(await writeActionDone())) { showToast('처리 권한이 없습니다 (작성자·관리자만)'); cb.checked = !done; cb.disabled = false; return; }
                }
            } else {
                if (!(await writeActionDone())) { showToast('처리 권한이 없습니다 (작성자·관리자만)'); cb.checked = !done; cb.disabled = false; return; }
            }
        } else { // agenda
            const idx = Number(ident);
            const { data: m, error: er } = await sb.from('meetings').select('agenda').eq('id', rid).single();
            if (er) throw er;
            const agenda = _normMeetingAgenda(m && m.agenda);
            if (agenda[idx]) agenda[idx].done = done;
            const { data: upd, error } = await sb.from('meetings').update({ agenda }).eq('id', rid).select('id');
            if (error) throw error;
            if (!upd || !upd.length) { showToast('처리 권한이 없습니다 (작성자·관리자만)'); cb.checked = !done; cb.disabled = false; return; }
        }
        if (_meetingReviewId === rid) renderMeetingReviewPanel();
    } catch (e) {
        console.error('이행 점검 완료 토글 실패', e);
        showToast('저장 실패: ' + ((e && e.message) || e));
        cb.checked = !done; cb.disabled = false;
    }
}

// F2: 회의록 목록에서 새 회의록 바로 만들기
document.addEventListener('keydown', (e) => {
    if (e.key !== 'F2') return;
    const tab = document.getElementById('tab-meetings');
    if (!tab || !tab.classList.contains('active')) return;   // 회의록 탭이 아닐 때는 무시
    if (_meetingEditingId !== undefined) return;             // 이미 편집 중이면 무시
    const t = e.target;
    if (t && /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)) return; // 입력 중에는 무시
    e.preventDefault();
    openMeetingEditor(null);
});

// 회의록 편집 중 저장 안 하고 새로고침·창닫기 → 브라우저 기본 경고
window.addEventListener('beforeunload', (e) => {
    if (_meetingEditingId !== undefined && _meetingDirty) { e.preventDefault(); e.returnValue = ''; }
});

// 회의록 편집 중 사이드바로 다른 메뉴 이동 → 확인 후 이동
document.addEventListener('click', (e) => {
    if (_meetingEditingId === undefined || !_meetingDirty) return;
    const nav = e.target.closest && e.target.closest('.nav-item[data-tab]');
    if (!nav || nav.dataset.tab === 'meetings') return;
    if (!confirm('저장하지 않은 회의록 내용이 있습니다. 이동하면 사라집니다. 이동할까요?')) {
        e.preventDefault();
        e.stopPropagation();
        return;
    }
    _meetingDirty = false;
    _meetingEditingId = undefined;
    _meetingDraft = null;
    _meetingActions = [];
}, true);


// ============================================================
// 내 하루 (타임박스) — Brain dump → BIG 3 → 타임라인
// 데이터는 daily_tasks 공유: start_min(자정 기준 분, null=미배정), duration_min, big3_rank, category
// 일일계획표에 미래 날짜로 적은 일 = 예정 → 그 날짜가 되면 여기 Brain dump에 자동 표시
// ============================================================
const TBX_DAY_START = 6 * 60, TBX_DAY_END = 24 * 60;
const TBX_CATS = { work: '회사', client: '미팅', meet: '회의', me: '개인' };
const TBX_CAT_VAR = { work: 'var(--tbx-work)', client: 'var(--tbx-client)', meet: 'var(--tbx-meet)', me: 'var(--tbx-me)' };
const TBX_CAT_LABEL = { work: '회사 업무', client: '거래처 업무', meet: '회사 업무', me: '개인' };
let _tbxTasks = [];      // 내 할 일 (보는 날짜 전체 + 밀린 미완료)
let _tbxGran = 60;
let _tbxTimer = null;
let _tbxDate = null;     // 보고 있는 날짜(YYYY-MM-DD). null=오늘
let _tbxRoutines = [];   // 내 루틴 (매일 자동 생성)

function tbxViewDate() { return _tbxDate || getTodayStr(); }
function tbxIsToday() { return tbxViewDate() === getTodayStr(); }
function tbxFmtMD(ds) { return ds ? (Number(ds.slice(5,7)) + '/' + Number(ds.slice(8,10))) : ''; }
function tbxShiftDate(delta) {
    const d = new Date(tbxViewDate() + 'T00:00:00');
    d.setDate(d.getDate() + delta);
    _tbxDate = d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
    if (_tbxDate === getTodayStr()) _tbxDate = null;
    tbxEnter();
}
function tbxGoToday() { _tbxDate = null; tbxEnter(); }
function tbxRenderDateLabel() {
    const el = document.getElementById('tbxDateLabel');
    const btn = document.getElementById('tbxTodayBtn');
    if (!el) return;
    const vd = tbxViewDate(), today = getTodayStr();
    const d = new Date(vd + 'T00:00:00');
    const dow = '일월화수목금토'[d.getDay()];
    const diff = Math.round((d - new Date(today + 'T00:00:00')) / 86400000);
    const rel = diff === 0 ? '오늘' : diff === -1 ? '어제' : diff === 1 ? '내일' : diff === -2 ? '그제' : (diff < 0 ? (-diff) + '일 전' : diff + '일 후');
    el.textContent = tbxFmtMD(vd) + ' (' + dow + ') ' + rel;
    if (btn) btn.style.display = tbxIsToday() ? 'none' : '';
}

function tbxPxPerMin() { return _tbxGran === 60 ? 0.9 : 1.15; }
function tbxY(min) { return (min - TBX_DAY_START) * tbxPxPerMin(); }
function tbxMinOfY(y) { return TBX_DAY_START + Math.round(y / tbxPxPerMin()); }
function tbxSnap(min) { return Math.max(TBX_DAY_START, Math.min(TBX_DAY_END - _tbxGran, Math.round(min / _tbxGran) * _tbxGran)); }
function tbxFmt(min) { return `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`; }
function tbxNowMin() { const d = new Date(); return d.getHours() * 60 + d.getMinutes(); }

// "보고서 30분" → {title:'보고서', est:30, cat}. 카테고리는 단어로 추측, 기본 회사·1시간
function tbxParse(raw) {
    let title = raw.trim(), est = 60;
    const mh = title.match(/(\d+(?:\.\d+)?)\s*시간\s*$/);
    const mm = title.match(/(\d+)\s*분\s*$/);
    if (mh) { est = Math.round(parseFloat(mh[1]) * 60); title = title.slice(0, mh.index).trim(); }
    else if (mm) { est = parseInt(mm[1], 10); title = title.slice(0, mm.index).trim(); }
    est = Math.max(15, Math.min(240, Math.round(est / 15) * 15));
    let cat = 'work';
    if (/회의/.test(title)) cat = 'meet';
    else if (/미팅|방문|상담/.test(title)) cat = 'client';
    else if (/점심|저녁|운동|산책|병원|휴식|개인/.test(title)) cat = 'me';
    return { title: title || raw.trim(), est, cat };
}

// 파생 뷰: 오늘 블록 / 미배정(브레인덤프) — 과거 날짜의 start_min은 그날의 것이므로 무시
function tbxBlocks() { return _tbxTasks.filter(t => t.date === tbxViewDate() && t.start_min != null); }
function tbxInboxTasks() {
    if (tbxIsToday()) return _tbxTasks.filter(t => !t.done && !(t.date === getTodayStr() && t.start_min != null));
    return _tbxTasks.filter(t => t.date === tbxViewDate() && t.start_min == null && !t.done);
}
function tbxTopCount() { return _tbxTasks.filter(t => t.big3_rank != null && (!t.done || (t.date === tbxViewDate() && t.start_min != null))).length; }
// ⭐ BIG 3 올리기/내리기 — 할 일 목록·타임라인 블록 공용 (배정된 일도 올릴 수 있다)
async function tbxToggleBig3(id) {
    const t = _tbxTasks.find(x => x.id === id); if (!t) return;
    if (t.big3_rank != null) {
        if (await tbxUpdate(id, { big3_rank: null })) { tbxRenderAll(); showToast('BIG 3에서 내렸습니다'); }
        return;
    }
    if (tbxTopCount() >= 3) {
        alert('⭐ 오늘의 BIG 3가 이미 3개로 가득 찼습니다.\n\n"' + t.task + '"은(는) 등록되지 않았습니다.\n먼저 기존 BIG 3 중 하나의 ⭐를 눌러 내린 뒤 다시 시도해주세요.');
        return;
    }
    const used = _tbxTasks.filter(x => x.big3_rank != null).map(x => x.big3_rank);
    let rank = 1; while (used.includes(rank) && rank < 3) rank++;
    if (await tbxUpdate(id, { big3_rank: rank })) { tbxRenderAll(); showToast(`⭐ BIG 3 ${rank}순위로 지정`); }
}
function tbxDur(t) { return t.duration_min || 60; }
function tbxCat(t) { return TBX_CAT_VAR[t.category] || TBX_CAT_VAR.work; }

async function tbxEnter() {
    await tbxLoad();
    await tbxLoadRoutines();
    await tbxMaterializeRoutines();
    tbxRenderDateLabel();
    tbxRenderAll();
    if (_tbxTimer) clearInterval(_tbxTimer);
    _tbxTimer = setInterval(() => {
        const tab = document.getElementById('tab-timebox');
        if (!tab || !tab.classList.contains('active')) { clearInterval(_tbxTimer); _tbxTimer = null; return; }
        tbxRenderGrid(); tbxRenderNow();
    }, 60000);
}

async function tbxLoad() {
    if (!currentUser || !currentUser.name) return;
    const today = getTodayStr();
    // 내 것: (미완료 & 오늘 이전 포함) + (오늘 것 전부) — 미래 예정은 그 날이 오면 자연히 포함됨
    const COLS = 'id, task, date, done, start_min, duration_min, big3_rank, category, assignee, routine_id, sort_order';
    const { data, error } = await sb.from('daily_tasks')
        .select(COLS)
        .eq('assignee', currentUser.name)
        .lte('date', today)
        .or(`done.eq.false,date.eq.${today}`)
        .order('id');
    if (error) { console.error('타임박스 로드 실패', error); showToast('불러오기 실패: ' + error.message); return; }
    _tbxTasks = data || [];
    // 다른 날짜를 보는 중이면 그 날짜의 행(완료 포함)을 추가로 가져와 병합
    const vd = tbxViewDate();
    if (vd !== today) {
        const { data: extra } = await sb.from('daily_tasks').select(COLS)
            .eq('assignee', currentUser.name).eq('date', vd).order('id');
        (extra || []).forEach(r => { if (!_tbxTasks.find(x => x.id === r.id)) _tbxTasks.push(r); });
    }
}

// 일일계획표·홈 화면도 함께 갱신 (직접 push하면 realtime이 중복으로 무시해 재렌더가 안 됨)
function tbxSyncViews() {
    try { renderDaily(); } catch (_) {}
    try { renderHome(); } catch (_) {}
}

// DB 업데이트 + 로컬/전역 캐시 동기화 (일일계획표 화면과 어긋나지 않게)
async function tbxUpdate(id, patch) {
    const { data, error } = await sb.from('daily_tasks').update(patch).eq('id', id).select('id');
    if (error || !data || !data.length) { showToast('저장 실패' + (error ? ': ' + error.message : '')); return false; }
    const t = _tbxTasks.find(x => x.id === id);
    if (t) Object.assign(t, patch);
    try {
        const g = (typeof dailyTasks !== 'undefined') ? dailyTasks.find(x => x.id === id) : null;
        if (g) { if ('done' in patch) g.done = patch.done; if ('date' in patch) g.date = patch.date; }
    } catch (_) {}
    tbxSyncViews();
    return true;
}

function tbxRenderAll() { tbxRenderTop3(); tbxRenderInbox(); tbxRenderGrid(); tbxRenderStats(); tbxRenderNow(); }

// ===== BIG 3 =====
function tbxRenderTop3() {
    const list = document.getElementById('tbxTop3List');
    if (!list) return;
    const vday = tbxViewDate();
    const pending = _tbxTasks.filter(t => t.big3_rank != null && !t.done && !(t.date === vday && t.start_min != null) && (tbxIsToday() || t.date === vday))
        .sort((a, b) => a.big3_rank - b.big3_rank);
    const scheduled = _tbxTasks.filter(t => t.big3_rank != null && t.date === vday && t.start_min != null)
        .sort((a, b) => a.start_min - b.start_min);
    const total = pending.length + scheduled.length;
    document.getElementById('tbxTop3Count').textContent = `${total}/3`;
    let rank = 1, html = '';
    pending.forEach(t => {
        html += `<div class="tbx-top3item" draggable="true" data-tbxdrag="${t.id}">
            <span class="tbx-rank">${rank++}</span>
            <span class="tbx-title">${escHtml(t.task)}</span>
            <span class="tbx-when tbx-mono">${tbxDur(t)}m</span>
            <button class="tbx-place" data-tbxplace="${t.id}">배정</button>
            <button class="tbx-btn" data-tbxunstar="${t.id}" title="목록으로 내리기">↓</button>
        </div>`;
    });
    scheduled.forEach(t => {
        html += `<div class="tbx-top3item scheduled${t.done ? ' done-item' : ''}">
            <span class="tbx-rank">${rank++}</span>
            <span class="tbx-title">${escHtml(t.task)}</span>
            <span class="tbx-when tbx-mono">${tbxFmt(t.start_min)}</span>
            <span class="tbx-when">${t.done ? '✅ 완료' : '⏱ 배정됨'}</span>
        </div>`;
    });
    for (let i = total; i < 3; i++) html += `<div class="tbx-top3slot">${i + 1}순위 — 아래 목록에서 ⭐를 눌러 올리세요</div>`;
    list.innerHTML = html;
    list.querySelectorAll('[data-tbxdrag]').forEach(el => el.addEventListener('dragstart', e => {
        e.dataTransfer.setData('text/plain', 'tbx:' + el.dataset.tbxdrag);
    }));
    list.querySelectorAll('[data-tbxplace]').forEach(b => b.addEventListener('click', () => tbxAutoPlace(Number(b.dataset.tbxplace))));
    list.querySelectorAll('[data-tbxunstar]').forEach(b => b.addEventListener('click', async () => {
        if (await tbxUpdate(Number(b.dataset.tbxunstar), { big3_rank: null })) tbxRenderAll();
    }));
}

// ===== 목록 내 드래그 재정렬 공통 =====
function _tbxOrderCmp(a, b) {
    const ao = a.sort_order, bo = b.sort_order;
    if (ao != null && bo != null && ao !== bo) return ao - bo;
    if (ao != null && bo == null) return -1;
    if (ao == null && bo != null) return 1;
    return (a.date || '').localeCompare(b.date || '') || a.id - b.id;
}
// 컨테이너에서 드롭 위치(몇 번째 앞인지) 계산
function _tbxDropIndex(container, y) {
    const items = Array.from(container.querySelectorAll('.tbx-task'));
    for (let i = 0; i < items.length; i++) {
        const r = items[i].getBoundingClientRect();
        if (y < r.top + r.height / 2) return i;
    }
    return items.length;
}
// 목록 컨테이너에 재정렬 드롭 바인딩 (1회만). getOrdered()=현재 표시 순서 배열, apply(newIds)=순서 저장
function _tbxBindReorder(container, prefix, getOrdered, apply) {
    if (container._reorderBound) return;
    container._reorderBound = true;
    container.addEventListener('dragover', e => {
        const data = e.dataTransfer.types.includes('text/plain');
        if (!data) return;
        e.preventDefault();
        container.querySelectorAll('.tbx-task.reorder-hint').forEach(x => x.classList.remove('reorder-hint'));
        const items = Array.from(container.querySelectorAll('.tbx-task'));
        const idx = _tbxDropIndex(container, e.clientY);
        const mark = items[idx] || items[items.length - 1];
        if (mark) mark.classList.add('reorder-hint');
    });
    container.addEventListener('dragleave', e => {
        if (!container.contains(e.relatedTarget)) container.querySelectorAll('.tbx-task.reorder-hint').forEach(x => x.classList.remove('reorder-hint'));
    });
    container.addEventListener('drop', async e => {
        container.querySelectorAll('.tbx-task.reorder-hint').forEach(x => x.classList.remove('reorder-hint'));
        const data = e.dataTransfer.getData('text/plain');
        if (!data || !data.startsWith(prefix + ':')) return;
        e.preventDefault();
        e.stopPropagation();
        const id = Number(data.split(':')[1]);
        const ordered = getOrdered().map(x => x.id);
        const from = ordered.indexOf(id);
        if (from < 0) return;
        let to = _tbxDropIndex(container, e.clientY);
        ordered.splice(from, 1);
        if (to > from) to--;
        ordered.splice(to, 0, id);
        await apply(ordered);
    });
}

// ===== Brain dump =====
function tbxRenderInbox() {
    const list = document.getElementById('tbxInbox');
    if (!list) return;
    const today = getTodayStr();
    // 수동 순서(sort_order)가 있으면 우선, 없으면 오래된 날짜순 — 이월된 일이 위로 쌓인다
    const items = tbxInboxTasks().filter(t => t.big3_rank == null).sort(_tbxOrderCmp);
    if (!items.length) { list.innerHTML = '<div class="tbx-empty">목록이 비었습니다 🎉<br>모든 일이 자리를 찾았어요.</div>'; return; }
    list.innerHTML = items.map(t => `
        <div class="tbx-task" draggable="true" data-tbxdrag="${t.id}" style="border-left-color:${tbxCat(t)}">
            <button class="tbx-btn tbx-star" data-tbxstar="${t.id}" title="BIG 3로 올리기">⭐</button>
            ${t.routine_id != null ? '<span class="tbx-routine-badge" title="루틴에서 자동 추가된 일">🔁</span>' : ''}
            ${t.date < today ? `<span class="tbx-fromplan tbx-mono" title="${escHtml(t.date)}부터 밀려온 일">${tbxFmtMD(t.date)}</span>` : ''}
            <span class="tbx-title">${escHtml(t.task)}</span>
            <button class="tbx-catchip" data-tbxcat="${t.id}" title="클릭해서 카테고리 변경"><i style="background:${tbxCat(t)}"></i>${TBX_CATS[t.category] || '회사'}</button>
            <button class="tbx-est tbx-mono" data-tbxest="${t.id}" title="예상 시간 (클릭해서 변경)">${tbxDur(t)}m</button>
            <button class="tbx-place" data-tbxplace="${t.id}">배정</button>
            <button class="tbx-btn tbx-del" data-tbxdel="${t.id}" title="삭제">✕</button>
        </div>`).join('');
    list.querySelectorAll('[data-tbxdrag]').forEach(el => el.addEventListener('dragstart', e => {
        e.dataTransfer.setData('text/plain', 'tbx:' + el.dataset.tbxdrag);
    }));
    list.querySelectorAll('[data-tbxstar]').forEach(b => b.addEventListener('click', () => tbxToggleBig3(Number(b.dataset.tbxstar))));
    const CAT_CYCLE = ['work', 'client', 'meet', 'me'];
    const EST_CYCLE = [30, 60, 90, 120, 180];
    list.querySelectorAll('[data-tbxcat]').forEach(b => b.addEventListener('click', async () => {
        const t = _tbxTasks.find(x => x.id === Number(b.dataset.tbxcat)); if (!t) return;
        const next = CAT_CYCLE[(CAT_CYCLE.indexOf(t.category) + 1 + CAT_CYCLE.length) % CAT_CYCLE.length] || 'work';
        if (await tbxUpdate(t.id, { category: next, label: TBX_CAT_LABEL[next] })) tbxRenderInbox();
    }));
    list.querySelectorAll('[data-tbxest]').forEach(b => b.addEventListener('click', async () => {
        const t = _tbxTasks.find(x => x.id === Number(b.dataset.tbxest)); if (!t) return;
        const i = EST_CYCLE.indexOf(tbxDur(t));
        const next = EST_CYCLE[(i < 0 ? 1 : i + 1) % EST_CYCLE.length];
        if (await tbxUpdate(t.id, { duration_min: next })) tbxRenderInbox();
    }));
    list.querySelectorAll('[data-tbxplace]').forEach(b => b.addEventListener('click', () => tbxAutoPlace(Number(b.dataset.tbxplace))));
    list.querySelectorAll('[data-tbxdel]').forEach(b => b.addEventListener('click', async () => {
        if (!confirm('이 할 일을 삭제할까요?')) return;
        const { error } = await sb.from('daily_tasks').delete().eq('id', Number(b.dataset.tbxdel));
        if (error) { showToast('삭제 실패: ' + error.message); return; }
        _tbxTasks = _tbxTasks.filter(x => x.id !== Number(b.dataset.tbxdel));
        try { if (typeof dailyTasks !== 'undefined') { const i = dailyTasks.findIndex(x => x.id === Number(b.dataset.tbxdel)); if (i >= 0) dailyTasks.splice(i, 1); } } catch (_) {}
        tbxSyncViews();
        tbxRenderAll();
    }));
    // 목록 안에서 드래그해서 순서 바꾸기
    _tbxBindReorder(list, 'tbx',
        () => tbxInboxTasks().filter(t => t.big3_rank == null).sort(_tbxOrderCmp),
        async (ids) => {
            await Promise.all(ids.map((id, i) => {
                const t = _tbxTasks.find(x => x.id === id);
                const so = (i + 1) * 10;
                if (!t || t.sort_order === so) return null;
                t.sort_order = so;
                return sb.from('daily_tasks').update({ sort_order: so }).eq('id', id);
            }));
            tbxRenderInbox();
        });
}

// ===== 배치 =====
function tbxOverlaps(s, d, ignoreId) {
    return tbxBlocks().some(b => b.id !== ignoreId && s < b.start_min + tbxDur(b) && s + d > b.start_min);
}
function tbxFindFree(dur, fromMin) {
    let s = tbxSnap(Math.max(TBX_DAY_START, fromMin));
    while (s + dur <= TBX_DAY_END) { if (!tbxOverlaps(s, dur, -1)) return s; s += _tbxGran; }
    return -1;
}
async function tbxAutoPlace(id) {
    const t = _tbxTasks.find(x => x.id === id); if (!t) return;
    const s = tbxFindFree(tbxDur(t), Math.max(tbxNowMin(), TBX_DAY_START));
    if (s < 0) { showToast('오늘은 빈 시간이 부족해요 — 블록을 정리해보세요'); return; }
    if (await tbxUpdate(id, { start_min: s, date: tbxViewDate() })) {
        tbxRenderAll();
        showToast(`"${t.task}" → ${tbxFmt(s)} 에 배정됨`);
    }
}

// ===== 타임라인 =====
function tbxRenderGrid() {
    const grid = document.getElementById('tbxGrid');
    if (!grid) return;
    grid.style.height = ((TBX_DAY_END - TBX_DAY_START) * tbxPxPerMin() + 14) + 'px';
    grid.querySelectorAll('.tbx-hrow,.tbx-slot,.tbx-block,.tbx-nowline').forEach(el => el.remove());
    for (let m = TBX_DAY_START; m < TBX_DAY_END; m += _tbxGran) {
        const r = document.createElement('div');
        if (m % 60 === 0) { r.className = 'tbx-hrow'; r.innerHTML = `<span class="tbx-hlabel tbx-mono">${tbxFmt(m)}</span>`; }
        else r.className = 'tbx-hrow sub';
        r.style.top = tbxY(m) + 'px';
        grid.appendChild(r);
        const hit = document.createElement('div');
        hit.className = 'tbx-slot'; hit.dataset.min = m;
        hit.style.top = tbxY(m) + 'px'; hit.style.height = (_tbxGran * tbxPxPerMin()) + 'px';
        grid.appendChild(hit);
    }
    const nm = tbxNowMin();
    const isToday = tbxIsToday();
    tbxBlocks().forEach(b => {
        const el = document.createElement('div');
        el.className = 'tbx-block' + (b.done ? ' done' : '') + (isToday && !b.done && nm >= b.start_min && nm < b.start_min + tbxDur(b) ? ' now' : '');
        el.dataset.id = b.id; el.draggable = true;
        el.style.setProperty('--c', tbxCat(b));
        el.style.top = tbxY(b.start_min) + 'px';
        el.style.height = Math.max(20, tbxDur(b) * tbxPxPerMin() - 3) + 'px';
        el.innerHTML = `<div class="tbx-btop">
            <button class="tbx-bbtn tbx-bstar${b.big3_rank != null ? ' on' : ''}" title="${b.big3_rank != null ? 'BIG 3에서 내리기' : 'BIG 3로 올리기'}">${b.big3_rank != null ? '⭐' : '☆'}</button>
            <span class="tbx-btitle">${escHtml(b.task)}</span>
            <span class="tbx-btime tbx-mono">${tbxFmt(b.start_min)}–${tbxFmt(b.start_min + tbxDur(b))}</span>
            <button class="tbx-bbtn tbx-bdone" title="완료 표시">✓</button>
            <button class="tbx-bbtn tbx-bx" title="목록으로 되돌리기">↩</button>
        </div><div class="tbx-resize" title="끌어서 길이 조절"></div>`;
        grid.appendChild(el);
        el.querySelector('.tbx-bstar').addEventListener('click', e => {
            e.stopPropagation();
            tbxToggleBig3(b.id);
        });
        el.querySelector('.tbx-bdone').addEventListener('click', async e => {
            e.stopPropagation();
            const done = !b.done;
            if (await tbxUpdate(b.id, { done, completed_at: done ? new Date().toISOString() : null })) tbxRenderAll();
        });
        el.querySelector('.tbx-bx').addEventListener('click', async e => {
            e.stopPropagation();
            if (await tbxUpdate(b.id, { start_min: null })) { tbxRenderAll(); showToast('목록으로 되돌렸습니다'); }
        });
        el.addEventListener('dragstart', e => e.dataTransfer.setData('text/plain', 'tbxblk:' + b.id));
        el.querySelector('.tbx-resize').addEventListener('mousedown', e => {
            e.preventDefault(); e.stopPropagation();
            el.draggable = false;
            const startY = e.clientY, startDur = tbxDur(b);
            let nd = startDur;
            const move = (ev) => {
                nd = Math.max(_tbxGran, Math.round((startDur + (ev.clientY - startY) / tbxPxPerMin()) / _tbxGran) * _tbxGran);
                nd = Math.min(TBX_DAY_END - b.start_min, nd);
                if (!tbxOverlaps(b.start_min, nd, b.id)) {
                    el.style.height = Math.max(20, nd * tbxPxPerMin() - 3) + 'px';
                    el.querySelector('.tbx-btime').textContent = `${tbxFmt(b.start_min)}–${tbxFmt(b.start_min + nd)}`;
                }
            };
            const up = async () => {
                document.removeEventListener('mousemove', move);
                document.removeEventListener('mouseup', up);
                el.draggable = true;
                if (nd !== startDur && !tbxOverlaps(b.start_min, nd, b.id)) await tbxUpdate(b.id, { duration_min: nd });
                tbxRenderAll();
            };
            document.addEventListener('mousemove', move);
            document.addEventListener('mouseup', up);
        });
    });
    if (isToday && nm >= TBX_DAY_START && nm <= TBX_DAY_END) {
        const nl = document.createElement('div');
        nl.className = 'tbx-nowline'; nl.style.top = tbxY(nm) + 'px';
        grid.appendChild(nl);
    }
}

function tbxRenderStats() {
    const blocks = tbxBlocks();
    const planned = blocks.reduce((s, b) => s + tbxDur(b), 0);
    const done = blocks.filter(b => b.done).length;
    const h = (m) => (m / 60).toFixed(1).replace(/\.0$/, '') + 'h';
    const el1 = document.getElementById('tbxChipPlanned');
    const el2 = document.getElementById('tbxChipDone');
    if (el1) el1.textContent = (planned / 60).toFixed(1).replace(/\.0$/, '') + '시간';
    if (el2) el2.textContent = `${done}/${blocks.length}`;
    // 오른쪽 '오늘 요약' 패널
    const sp = document.getElementById('tbxStPlanned');
    const sf = document.getElementById('tbxStFree');
    if (sp) sp.textContent = h(planned);
    if (sf) sf.textContent = h((TBX_DAY_END - TBX_DAY_START) - planned);
    const pct = blocks.length ? Math.round(done / blocks.length * 100) : 0;
    const pf = document.getElementById('tbxProgFill');
    const pt = document.getElementById('tbxProgText');
    if (pf) pf.style.width = pct + '%';
    if (pt) pt.textContent = pct + '%';
}

function tbxRenderNow() {
    if (!tbxIsToday()) {
        const t1 = document.getElementById('tbxNowTitle');
        const t2 = document.getElementById('tbxNowSub');
        const ck = document.getElementById('tbxNowClock');
        if (ck) ck.textContent = tbxFmtMD(tbxViewDate());
        if (t1) t1.textContent = '다른 날짜 보는 중';
        if (t2) t2.textContent = '오늘로 돌아가려면 [오늘로]를 누르세요';
        return;
    }
    const nm = tbxNowMin();
    const clock = document.getElementById('tbxNowClock');
    if (clock) clock.textContent = tbxFmt(nm);
    const cur = tbxBlocks().find(b => !b.done && nm >= b.start_min && nm < b.start_min + tbxDur(b));
    const titleEl = document.getElementById('tbxNowTitle');
    const subEl = document.getElementById('tbxNowSub');
    if (!titleEl || !subEl) return;
    if (cur) {
        titleEl.textContent = cur.task;
        subEl.textContent = `${tbxFmt(cur.start_min)}–${tbxFmt(cur.start_min + tbxDur(cur))} · ${cur.start_min + tbxDur(cur) - nm}분 남음`;
    } else {
        const next = tbxBlocks().filter(b => !b.done && b.start_min > nm).sort((a, b) => a.start_min - b.start_min)[0];
        titleEl.textContent = '지금은 빈 시간';
        subEl.textContent = next ? `다음: ${tbxFmt(next.start_min)} "${next.task}"` : '남은 블록 없음';
    }
}

// ===== 추가/토글 =====
async function tbxAddTask() {
    const inp = document.getElementById('tbxNewTask');
    const v = (inp.value || '').trim(); if (!v) return;
    const p = tbxParse(v);
    const row = { task: p.title, date: tbxViewDate(), assignee: currentUser.name, done: false,
        category: p.cat, duration_min: p.est, label: TBX_CAT_LABEL[p.cat] };
    const { data, error } = await sb.from('daily_tasks').insert(row).select().single();
    if (error) { showToast('추가 실패: ' + error.message); return; }
    _tbxTasks.push(data);
    try { if (typeof dailyTasks !== 'undefined' && typeof taskFromDb === 'function') dailyTasks.push(taskFromDb(data)); } catch (_) {}
    tbxSyncViews();
    inp.value = '';
    tbxRenderInbox();
}

// ===== 루틴: 매일 자동으로 '할 일'에 추가 =====
async function tbxLoadRoutines() {
    if (!currentUser || !currentUser.name) return;
    const { data, error } = await sb.from('routines').select('*')
        .eq('assignee', currentUser.name).eq('active', true).order('id');
    if (error) { console.error('루틴 로드 실패', error); return; }
    _tbxRoutines = (data || []).sort((a, b) => {
        if (a.sort_order != null && b.sort_order != null && a.sort_order !== b.sort_order) return a.sort_order - b.sort_order;
        if (a.sort_order != null && b.sort_order == null) return -1;
        if (a.sort_order == null && b.sort_order != null) return 1;
        return a.id - b.id;
    });
    tbxRenderRoutines();
}
// 오늘 날짜에 아직 안 만들어진 루틴을 할 일로 생성 (routine_id로 하루 1회 중복 방지)
async function tbxMaterializeRoutines() {
    if (!tbxIsToday() || !_tbxRoutines.length) return;
    const today = getTodayStr();
    const have = new Set(_tbxTasks.filter(t => t.routine_id != null && t.date === today).map(t => t.routine_id));
    let made = 0;
    for (const r of _tbxRoutines) {
        if (have.has(r.id)) continue;
        const row = { task: r.title, date: today, assignee: currentUser.name, done: false,
            category: r.category || 'work', duration_min: r.duration_min || 60,
            label: TBX_CAT_LABEL[r.category || 'work'], routine_id: r.id };
        const { data, error } = await sb.from('daily_tasks').insert(row).select().single();
        if (!error && data) {
            _tbxTasks.push(data); made++;
            try { if (typeof dailyTasks !== 'undefined' && !dailyTasks.find(x => x.id === data.id)) dailyTasks.push(taskFromDb(data)); } catch (_) {}
        }
    }
    if (made) { tbxSyncViews(); showToast('🔁 루틴 ' + made + '건이 오늘 할 일에 추가됐어요'); }
}
function tbxRenderRoutines() {
    const list = document.getElementById('tbxRoutines');
    if (!list) return;
    if (!_tbxRoutines.length) { list.innerHTML = '<div class="tbx-empty">루틴이 없습니다.<br>매일 반복할 일을 등록해보세요.</div>'; return; }
    list.innerHTML = _tbxRoutines.map(r => `
        <div class="tbx-task" draggable="true" data-rdrag="${r.id}" style="border-left-color:${TBX_CAT_VAR[r.category] || TBX_CAT_VAR.work}">
            <span class="tbx-routine-badge">🔁</span>
            <span class="tbx-title">${escHtml(r.title)}</span>
            <button class="tbx-catchip" data-rcat="${r.id}" title="클릭해서 카테고리 변경"><i style="background:${TBX_CAT_VAR[r.category] || TBX_CAT_VAR.work}"></i>${TBX_CATS[r.category] || '회사'}</button>
            <button class="tbx-est tbx-mono" data-rest="${r.id}" title="예상 시간 (클릭해서 변경)">${r.duration_min || 60}m</button>
            <button class="tbx-btn tbx-del" data-rdel="${r.id}" title="루틴 삭제">✕</button>
        </div>`).join('');
    const R_CAT_CYCLE = ['work', 'client', 'meet', 'me'];
    const R_EST_CYCLE = [30, 60, 90, 120, 180];
    // 루틴의 시간/카테고리 변경 → 루틴 자체 + 오늘 이미 만들어진 할 일에도 반영
    async function _tbxRoutinePatch(id, patch) {
        const { error } = await sb.from('routines').update(patch).eq('id', id);
        if (error) { showToast('루틴 수정 실패: ' + error.message); return false; }
        const r = _tbxRoutines.find(x => x.id === id);
        if (r) Object.assign(r, patch);
        const todayTask = _tbxTasks.find(t => t.routine_id === id && t.date === getTodayStr());
        if (todayTask) {
            const tp = {};
            if (patch.duration_min != null) tp.duration_min = patch.duration_min;
            if (patch.category != null) { tp.category = patch.category; tp.label = TBX_CAT_LABEL[patch.category]; }
            await tbxUpdate(todayTask.id, tp);
        }
        tbxRenderRoutines();
        tbxRenderAll();
        return true;
    }
    list.querySelectorAll('[data-rcat]').forEach(b => b.addEventListener('click', () => {
        const r = _tbxRoutines.find(x => x.id === Number(b.dataset.rcat)); if (!r) return;
        const next = R_CAT_CYCLE[(R_CAT_CYCLE.indexOf(r.category) + 1 + R_CAT_CYCLE.length) % R_CAT_CYCLE.length] || 'work';
        _tbxRoutinePatch(r.id, { category: next });
    }));
    list.querySelectorAll('[data-rest]').forEach(b => b.addEventListener('click', () => {
        const r = _tbxRoutines.find(x => x.id === Number(b.dataset.rest)); if (!r) return;
        const i = R_EST_CYCLE.indexOf(r.duration_min || 60);
        _tbxRoutinePatch(r.id, { duration_min: R_EST_CYCLE[(i < 0 ? 1 : i + 1) % R_EST_CYCLE.length] });
    }));
    list.querySelectorAll('[data-rdel]').forEach(b => b.addEventListener('click', async () => {
        if (!confirm('이 루틴을 삭제할까요? (이미 만들어진 할 일은 남습니다)')) return;
        const { error } = await sb.from('routines').delete().eq('id', Number(b.dataset.rdel));
        if (error) { showToast('삭제 실패: ' + error.message); return; }
        _tbxRoutines = _tbxRoutines.filter(r => r.id !== Number(b.dataset.rdel));
        tbxRenderRoutines();
    }));
    list.querySelectorAll('[data-rdrag]').forEach(el => el.addEventListener('dragstart', e => {
        e.dataTransfer.setData('text/plain', 'rtn:' + el.dataset.rdrag);
    }));
    // 루틴도 드래그로 순서 바꾸기
    _tbxBindReorder(list, 'rtn',
        () => _tbxRoutines.slice(),
        async (ids) => {
            _tbxRoutines.sort((a, b) => ids.indexOf(a.id) - ids.indexOf(b.id));
            await Promise.all(ids.map((id, i) => {
                const r = _tbxRoutines.find(x => x.id === id);
                const so = (i + 1) * 10;
                if (!r || r.sort_order === so) return null;
                r.sort_order = so;
                return sb.from('routines').update({ sort_order: so }).eq('id', id);
            }));
            tbxRenderRoutines();
        });
}
async function tbxAddRoutine() {
    const inp = document.getElementById('tbxNewRoutine');
    const v = (inp.value || '').trim(); if (!v) return;
    const p = tbxParse(v);
    const { data, error } = await sb.from('routines').insert({
        assignee: currentUser.name, title: p.title, category: p.cat, duration_min: p.est
    }).select().single();
    if (error) { showToast('루틴 추가 실패: ' + error.message); return; }
    _tbxRoutines.push(data);
    inp.value = '';
    tbxRenderRoutines();
    await tbxMaterializeRoutines();
    tbxRenderAll();
}

function tbxSetGran(g) {
    _tbxGran = g;
    document.getElementById('tbxGran60').classList.toggle('on', g === 60);
    document.getElementById('tbxGran30').classList.toggle('on', g === 30);
    tbxRenderGrid();
}

// ===== 그리드 상호작용 (드롭 / 빈칸 클릭) =====
(function tbxBindGridOnce() {
    document.addEventListener('DOMContentLoaded', () => {
        const grid = document.getElementById('tbxGrid');
        if (!grid) return;
        grid.addEventListener('dragover', e => {
            e.preventDefault();
            grid.querySelectorAll('.tbx-slot.droptarget').forEach(x => x.classList.remove('droptarget'));
            const hit = e.target.closest('.tbx-slot'); if (hit) hit.classList.add('droptarget');
        });
        grid.addEventListener('drop', async e => {
            e.preventDefault();
            grid.querySelectorAll('.tbx-slot.droptarget').forEach(x => x.classList.remove('droptarget'));
            const data = e.dataTransfer.getData('text/plain'); if (!data) return;
            // 드래그 중 파랗게 표시된 바로 그 칸에 놓는다 (커서 위치 반올림 오차 제거)
            const hitSlot = e.target.closest && e.target.closest('.tbx-slot');
            let dropMin;
            if (hitSlot) dropMin = Number(hitSlot.dataset.min);
            else {
                const rect = grid.getBoundingClientRect();
                const raw = tbxMinOfY(e.clientY - rect.top);
                dropMin = TBX_DAY_START + Math.floor((raw - TBX_DAY_START) / _tbxGran) * _tbxGran;
                dropMin = Math.max(TBX_DAY_START, Math.min(TBX_DAY_END - _tbxGran, dropMin));
            }
            const [kind, idStr] = data.split(':'); const id = Number(idStr);
            const t = _tbxTasks.find(x => x.id === id); if (!t) return;
            const dur = tbxDur(t);
            if (dropMin + dur > TBX_DAY_END) { showToast('하루를 넘어갑니다'); return; }
            if (kind === 'tbx' || kind === 'tbxblk') {
                if (tbxOverlaps(dropMin, dur, kind === 'tbxblk' ? id : -1)) { showToast('그 시간엔 이미 블록이 있어요'); return; }
                if (await tbxUpdate(id, { start_min: dropMin, date: tbxViewDate() })) tbxRenderAll();
            }
        });
        // 빈 칸 클릭 → 그 자리에서 바로 추가
        const qa = document.getElementById('tbxQuickAdd');
        let qaMin = null;
        grid.addEventListener('click', e => {
            const hit = e.target.closest('.tbx-slot');
            if (!hit) { if (!e.target.closest('.tbx-quickadd')) { qa.style.display = 'none'; qaMin = null; } return; }
            qaMin = Number(hit.dataset.min);
            qa.style.display = 'flex';
            qa.style.top = tbxY(qaMin) + 'px';
            const qi = document.getElementById('tbxQuickInput');
            qi.value = ''; qi.focus();
        });
        window.tbxQuickCommit = async function () {
            const qi = document.getElementById('tbxQuickInput');
            const v = (qi.value || '').trim();
            if (!v || qaMin === null) { qa.style.display = 'none'; qaMin = null; return; }
            const p = tbxParse(v);
            let dur = p.est;
            while (tbxOverlaps(qaMin, dur, -1) && dur > 30) dur -= 30;
            if (tbxOverlaps(qaMin, dur, -1)) { showToast('그 시간엔 이미 블록이 있어요'); qa.style.display = 'none'; return; }
            const row = { task: p.title, date: tbxViewDate(), assignee: currentUser.name, done: false,
                category: p.cat, duration_min: dur, start_min: qaMin, label: TBX_CAT_LABEL[p.cat] };
            const { data, error } = await sb.from('daily_tasks').insert(row).select().single();
            if (error) { showToast('추가 실패: ' + error.message); return; }
            _tbxTasks.push(data);
            try { if (typeof dailyTasks !== 'undefined' && typeof taskFromDb === 'function' && !dailyTasks.find(x => x.id === data.id)) dailyTasks.push(taskFromDb(data)); } catch (_) {}
            tbxSyncViews();
            qa.style.display = 'none'; qaMin = null;
            tbxRenderAll();
        };
        document.getElementById('tbxQuickInput').addEventListener('keydown', e => {
            if (e.key === 'Enter') window.tbxQuickCommit();
            if (e.key === 'Escape') { qa.style.display = 'none'; qaMin = null; }
        });
        document.getElementById('tbxNewTask').addEventListener('keydown', e => { if (e.key === 'Enter') tbxAddTask(); });
        document.getElementById('tbxNewRoutine').addEventListener('keydown', e => { if (e.key === 'Enter') tbxAddRoutine(); });
    });
})();

// =====================================
// QR 라벨 출력 (상품 DB → A4 라벨지)
// 이 앱은 바닐라 JS라 qrcode.react 대신 qrcodejs(CDN) 사용
// =====================================
let _labelSelected = new Set();

// 폼텍 A4 라벨지 규격 (mm). 실제 인쇄 전 시험 출력 권장
const LABEL_SPECS = {
    '3100': { name: '폼텍 3100', cols: 3, rows: 8, w: 63.5, h: 33.9, mt: 12.9, ml: 7.25, gx: 2.54, gy: 0, qr: 26 },
    '3108': { name: '폼텍 3108', cols: 2, rows: 6, w: 96.5, h: 42.3, mt: 12.7, ml: 7.75, gx: 2.5, gy: 0, qr: 33 }
};

// 체크박스 상태 → 버튼 노출/카운트
function updateLabelBtn() {
    const btn = document.getElementById('pdbLabelBtn');
    const cnt = document.getElementById('pdbLabelCount');
    if (!btn) return;
    const n = _labelSelected.size;
    btn.style.display = '';                       // 항상 보이게 (예전엔 선택해야만 나타나 찾기 어려웠음)
    btn.classList.toggle('is-dim', n === 0);
    if (cnt) cnt.textContent = n ? `(${n})` : '';
    const all = document.getElementById('pdbCheckAll');
    if (all) {
        const boxes = document.querySelectorAll('.pdb-check');
        const checked = document.querySelectorAll('.pdb-check:checked');
        all.checked = boxes.length > 0 && boxes.length === checked.length;
        all.indeterminate = checked.length > 0 && checked.length < boxes.length;
    }
}

// renderProductDB 이후 체크박스 리스너 부착
function bindProductChecks() {
    document.querySelectorAll('.pdb-check').forEach(box => {
        box.addEventListener('change', () => {
            const id = Number(box.dataset.pid);
            if (box.checked) _labelSelected.add(id); else _labelSelected.delete(id);
            updateLabelBtn();
        });
    });
    const all = document.getElementById('pdbCheckAll');
    if (all && !all._bound) {
        all._bound = true;
        all.addEventListener('change', () => {
            document.querySelectorAll('.pdb-check').forEach(box => {
                box.checked = all.checked;
                const id = Number(box.dataset.pid);
                if (all.checked) _labelSelected.add(id); else _labelSelected.delete(id);
            });
            updateLabelBtn();
        });
    }
    updateLabelBtn();
}

// 행의 🏷 라벨 버튼 — 그 상품 하나만 바로 출력
function printOneLabel(id) {
    _labelSelected = new Set([id]);
    document.querySelectorAll('.pdb-check').forEach(b => { b.checked = Number(b.dataset.pid) === id; });
    updateLabelBtn();
    openLabelSheet();
}

function openLabelSheet() {
    if (!_labelSelected.size) {
        // 아무것도 안 골랐으면 지금 목록에 보이는 상품 전체로
        const visible = Array.from(document.querySelectorAll('.pdb-check')).map(b => Number(b.dataset.pid));
        if (!visible.length) { showToast('등록된 상품이 없습니다'); return; }
        if (!confirm(`선택한 상품이 없습니다.\n지금 목록에 보이는 ${visible.length}개 상품 전체로 라벨을 만들까요?`)) return;
        _labelSelected = new Set(visible);
        document.querySelectorAll('.pdb-check').forEach(b => { b.checked = true; });
        updateLabelBtn();
    }
    document.getElementById('labelOverlay').classList.add('open');
    document.body.style.overflow = 'hidden';
    renderLabelSheet();
}

function closeLabelSheet() {
    document.getElementById('labelOverlay').classList.remove('open');
    document.body.style.overflow = '';
}

function renderLabelSheet() {
    const spec = LABEL_SPECS[document.getElementById('labelSpec').value] || LABEL_SPECS['3100'];
    const perPage = spec.cols * spec.rows;
    const startEl = document.getElementById('labelStart');
    let start = Math.max(1, Math.min(perPage, parseInt(startEl.value, 10) || 1));
    startEl.value = start;
    startEl.max = perPage;

    const items = productsDB.filter(p => _labelSelected.has(p.id));
    document.getElementById('labelBarCount').textContent = `${items.length}개 상품`;

    // 시작 칸만큼 앞을 빈 칸으로 채운 뒤 페이지 단위로 자른다
    const cells = new Array(start - 1).fill(null).concat(items);
    const pages = [];
    for (let i = 0; i < cells.length; i += perPage) pages.push(cells.slice(i, i + perPage));
    if (!pages.length) pages.push([]);

    const base = location.origin;
    const scroll = document.getElementById('labelScroll');
    scroll.innerHTML = pages.map(page => {
        const cellHtml = [];
        for (let i = 0; i < perPage; i++) {
            const p = page[i];
            if (!p) { cellHtml.push('<div class="lbl lbl-empty"></div>'); continue; }
            const price = (p.unitPrice != null ? p.unitPrice : p.unit_price) || 0;
            const code = p.publicCode || p.public_code || '';
            cellHtml.push(`<div class="lbl">
                <div class="lbl-qr" data-url="${escHtml(base + '/p/' + code)}" data-size="${spec.qr}"></div>
                <div class="lbl-txt">
                    <div class="lbl-name">${escHtml(p.name)}</div>
                    <div class="lbl-price">${Number(price).toLocaleString('ko-KR')}원</div>
                    <div class="lbl-code">${escHtml(code)}</div>
                </div>
            </div>`);
        }
        return `<div class="lbl-sheet" style="padding:${spec.mt}mm ${spec.ml}mm;grid-template-columns:repeat(${spec.cols}, ${spec.w}mm);grid-auto-rows:${spec.h}mm;column-gap:${spec.gx}mm;row-gap:${spec.gy}mm">${cellHtml.join('')}</div>`;
    }).join('');

    // QR 렌더 (qrcodejs는 컨테이너에 직접 그린다)
    scroll.querySelectorAll('.lbl-qr').forEach(el => {
        el.innerHTML = '';
        const px = Math.round(Number(el.dataset.size) * 3.78); // mm → px (96dpi)
        try {
            new QRCode(el, {
                text: el.dataset.url,
                width: px, height: px,
                correctLevel: QRCode.CorrectLevel.M
            });
        } catch (e) {
            el.textContent = 'QR 오류';
            console.error('QR 생성 실패', e);
        }
    });
}

// =====================================
// 상품 원가·재고 (product_costs) — 로그인 사용자만 접근 가능 (RLS)
// =====================================
let _editingCosts = null;   // 편집 중 상품의 기존 원가 행 (없으면 null)

// 모달이 열린 뒤 호출 — 기존 값 채우기 + QR 링크 표시
async function loadProductCosts(productId, publicCode) {
    _editingCosts = null;
    const setV = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };

    // QR 공개 링크 (편집일 때만)
    const qrRow = document.getElementById('pcQrRow');
    if (qrRow && publicCode) {
        const url = location.origin + '/p/' + publicCode;
        qrRow.style.display = '';
        qrRow.innerHTML = `<div class="form-group"><label class="form-label">공개 QR 주소</label>
            <div style="display:flex;gap:8px;align-items:center">
                <input type="text" class="form-input" id="pcQrUrl" readonly value="${escHtml(url)}" style="font-family:'SF Mono','Fira Code',monospace;font-size:12.5px">
                <button type="button" class="btn-ghost" onclick="copyProductQrUrl()" style="white-space:nowrap">복사</button>
                <a class="btn-ghost" href="${escHtml(url)}" target="_blank" rel="noopener" style="white-space:nowrap;text-decoration:none">열기</a>
            </div>
            <div style="font-size:11.5px;color:var(--gray-500);font-weight:600;margin-top:6px">
                라벨의 QR을 찍으면 이 주소로 연결됩니다 · 코드 <b>${escHtml(publicCode)}</b>
            </div></div>`;
    } else if (qrRow) {
        qrRow.style.display = 'none';
        qrRow.innerHTML = '';
    }

    if (!productId) return;
    const { data, error } = await sb.from('product_costs').select('*').eq('product_id', productId).maybeSingle();
    if (error) { console.error('원가 로드 실패', error); return; }
    if (!data) return;
    _editingCosts = data;
    setV('pcSupplier', data.supplier_name || '');
    setV('pcSupplierClientId', data.supplier_client_id || '');
    setV('pcCost', data.cost_price ? Number(data.cost_price).toLocaleString() : '');
    setV('pcMinPrice', data.min_sale_price ? Number(data.min_sale_price).toLocaleString() : '');
    setV('pcStockQty', data.stock_qty != null ? data.stock_qty : '');
    setV('pcProdDays', data.production_days != null ? data.production_days : '');
    setV('pcStockLoc', data.stock_location || '');
    setV('pcStockPhoto', data.stock_photo || '');
    setV('pcMemo', data.memo || '');
    const cv = document.getElementById('pcCostVat'); if (cv) cv.checked = !!data.cost_vat_included;
    const mv = document.getElementById('pcMinPriceVat'); if (mv) mv.checked = !!data.min_price_vat_included;
    const echo = document.getElementById('pcProdDaysEcho'); if (echo) echo.textContent = data.production_days || 0;
    renderStockPhotoPreview();
    onSupplierInput();
}

// 공급처 datalist — 거래처 DB(매입처·서비스 우선)에서 채운다. 직접 입력도 허용
// 공급처 목록·연동 확인은 거래처 DB 전체 기준 — 처음 불러온 500개만 보면 '두리정밀'처럼
// 이름순 뒤쪽 거래처가 '거래처 DB에 없는 이름'으로 잘못 나온다
function fillSupplierDatalist() {
    fillSupplierDatalistNow();
    if (_clientsPagination && !_clientsPagination.hasMore) return;
    (async () => {
        try { if (!_clientsPagination) await loadClientsFromDb(); await ensureAllClientsLoaded(); } catch (_) {}
        fillSupplierDatalistNow();
        onSupplierInput();
    })();
}

function fillSupplierDatalistNow() {
    const dl = document.getElementById('pcSupplierList');
    if (!dl) return;
    const rank = c => (c.category === '매입처' ? 0 : c.category === '서비스(비용)' ? 1 : 2);
    const list = (clients || [])
        .filter(c => c.companyName)
        .sort((a, b) => rank(a) - rank(b) || String(a.companyName).localeCompare(String(b.companyName)));
    dl.innerHTML = list.map(c =>
        `<option value="${escHtml(c.companyName)}">${escHtml(c.category || '')}${c.staffName ? ' · ' + escHtml(c.staffName) : ''}</option>`
    ).join('');
}

// 입력값이 거래처 DB와 일치하면 id를 연결하고 담당자 정보를 보여준다
function onSupplierInput() {
    const inp = document.getElementById('pcSupplier');
    const hid = document.getElementById('pcSupplierClientId');
    const hint = document.getElementById('pcSupplierHint');
    if (!inp || !hid || !hint) return;
    const name = inp.value.trim();
    const key = clientNameKey(name);
    const hit = (clients || []).find(c => c.companyName === name)
        || (key.length >= 2 ? (clients || []).find(c => clientNameKey(c.companyName) === key) : null);   // (주)·공백 차이는 같은 거래처로
    if (!hit && name && (_clientsLoadingAll || (_clientsPagination && _clientsPagination.hasMore))) {
        hid.value = '';
        hint.innerHTML = '거래처 DB 전체에서 확인하는 중…';
        return;   // 전체 불러오기가 끝나면 fillSupplierDatalist 가 다시 확인한다
    }
    if (hit) {
        hid.value = hit.id;
        const bits = [hit.category, hit.staffName, hit.staffMobile || hit.phone].filter(Boolean);
        hint.innerHTML = `<span style="color:var(--blue);font-weight:800">거래처 DB 연동됨</span> · ${escHtml(bits.join(' · '))}`;
    } else {
        hid.value = '';
        hint.innerHTML = name
            ? '거래처 DB에 없는 이름입니다 — 직접 입력으로 저장됩니다'
            : '';
    }
}

// 재고 위치 사진 업로드 (기존 상품 이미지와 같은 압축 사용)
async function handleStockPhotoUpload(ev) {
    const file = ev.target.files && ev.target.files[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) { showToast('이미지 파일만 업로드 가능합니다'); return; }
    if (file.size > 8 * 1024 * 1024) { showToast('8MB 이하 파일만 업로드 가능합니다'); return; }
    const reader = new FileReader();
    reader.onload = async (e) => {
        try {
            const shrunk = await _shrinkDataUrl(e.target.result, 900, 0.8);
            document.getElementById('pcStockPhoto').value = shrunk;
            renderStockPhotoPreview();
            showToast('재고 위치 사진이 첨부됐습니다');
        } catch (err) {
            showToast('사진 처리 실패: ' + err.message);
        }
    };
    reader.readAsDataURL(file);
}

function renderStockPhotoPreview() {
    const box = document.getElementById('pcStockPhotoPreview');
    const val = document.getElementById('pcStockPhoto');
    if (!box || !val) return;
    if (!val.value) { box.innerHTML = ''; return; }
    box.innerHTML = `<div style="position:relative;display:inline-block">
        <img src="${escHtml(val.value)}" alt="재고 위치" style="max-width:220px;border-radius:10px;border:1px solid var(--border);display:block">
        <button type="button" onclick="clearStockPhoto()" title="사진 제거"
            style="position:absolute;top:6px;right:6px;width:24px;height:24px;border-radius:50%;border:none;
                   background:rgba(0,0,0,.6);color:#fff;cursor:pointer;font-size:13px;line-height:1">×</button>
    </div>`;
}

function clearStockPhoto() {
    document.getElementById('pcStockPhoto').value = '';
    const f = document.getElementById('pcStockPhotoFile'); if (f) f.value = '';
    renderStockPhotoPreview();
}

function copyProductQrUrl() {
    const el = document.getElementById('pcQrUrl');
    if (!el) return;
    navigator.clipboard.writeText(el.value)
        .then(() => showToast('QR 주소를 복사했습니다'))
        .catch(() => { el.select(); document.execCommand('copy'); showToast('QR 주소를 복사했습니다'); });
}

// saveProduct 뒤에 호출 — 입력이 하나라도 있으면 upsert, 전부 비었고 기존 행도 없으면 건너뜀
async function saveProductCosts(productId) {
    if (!productId) return;
    const g = (id) => { const el = document.getElementById(id); return el ? el.value.trim() : ''; };
    const n = (id) => Number(String(g(id)).replace(/[^0-9-]/g, '')) || 0;

    const chk = (id) => { const el = document.getElementById(id); return !!(el && el.checked); };
    const payload = {
        product_id: productId,
        supplier_name: g('pcSupplier'),
        supplier_client_id: Number(g('pcSupplierClientId')) || null,
        cost_price: n('pcCost'),
        cost_vat_included: chk('pcCostVat'),
        min_sale_price: n('pcMinPrice'),
        min_price_vat_included: chk('pcMinPriceVat'),
        stock_qty: n('pcStockQty'),
        production_days: n('pcProdDays'),
        stock_location: g('pcStockLoc'),
        stock_photo: g('pcStockPhoto'),
        memo: g('pcMemo'),
        updated_at: new Date().toISOString()
    };
    const isEmpty = !payload.supplier_name && !payload.cost_price && !payload.min_sale_price
        && !payload.stock_qty && !payload.production_days && !payload.stock_location
        && !payload.stock_photo && !payload.memo;
    if (isEmpty && !_editingCosts) return;   // 아무것도 안 적었고 기존 행도 없으면 만들지 않음

    if (_editingCosts) {
        const { error } = await sb.from('product_costs').update(payload).eq('id', _editingCosts.id);
        if (error) showToast('원가 저장 실패: ' + error.message);
    } else {
        const { error } = await sb.from('product_costs').insert(payload);   // company_id는 트리거가 채움
        if (error) showToast('원가 저장 실패: ' + error.message);
    }
}

// =====================================
// 국내 거래처 DB — 엑셀 내보내기
// 화면에 적용된 구분(매출처/매입처/서비스/공란) + 검색어 그대로 반영해서 내보낸다
// =====================================
// 목록 화면은 500곳만 로드해두므로, 내보내기는 DB에서 전체를 다시 받아온다
async function fetchAllClients() {
    const PAGE = 1000;
    const out = [];
    for (let from = 0; ; from += PAGE) {
        const { data, error } = await sb.from('clients')
            .select('*').order('company_name', { ascending: true })
            .range(from, from + PAGE - 1);
        if (error) throw new Error(error.message);
        (data || []).forEach(r => out.push(clientFromDb(r)));
        if (!data || data.length < PAGE) break;
    }
    return out;
}

async function exportClientsToExcel(mode) {
    if (typeof XLSX === 'undefined') { showToast('엑셀 모듈을 불러오지 못했습니다'); return; }

    const CAT_SET = ['매출처', '매입처', '서비스(비용)'];
    const catLabel = (c) => CAT_SET.includes(c.category || '') ? c.category : '공란';

    showToast('전체 거래처를 불러오는 중…');
    let all;
    try { all = await fetchAllClients(); }
    catch (e) { showToast('불러오기 실패: ' + e.message); return; }

    // mode: 'current'(화면 필터 그대로) | 'bycat'(구분별 시트 분리) | 특정 카테고리명
    let sheets = [];
    if (mode === 'bycat') {
        ['매출처', '매입처', '서비스(비용)', '공란'].forEach(cat => {
            const rows = all.filter(c => catLabel(c) === cat);
            if (rows.length) sheets.push({ name: cat, rows });
        });
        if (!sheets.length) { showToast('내보낼 거래처가 없습니다'); return; }
    } else if (CAT_SET.includes(mode) || mode === '공란') {
        const rows = all.filter(c => catLabel(c) === mode);
        if (!rows.length) { showToast(mode + ' 거래처가 없습니다'); return; }
        sheets = [{ name: mode, rows }];
    } else {
        // 화면의 구분 칩 + 검색어를 전체 데이터에 그대로 적용
        let rows = all;
        if (CAT_SET.includes(clientCategoryFilter)) {
            rows = rows.filter(c => (c.category || '') === clientCategoryFilter);
        } else if (clientCategoryFilter === '공란') {
            rows = rows.filter(c => !CAT_SET.includes(c.category || ''));
        }
        if (clientSearch) {
            const q = clientSearch.toLowerCase();
            rows = rows.filter(c =>
                (c.companyName || '').toLowerCase().includes(q) ||
                (c.ceo || '').toLowerCase().includes(q) ||
                (c.phone || '').toLowerCase().includes(q) ||
                (c.mobile || '').toLowerCase().includes(q) ||
                (c.staffName || '').toLowerCase().includes(q) ||
                (c.address || '').toLowerCase().includes(q) ||
                (c.email || '').toLowerCase().includes(q));
        }
        if (!rows.length) { showToast('내보낼 거래처가 없습니다'); return; }
        const label = clientCategoryFilter === 'all' ? '전체' : clientCategoryFilter;
        sheets = [{ name: label, rows }];
    }

    const header = ['구분', '회사명', '사업자번호', '대표자', '전화번호', '팩스', '휴대폰',
                    '이메일', '우편번호', '주소', '업태', '종목',
                    '담당직원', '담당직원 연락처', '담당직원 이메일', '등급'];
    const cols = [{ wch: 11 }, { wch: 30 }, { wch: 14 }, { wch: 10 }, { wch: 15 }, { wch: 15 },
                  { wch: 15 }, { wch: 26 }, { wch: 10 }, { wch: 44 }, { wch: 14 }, { wch: 22 },
                  { wch: 12 }, { wch: 15 }, { wch: 24 }, { wch: 8 }];

    const wb = XLSX.utils.book_new();
    let total = 0;
    sheets.forEach(sh => {
        const body = sh.rows.map(c => [
            catLabel(c), c.companyName || '', c.businessNo || '', c.ceo || '',
            c.phone || '', c.fax || '', c.mobile || '', c.email || '',
            c.zipcode || '', c.address || '', c.bizType || '', c.bizItem || '',
            c.staffName || '', c.staffMobile || '', c.staffEmail || '', c.grade || ''
        ]);
        const ws = XLSX.utils.aoa_to_sheet([header, ...body]);
        ws['!cols'] = cols;
        ws['!autofilter'] = { ref: XLSX.utils.encode_range({ s: { r: 0, c: 0 }, e: { r: body.length, c: header.length - 1 } }) };
        ws['!freeze'] = { xSplit: 0, ySplit: 1 };
        // 시트명에 엑셀이 못 쓰는 문자 제거 (서비스(비용) 의 괄호는 허용됨)
        const safe = String(sh.name).replace(/[\\\/\?\*\[\]:]/g, '').slice(0, 28) || '거래처';
        XLSX.utils.book_append_sheet(wb, ws, safe + '(' + body.length + ')');
        total += body.length;
    });

    const d = new Date();
    const stamp = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
    const suffix = mode === 'bycat' ? '구분별' : (sheets[0] ? sheets[0].name : '전체');
    XLSX.writeFile(wb, `국내거래처_${suffix}_${stamp}.xlsx`);
    showToast(`${total}곳을 엑셀로 내보냈습니다`);
    closeClientExportMenu();
}

async function toggleClientExportMenu(ev) {
    if (ev) ev.stopPropagation();
    const m = document.getElementById('clientExportMenu');
    if (!m) return;
    const open = m.classList.toggle('show');
    if (!open) return;
    setTimeout(() => document.addEventListener('click', closeClientExportMenu, { once: true }), 0);

    const label = clientCategoryFilter === 'all' ? '전체' : clientCategoryFilter;
    const cur = document.getElementById('cxCurrent');
    const CATS = ['매출처', '매입처', '서비스(비용)', '공란'];
    if (cur) cur.textContent = `지금 화면 그대로 (${label}) — 세는 중…`;
    CATS.forEach(c => { const el = document.getElementById('cxCnt_' + c); if (el) el.textContent = '…'; });

    // 화면에 500곳만 로드돼 있으므로 건수는 DB 전체에서 센다
    try {
        const CAT_SET = ['매출처', '매입처', '서비스(비용)'];
        const counts = {};
        for (const cat of CAT_SET) {
            const { count } = await sb.from('clients').select('id', { count: 'exact', head: true }).eq('category', cat);
            counts[cat] = count || 0;
        }
        const { count: total } = await sb.from('clients').select('id', { count: 'exact', head: true });
        counts['공란'] = (total || 0) - CAT_SET.reduce((a, c) => a + counts[c], 0);

        CATS.forEach(c => { const el = document.getElementById('cxCnt_' + c); if (el) el.textContent = counts[c] + '곳'; });
        const shown = clientCategoryFilter === 'all' ? (total || 0) : (counts[clientCategoryFilter] || 0);
        if (cur) cur.textContent = clientSearch
            ? `지금 화면 그대로 (${label} + 검색어)`
            : `지금 화면 그대로 (${label} ${shown}곳)`;
    } catch (e) {
        if (cur) cur.textContent = `지금 화면 그대로 (${label})`;
        CATS.forEach(c => { const el = document.getElementById('cxCnt_' + c); if (el) el.textContent = ''; });
    }
}

function closeClientExportMenu() {
    const m = document.getElementById('clientExportMenu');
    if (m) m.classList.remove('show');
}

// =====================================
// 상담 관리 (견적 의뢰 화면 안) — 문의 접수부터 수주/실패까지
// 상담 건(inquiries) + 타임라인(inquiry_logs), 견적 품목은 projects_temp.inquiry_id로 연결
// =====================================
const INQ_STATUSES = ['신규', '상담중', '가견적', '견적발송', '수주', '제작중', '납품완료', '정산완료', '보류', '실패'];
const INQ_ACTIVE = ['신규', '상담중', '가견적', '견적발송', '수주', '제작중', '납품완료'];   // 정산완료·보류·실패만 '끝난 건'
const INQ_CHANNELS = ['전화', '카톡', '문자', '이메일', '방문', '홈페이지', '기타'];
const INQ_STATUS_CLS = { '신규': 's-new', '상담중': 's-talk', '가견적': 's-pre', '견적발송': 's-quote', '수주': 's-won', '제작중': 's-make', '납품완료': 's-deliv', '정산완료': 's-done', '보류': 's-hold', '실패': 's-lost' };
const INQ_DIR_LABEL = { in: '고객', out: '우리', memo: '내부 메모' };

let _inqList = [];
let _inqSel = null;            // 선택된 상담 id, 새 등록 중이면 'new'
let _inqLogs = [];
let _inqFilter = 'active';
let _inqDir = 'in';
let _inqPendingLink = null;    // '이 상담으로 견적 작성' 중인 상담 id
const _inqComposerImages = [];   // 기록 작성칸에 붙인 사진들
const _inqNewImages = [];        // 새 상담 첫 문의 내용에 붙인 사진들

// ---------- 화면 전환 ----------
function tpSetView(v) {
    if (v !== 'inq' && v !== 'quote') v = 'inq';
    try { localStorage.setItem('tp_view', v); } catch (_) {}
    const iv = document.getElementById('tpInqView');
    const qv = document.getElementById('tpQuoteView');
    if (!iv || !qv) return;
    iv.style.display = v === 'inq' ? '' : 'none';
    qv.style.display = v === 'quote' ? '' : 'none';
    document.getElementById('tpSwInq').classList.toggle('on', v === 'inq');
    document.getElementById('tpSwQuote').classList.toggle('on', v === 'quote');
    if (v === 'inq') {
        _inqPendingLink = null;       // 상담 화면으로 돌아오면 견적 연결 모드 해제
        inqRenderLinkBanner();
        inqEnter();
    } else {
        inqRenderLinkBanner();
    }
}

function tpInitView() {
    let v = 'inq';
    try { v = localStorage.getItem('tp_view') || 'inq'; } catch (_) {}
    if (v === 'quote') inqLoad();     // 목록 화면이어도 상단 건수는 보여준다
    tpSetView(v);
    tpMaybeAutoTour();   // 처음 들어온 사람에게 사용법 안내 한 번
}

// ---------- 데이터 ----------
async function inqLoad() {
    const { data, error } = await sb.from('inquiries').select('*')
        .order('last_contact_at', { ascending: false }).limit(2000);
    if (error) { console.error('상담 로드 실패', error); showToast('상담 불러오기 실패: ' + error.message); return false; }
    _inqList = data || [];
    inqUpdateSwitchCount();
    return true;
}

async function inqEnter() {
    await inqLoad();
    inqRenderChips();
    if (_inqSel && _inqSel !== 'new' && !_inqList.find(x => x.id === _inqSel)) _inqSel = null;
    if (!_inqSel) { const first = inqFiltered()[0]; if (first) _inqSel = first.id; }
    inqRenderList();
    inqRenderDetail();
}

function inqUpdateSwitchCount() {
    const el = document.getElementById('tpSwInqCnt');
    if (!el) return;
    const n = _inqList.filter(x => INQ_ACTIVE.includes(x.status)).length;
    el.textContent = n ? String(n) : '';
}

function inqFind(id) { return _inqList.find(x => x.id === id) || null; }

// 상담 건 수정 (+ 선택적으로 자동 기록 한 줄)
async function inqPatch(id, patch, systemLog) {
    patch.updated_at = new Date().toISOString();
    const { data, error } = await sb.from('inquiries').update(patch).eq('id', id).select().single();
    if (error) { showToast('저장 실패: ' + error.message); return null; }
    const i = _inqList.findIndex(x => x.id === id);
    if (i >= 0) _inqList[i] = data; else _inqList.unshift(data);
    if (systemLog) await inqAddLog(id, { direction: 'system', body: systemLog });
    inqRenderChips(); inqRenderList(); inqUpdateSwitchCount();
    return data;
}

async function inqAddLog(id, log) {
    const row = {
        inquiry_id: id,
        direction: log.direction || 'memo',
        channel: log.channel || '',
        body: log.body || '',
        images: Array.isArray(log.images) ? log.images : [],
        author: log.direction === 'system' ? '' : ((currentUser && currentUser.name) || '')
    };
    const { data, error } = await sb.from('inquiry_logs').insert(row).select().single();
    if (error) { showToast('기록 실패: ' + error.message); return null; }
    if (_inqSel === id && document.getElementById('inqTimeline')) {
        _inqLogs.push(data);
        inqRenderTimeline();
    }
    // 기록(상태 변경 등 자동 기록 포함)이 생기면 목록 시간·순서도 최신으로 (DB는 트리거 inquiry_logs_touch_inquiry가 맞춤)
    const it = (typeof _inqList !== 'undefined') && _inqList.find(r => r.id === id);
    const at = (data && data.at) || new Date().toISOString();
    if (it && String(it.last_contact_at || '') < at) {
        it.last_contact_at = at;
        if (document.getElementById('inqList')) inqRenderList();
    }
    return data;
}

// ---------- 날짜 표시 ----------
// '카톡으로' / '전화로' — 받침 있으면(ㄹ 제외) '으로'
function inqJosaRo(w) {
    const c = String(w || '').slice(-1).charCodeAt(0);
    if (c >= 0xAC00 && c <= 0xD7A3) { const jong = (c - 0xAC00) % 28; return w + (jong && jong !== 8 ? '으로' : '로'); }
    return w + '로';
}
function inqMD(d) { if (!d) return ''; const p = String(d).split('-'); return `${+p[1]}/${+p[2]}`; }
function inqTime(ts) { const t = new Date(ts); return `${String(t.getHours()).padStart(2, '0')}:${String(t.getMinutes()).padStart(2, '0')}`; }
function inqDayLabel(ts) { const t = new Date(ts); return `${t.getFullYear()}.${t.getMonth() + 1}.${t.getDate()} (${'일월화수목금토'[t.getDay()]})`; }
function inqRel(ts) {
    if (!ts) return '';
    const m = (Date.now() - new Date(ts).getTime()) / 60000;
    if (m < 1) return '방금';
    if (m < 60) return Math.floor(m) + '분 전';
    if (m < 1440) return Math.floor(m / 60) + '시간 전';
    const d = Math.floor(m / 1440);
    if (d < 7) return d + '일 전';
    const t = new Date(ts);
    return `${t.getMonth() + 1}/${t.getDate()}`;
}
function inqIsOverdue(x) {
    return !!(x && x.next_action && x.next_action_date && INQ_ACTIVE.includes(x.status) && x.next_action_date <= getTodayStr());
}

// ---------- 목록 ----------
function inqFiltered() {
    const q = ((document.getElementById('inqSearch') || {}).value || '').trim().toLowerCase();
    let list = _inqList;
    if (_inqFilter === 'active') list = list.filter(x => INQ_ACTIVE.includes(x.status));
    else if (_inqFilter !== 'all') list = list.filter(x => x.status === _inqFilter);
    if (q) list = list.filter(x =>
        [x.client, x.title, x.client_contact, x.contact_name, x.contact_dept, x.contact_phone, x.contact_email, x.purpose, inqItemsSummary(x.items)]
            .some(v => String(v || '').toLowerCase().includes(q)));
    // 정렬: '최근순'(기본) = 최근 연락 순 / '급한 일 먼저' = 오늘·지난 할 일 있는 상담 먼저 → 최근 연락 순
    const urgentFirst = _inqSort === 'urgent';
    return list.slice().sort((a, b) => {
        if (urgentFirst) {
            const ao = inqIsOverdue(a) ? 0 : 1, bo = inqIsOverdue(b) ? 0 : 1;
            if (ao !== bo) return ao - bo;
        }
        return String(b.last_contact_at || b.created_at || '').localeCompare(String(a.last_contact_at || a.created_at || ''));
    });
}
let _inqSort = (() => { try { return localStorage.getItem('inq_sort') === 'urgent' ? 'urgent' : 'recent'; } catch (_) { return 'recent'; } })();

function inqRenderChips() {
    const el = document.getElementById('inqChips');
    if (!el) return;
    const cnt = s => _inqList.filter(x => x.status === s).length;
    const act = _inqList.filter(x => INQ_ACTIVE.includes(x.status)).length;
    const chips = [['active', '진행 중', act]].concat(INQ_STATUSES.map(s => [s, s, cnt(s)])).concat([['all', '전체', _inqList.length]]);
    const urgentN = _inqList.filter(inqIsOverdue).length;
    el.innerHTML = chips.map(([k, l, n]) =>
        `<button class="inq-chip ${_inqFilter === k ? 'on' : ''}" data-f="${escHtml(k)}">${escHtml(l)}<b>${n}</b></button>`).join('') +
        `<div class="inq-sort"><span>정렬</span>
            <button class="${_inqSort === 'recent' ? 'on' : ''}" data-sort="recent">최근순</button>
            <button class="${_inqSort === 'urgent' ? 'on' : ''}" data-sort="urgent">급한 일 먼저${urgentN ? `<b>${urgentN}</b>` : ''}</button>
        </div>`;
    el.querySelectorAll('[data-f]').forEach(b => b.addEventListener('click', () => {
        _inqFilter = b.dataset.f; inqRenderChips(); inqRenderList();
    }));
    el.querySelectorAll('[data-sort]').forEach(b => b.addEventListener('click', () => {
        _inqSort = b.dataset.sort;
        try { localStorage.setItem('inq_sort', _inqSort); } catch (_) {}
        inqRenderChips(); inqRenderList();
    }));
}

function inqRenderList() {
    const el = document.getElementById('inqList');
    if (!el) return;
    const list = inqFiltered();
    if (!list.length) {
        el.innerHTML = `<div class="inq-empty">${_inqList.length
            ? '조건에 맞는 상담이 없습니다'
            : '아직 상담 기록이 없습니다.<br><b>새 상담</b>으로 첫 문의를 등록해보세요.'}</div>`;
        return;
    }
    el.innerHTML = list.map(x => {
        const late = inqIsOverdue(x);
        const who = x.contact_name || x.client_contact || '';
        // 회사명을 가장 크게 — 등급·상태·시간은 위 작은 줄, 담당자·제목은 아래
        return `<div class="inq-item ${x.id === _inqSel ? 'on' : ''}" data-id="${x.id}">
            <div class="inq-item-tags">
                ${clientGradeBadge(x.grade)}<span class="inq-st ${INQ_STATUS_CLS[x.status] || ''}">${escHtml(x.status)}</span>
                <span class="inq-item-when">${x.assignee ? `${escHtml(x.assignee)} · ` : ''}${inqRel(x.last_contact_at)}</span>
            </div>
            <div class="inq-client">${escHtml(x.client || '(거래처 미정)')}${who ? `<em>${escHtml(who)}</em>` : ''}</div>
            ${x.title ? `<div class="inq-title">${escHtml(x.title)}</div>` : ''}
            ${x.next_action ? `<div class="inq-next ${late ? 'late' : ''}">▶ ${x.next_action_date ? inqMD(x.next_action_date) + ' · ' : ''}${escHtml(x.next_action)}</div>` : ''}
        </div>`;
    }).join('');
    el.querySelectorAll('[data-id]').forEach(d => d.addEventListener('click', () => {
        _inqSel = Number(d.dataset.id);
        inqRenderList(); inqRenderDetail();
    }));
}

// ---------- 상세 ----------
function inqOpt(arr, v) { return arr.map(a => `<option value="${escHtml(a)}" ${a === v ? 'selected' : ''}>${escHtml(a)}</option>`).join(''); }

async function inqRenderDetail() {
    const el = document.getElementById('inqDetail');
    if (!el) return;
    if (_inqSel === 'new') { inqRenderNewForm(); return; }
    const x = inqFind(_inqSel);
    if (!x) {
        el.innerHTML = `<div class="inq-placeholder">
            <svg width="40" height="40" fill="none" stroke="currentColor" stroke-width="1.6" viewBox="0 0 24 24"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/></svg>
            <div>왼쪽에서 상담을 고르거나 <b>새 상담</b>을 등록하세요</div></div>`;
        return;
    }
    const people = inqPeople();
    const assigneeOpts = `<option value="">-</option>` + inqOpt(people.includes(x.assignee) || !x.assignee ? people : people.concat([x.assignee]), x.assignee);
    // 고객 정보가 채워져 있으면 한 줄 요약으로 접어둔다 (화면을 단계·기록에 양보)
    el.innerHTML = `
      <div class="inq-head">
        <div class="inq-head-row">
          <input class="inq-h-client" id="inqFClient" list="tempClientList" value="${escHtml(x.client || '')}" placeholder="거래처">
          <select class="inq-h-status ${INQ_STATUS_CLS[x.status] || ''}" id="inqFStatus">${inqOpt(INQ_STATUSES, x.status)}</select>
          <select class="inq-h-grade g-${escHtml(x.grade || 'none')}" id="inqFGrade" title="거래처 등급 — 바꾸면 거래처 DB 등급도 같이 바뀌어요">${clientGradeOptions(x.grade || '')}</select>
          <input class="inq-h-title" id="inqFTitle" value="${escHtml(x.title || '')}" placeholder="무엇을 문의했나요? 예) 손목시계 300개 각인 견적">
          <button class="inq-send-btn" id="inqFSend" type="button">📤 보내기</button>
          <button class="inq-icon-btn" id="inqFDelete" title="상담 삭제">
            <svg width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M4 7h16M10 11v6M14 11v6M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2l1-12M9 7V4h6v3"/></svg>
          </button>
        </div>
        <div class="inq-hfields" id="inqFields">
          <div class="inq-hf-row">
            <span class="inq-hf-cap">담당자</span>
            <label><span>이름</span><input id="inqFCName" value="${escHtml(x.contact_name || x.client_contact || '')}" placeholder="이름"></label>
            <label><span>직함</span><input id="inqFCTitle" value="${escHtml(x.contact_title || '')}" placeholder="예) 과장"></label>
            <label><span>부서</span><input id="inqFCDept" value="${escHtml(x.contact_dept || '')}" placeholder="예) 총무팀"></label>
            <label><span>연락처</span><input id="inqFCPhone" inputmode="tel" value="${escHtml(x.contact_phone || '')}" placeholder="010-0000-0000"></label>
            <label class="w3"><span>이메일</span><input id="inqFCEmail" type="email" value="${escHtml(x.contact_email || '')}" placeholder="name@company.com"></label>
          </div>
          <div class="inq-hf-row">
            <span class="inq-hf-cap">회사</span>
            <label class="w2"><span>회사 주소</span><input id="inqFCAddr" value="${escHtml(x.company_address || '')}" placeholder="회사 주소"></label>
            <label><span>팩스</span><input id="inqFCFax" inputmode="tel" value="${escHtml(x.company_fax || '')}" placeholder="02-0000-0000"></label>
            <label><span>홈페이지</span><input id="inqFCWeb" value="${escHtml(x.company_website || '')}" placeholder="www.company.co.kr"></label>
            <label><span>문의 경로</span><select id="inqFChannel">${inqOpt(INQ_CHANNELS, x.channel)}</select></label>
            <label><span>우리 담당</span><select id="inqFAssignee">${assigneeOpts}</select></label>
            <label><span>시작일</span><input type="date" id="inqFStarted" value="${escHtml(x.started_at || '')}"></label>
          </div>
        </div>
        <div class="inq-stage" id="inqStage"></div>
        ${x.status === '실패' && x.fail_reason ? `<div class="inq-fail">실패 사유 · ${escHtml(x.fail_reason)}</div>` : ''}
      </div>
      <div class="inq-body2">
        <div class="inq-main">
          <div class="inq-timeline" id="inqTimeline"><div class="inq-empty">불러오는 중…</div></div>
          <div class="inq-composer">
            <div class="inq-comp-top">
              <div class="inq-dir" id="inqDir">
                <button data-dir="in">고객</button><button data-dir="out">우리 답변</button><button data-dir="memo">내부 메모</button>
              </div>
              <select id="inqCChannel">${inqOpt(INQ_CHANNELS, x.channel)}</select>
              <label class="inq-attach" title="사진 첨부 (Ctrl+V로 붙여넣기도 됩니다)">
                <svg width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="9" cy="11" r="2"/><path d="M21 16l-5-5-8 8"/></svg>
                <input type="file" accept="image/*" multiple id="inqCFile" hidden>
              </label>
              <div class="inq-spacer"></div>
              <span class="inq-comp-hint">사진은 Ctrl+V · Ctrl+Enter 저장</span>
            </div>
            <div class="inq-comp-body">
              <textarea id="inqCBody" rows="2" placeholder="오간 내용을 그대로 적거나 카톡 대화를 붙여넣으세요"></textarea>
              <button class="btn-primary" id="inqCSave">기록</button>
            </div>
            <div class="inq-img-notice" id="inqCImgNotice" hidden></div>
            <div class="inq-thumbs" id="inqCThumbs"></div>
          </div>
        </div>
        <aside class="inq-side">
          <div id="inqNow"></div>
          <section class="inq-card"><div class="inq-todos" id="inqTodos"><div class="inq-todo-head"><b>다음 할 일</b><em>불러오는 중…</em></div></div></section>
          <section class="inq-card inq-req" id="inqReq"></section>
          <section class="inq-card inq-pre" id="inqPre"></section>
          <section class="inq-card inq-quotes" id="inqQuotes"></section>
          <section class="inq-card inq-projs" id="inqProjs"></section>
        </aside>
      </div>`;
    _inqComposerImages.length = 0;
    _inqTodos = [];
    if (_inqProjsFor !== x.id) { _inqProjs = []; _inqProjsFor = null; }
    if (_inqPreEditing !== x.id) _inqPreEditing = null;
    inqBindDetail(x);
    inqRenderReq(x);
    inqRenderPre(x);
    inqRenderQuotes(x);
    inqLoadDeal(x);
    inqSetDir(_inqDir);
    inqLoadTodos(x);
    await inqLoadLogs(x.id);
}

function inqBindDetail(x) {
    const $ = id => document.getElementById(id);
    const saveField = (id, key, norm) => {
        const el = $(id); if (!el) return;
        el.addEventListener('change', () => {
            let v = el.value.trim();
            if (norm) { v = norm(v); el.value = v; }
            const cur = key === 'contact_name' ? (x.contact_name || x.client_contact || '') : (x[key] || '');
            if (cur === v) return;
            inqPatch(x.id, { [key]: v || (key === 'started_at' ? null : '') }).then(d => {
                if (!d) return;
                Object.assign(x, d);
                const sum = $('inqCISum'); if (sum) sum.innerHTML = inqContactSummary(x);
                if (key === 'started_at') inqRenderStage(x);
            });
        });
    };
    if ($('inqCIToggle')) $('inqCIToggle').addEventListener('click', () => {
        const f = $('inqFields');
        f.hidden = !f.hidden;
        $('inqCIToggle').textContent = f.hidden ? '편집' : '접기';
        if (!f.hidden) { const n = $('inqFCName'); if (n) n.focus(); }
    });
    saveField('inqFClient', 'client');
    $('inqFClient').addEventListener('change', () => setTimeout(() => clientAutoAddNotice([$('inqFClient').value]), 600));
    saveField('inqFTitle', 'title');
    saveField('inqFCName', 'contact_name');
    saveField('inqFCDept', 'contact_dept');
    saveField('inqFCTitle', 'contact_title');
    saveField('inqFCPhone', 'contact_phone', inqNormPhone);
    saveField('inqFCEmail', 'contact_email');
    saveField('inqFChannel', 'channel');
    saveField('inqFAssignee', 'assignee');
    saveField('inqFStarted', 'started_at');
    saveField('inqFGrade', 'grade');
    $('inqFGrade').addEventListener('change', () => { $('inqFGrade').className = 'inq-h-grade g-' + ($('inqFGrade').value || 'none'); });
    saveField('inqFCAddr', 'company_address');
    saveField('inqFCFax', 'company_fax', inqNormPhone);
    saveField('inqFCWeb', 'company_website');


    $('inqFStatus').addEventListener('change', async (e) => {
        const nv = e.target.value, ov = x.status;
        if (nv === ov) return;
        const patch = { status: nv };
        let log = `상태 변경 · ${ov} → ${nv}`;
        if (nv === '실패') {
            const r = prompt('실패 사유를 적어주세요\n예) 단가 안 맞음 / 납기 / 연락 두절 / 타사 선택', x.fail_reason || '');
            if (r === null) { e.target.value = ov; return; }
            patch.fail_reason = r.trim();
            if (r.trim()) log += ` (사유: ${r.trim()})`;
        }
        const d = await inqPatch(x.id, patch, log);
        if (d) inqRenderDetail();
    });

    $('inqFSend').addEventListener('click', e => inqSendMenu(x, e.currentTarget));
    $('inqFDelete').addEventListener('click', async () => {
        if (!confirm(`'${x.client || '이 상담'}' 상담과 모든 기록을 삭제할까요?\n연결된 견적 품목은 그대로 남습니다.`)) return;
        const { error } = await sb.from('inquiries').delete().eq('id', x.id);
        if (error) { showToast('삭제 실패: ' + error.message); return; }
        _inqList = _inqList.filter(i => i.id !== x.id);
        tempProjects.forEach(p => { if (p.inquiryId === x.id) p.inquiryId = null; });
        _inqSel = null;
        inqRenderChips(); inqRenderList(); inqRenderDetail(); inqUpdateSwitchCount();
        showToast('상담을 삭제했습니다');
    });

    // 작성기 — 방향 전환, 저장, 사진(파일 선택·붙여넣기·끌어놓기)
    $('inqDir').querySelectorAll('[data-dir]').forEach(b => b.addEventListener('click', () => inqSetDir(b.dataset.dir)));
    $('inqCSave').addEventListener('click', inqSubmit);
    $('inqCBody').addEventListener('keydown', e => {
        if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); inqSubmit(); }
    });
    const redraw = () => inqThumbs(_inqComposerImages, 'inqCThumbs');
    inqBindImageInput($('inqCBody'), _inqComposerImages, redraw, 'inqCImgNotice');
    $('inqCFile').addEventListener('change', async (ev) => {
        await inqAddImageFiles(ev.target.files, _inqComposerImages, redraw);
        ev.target.value = '';
    });
}

function inqSetDir(d) {
    _inqDir = INQ_DIR_LABEL[d] ? d : 'in';
    const box = document.getElementById('inqDir');
    if (box) box.querySelectorAll('[data-dir]').forEach(b => b.classList.toggle('on', b.dataset.dir === _inqDir));
    const ta = document.getElementById('inqCBody');
    if (ta) ta.placeholder = _inqDir === 'in' ? '고객이 한 말 · 카톡 대화를 그대로 붙여넣어도 됩니다'
        : _inqDir === 'out' ? '우리가 어떻게 답변했는지'
        : '팀끼리만 보는 메모 (고객에게 안 나감)';
}

// (사진 여러 장 지원으로 inqThumbs로 대체됨 — 호출 호환용)
function inqRenderComposerPreview() {
    inqThumbs(_inqComposerImages, 'inqCThumbs');
}

async function inqSubmit() {
    const x = inqFind(_inqSel);
    if (!x) return;
    const body = document.getElementById('inqCBody').value.trim();
    if (!body && !_inqComposerImages.length) { showToast('내용을 입력하거나 사진을 붙여넣으세요'); return; }
    const btn = document.getElementById('inqCSave');
    btn.disabled = true;
    const saved = await inqAddLog(x.id, {
        direction: _inqDir,
        channel: _inqDir === 'memo' ? '' : document.getElementById('inqCChannel').value,   // 내부 메모엔 경로 없음
        body, images: _inqComposerImages.slice()
    });
    btn.disabled = false;
    if (!saved) return;
    document.getElementById('inqCBody').value = '';
    _inqComposerImages.length = 0;
    inqThumbs(_inqComposerImages, 'inqCThumbs');

    // 고객·우리 대화면 마지막 연락 갱신, 우리가 처음 답하면 신규 → 상담중
    if (_inqDir !== 'memo') {
        const patch = { last_contact_at: new Date().toISOString() };
        const bump = x.status === '신규' && _inqDir === 'out';
        if (bump) patch.status = '상담중';
        const d = await inqPatch(x.id, patch, bump ? '상태 변경 · 신규 → 상담중' : null);
        if (d && bump) {
            Object.assign(x, d);
            const sel = document.getElementById('inqFStatus');
            if (sel) { sel.value = d.status; sel.className = 'inq-h-status ' + (INQ_STATUS_CLS[d.status] || ''); }
        }
    }
    document.getElementById('inqCBody').focus();
}

// ---------- 타임라인 ----------
async function inqLoadLogs(id) {
    const { data, error } = await sb.from('inquiry_logs').select('*').eq('inquiry_id', id).order('at', { ascending: true });
    if (_inqSel !== id) return;
    if (error) {
        const el = document.getElementById('inqTimeline');
        if (el) el.innerHTML = `<div class="inq-empty">기록을 불러오지 못했습니다: ${escHtml(error.message)}</div>`;
        return;
    }
    _inqLogs = data || [];
    inqRenderTimeline();
}

function inqRenderTimeline(keepScroll) {
    const el = document.getElementById('inqTimeline');
    if (!el) return;
    if (!_inqLogs.length) {
        el.innerHTML = '<div class="inq-empty">아직 기록이 없습니다.<br>아래에 첫 대화를 남겨보세요.</div>';
        return;
    }
    const prevScroll = el.scrollTop;
    let html = '', lastDay = '';
    _inqLogs.forEach(l => {
        const day = inqDayLabel(l.at);
        if (day !== lastDay) { html += `<div class="inq-day"><span>${day}</span></div>`; lastDay = day; }
        if (l.direction === 'system') {
            html += `<div class="inq-sys"><span>${escHtml(l.body)}</span><em>${inqTime(l.at)}</em></div>`;
            return;
        }
        const imgs = inqLogImages(l);
        html += `<div class="inq-msg d-${escHtml(l.direction)}" data-lid="${l.id}">
            <div class="inq-msg-meta">
                <b>${escHtml(INQ_DIR_LABEL[l.direction] || '')}</b>
                ${l.channel ? `<span>${escHtml(l.channel)}</span>` : ''}
                ${l.author ? `<span>${escHtml(l.author)}</span>` : ''}
                <span>${inqTime(l.at)}</span>
                ${l.edited_at ? `<span class="inq-edited" title="${escHtml(inqDayLabel(l.edited_at) + ' ' + inqTime(l.edited_at))} 수정">수정됨</span>` : ''}
                <span class="inq-msg-acts">
                    <button class="inq-msg-btn" data-edit="${l.id}" title="이 기록 수정">
                        <svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" viewBox="0 0 24 24"><path d="M4 20h4L19 9l-4-4L4 16v4zM14 6l4 4"/></svg></button>
                    <button class="inq-msg-btn del" data-del="${l.id}" title="이 기록 삭제">
                        <svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.2" viewBox="0 0 24 24"><path d="M4 7h16M10 11v6M14 11v6M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2l1-12M9 7V4h6v3"/></svg></button>
                </span>
            </div>
            ${l.body ? `<div class="inq-msg-body">${escHtml(l.body).replace(/\n/g, '<br>')}</div>` : ''}
            ${imgs.length ? `<div class="inq-msg-imgs">${imgs.map(s => `<img class="inq-msg-img" src="${escHtml(s)}" alt="첨부 사진">`).join('')}</div>` : ''}
        </div>`;
    });
    el.innerHTML = html;
    el.scrollTop = keepScroll ? prevScroll : el.scrollHeight;
    el.querySelectorAll('[data-del]').forEach(b => b.addEventListener('click', async () => {
        if (!confirm('이 기록을 삭제할까요?')) return;
        const id = Number(b.dataset.del);
        const { error } = await sb.from('inquiry_logs').delete().eq('id', id);
        if (error) { showToast('삭제 실패: ' + error.message); return; }
        _inqLogs = _inqLogs.filter(l => l.id !== id);
        inqRenderTimeline(true);
    }));
    el.querySelectorAll('[data-edit]').forEach(b => b.addEventListener('click', () => inqEditLog(Number(b.dataset.edit))));
    el.querySelectorAll('.inq-msg-img').forEach(img => img.addEventListener('click', () => img.classList.toggle('zoom')));
}

function inqLogImages(l) {
    return (Array.isArray(l.images) && l.images.length) ? l.images : (l.image ? [l.image] : []);
}

// 기록 수정 — 글 · 사진(빼기/붙여넣기) · 누가 한 말인지 · 경로
function inqEditLog(id) {
    const el = document.getElementById('inqTimeline');
    const l = _inqLogs.find(v => v.id === id);
    const box = el && el.querySelector(`[data-lid="${id}"]`);
    if (!l || !box) return;
    const imgs = inqLogImages(l).slice();
    box.classList.add('editing');
    box.innerHTML = `
        <div class="inq-edit-top">
          <div class="inq-dir" id="inqEDir">
            <button data-dir="in">고객</button><button data-dir="out">우리 답변</button><button data-dir="memo">내부 메모</button>
          </div>
          <select id="inqEChannel">${inqOpt(INQ_CHANNELS, l.channel || '')}</select>
        </div>
        <textarea id="inqEBody" rows="${Math.min(14, Math.max(3, String(l.body || '').split('\n').length + 1))}" placeholder="내용 (사진은 Ctrl+V로 추가)">${escHtml(l.body || '')}</textarea>
        <div class="inq-img-notice" id="inqEImgNotice" hidden></div>
        <div class="inq-thumbs" id="inqEThumbs"></div>
        <div class="inq-edit-act">
          <span>Ctrl+Enter 저장 · Esc 취소</span>
          <button type="button" class="btn-ghost" id="inqECancel">취소</button>
          <button type="button" class="btn-primary" id="inqESave">저장</button>
        </div>`;
    let dir = l.direction;
    const $ = i => document.getElementById(i);
    const setDir = d => {
        dir = d;
        $('inqEDir').querySelectorAll('[data-dir]').forEach(b => b.classList.toggle('on', b.dataset.dir === d));
        $('inqEChannel').style.display = d === 'memo' ? 'none' : '';
    };
    setDir(dir);
    if (!l.channel) $('inqEChannel').value = inqFind(_inqSel) ? (inqFind(_inqSel).channel || INQ_CHANNELS[0]) : INQ_CHANNELS[0];
    $('inqEDir').querySelectorAll('[data-dir]').forEach(b => b.addEventListener('click', () => setDir(b.dataset.dir)));
    const redraw = () => inqThumbs(imgs, 'inqEThumbs');
    redraw();
    inqBindImageInput($('inqEBody'), imgs, redraw, 'inqEImgNotice');
    const ta = $('inqEBody');
    ta.focus();
    ta.setSelectionRange(ta.value.length, ta.value.length);

    const cancel = () => inqRenderTimeline(true);
    const save = async () => {
        const body = ta.value.trim();
        if (!body && !imgs.length) { showToast('내용이 비었습니다. 지우려면 삭제를 눌러주세요'); return; }
        const patch = { body, images: imgs.slice(), direction: dir, channel: dir === 'memo' ? '' : $('inqEChannel').value, edited_at: new Date().toISOString() };
        $('inqESave').disabled = true;
        const { data, error } = await sb.from('inquiry_logs').update(patch).eq('id', id).select().single();
        if (error) { $('inqESave').disabled = false; showToast('수정 실패: ' + error.message); return; }
        Object.assign(l, data);
        inqRenderTimeline(true);
        showToast('기록을 수정했습니다');
    };
    $('inqECancel').addEventListener('click', cancel);
    $('inqESave').addEventListener('click', save);
    ta.addEventListener('keydown', e => {
        if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); save(); }
        else if (e.key === 'Escape') { e.preventDefault(); cancel(); }
    });
}

// ---------- 견적 연결 ----------
function inqRefreshQuotes() {
    const x = inqFind(_inqSel);
    if (x && document.getElementById('inqQuotes')) inqRenderQuotes(x);
}

// 견적 부대비용 한 줄 — '인쇄 레이저각인 · 개당 500원 = 150,000원 (VAT별도)'
function inqFeeLines(p, sup) {
    const q = p.qty || 0;
    const won = n => Number(n || 0).toLocaleString() + '원';
    const vat = v => v === 'VAT 포함' ? 'VAT포함' : 'VAT별도';
    const f = sup
        ? [['인쇄', p.supPrintMethod, p.supPrintFee, p.supPrintFeeApply, p.supPrintFeeVat],
           ['포장', p.supPackMethod, p.supPackagingFee, p.supPackagingFeeApply, p.supPackagingFeeVat],
           ['라벨', '', p.supLabelFee, p.supLabelFeeApply || '1개당', p.supLabelFeeVat]]
        : [['인쇄', p.printMethod, p.printFee, p.printFeeApply, p.printFeeVat],
           ['포장', p.packMethod, p.packagingFee, p.packagingFeeApply, p.packagingFeeVat],
           ['라벨', '', p.labelFee, p.labelFeeApply || '1개당', p.labelFeeVat]];
    const out = [];
    f.forEach(([name, method, fee, apply, v]) => {
        const m = method && method !== '없음' && method !== '기본박스' ? method : '';
        const total = calcTempFeeTotal(fee, apply, q);
        if (!total && !(name === '인쇄' && m)) return;
        let t = name + (m ? ' ' + m : '');
        if (total) t += (apply === '1개당' ? ` · 개당 ${won(fee)} = ${won(total)}` : ` · 일괄 ${won(total)}`) + ` (${vat(v)})`;
        out.push(t);
    });
    const boxes = sup ? p.supShippingBoxes : p.shippingBoxes, sf = sup ? p.supShippingFee : p.shippingFee;
    if (boxes && sf) out.push(`택배 ${boxes}박스 × ${won(sf)} = ${won(boxes * sf)} (${vat(sup ? p.supShippingFeeVat : p.shippingFeeVat)})`);
    return out;
}

function inqQuoteGroupIndex(date, client) {
    if (!tempGroups.length) renderTempProjects();
    return tempGroups.findIndex(g => g.key === (date || '') + '||' + (client || ''));
}

function inqRenderQuotes(x) {
    const el = document.getElementById('inqQuotes');
    if (!el) return;
    const linked = tempProjects.filter(p => p.inquiryId === x.id);
    const rev = linked.reduce((s, p) => s + calcTempRevenueWithVat(p), 0);
    const sup = linked.reduce((s, p) => s + calcTempSupRevenueWithVat(p), 0);
    const cands = inqLinkCands(x);

    // 견적 묶음(날짜+매출처)별 — 견적 목록과 같은 기준
    const groups = [];
    linked.slice().sort((a, b) => String(b.date).localeCompare(String(a.date)) || ((a.sortOrder ?? a.id) - (b.sortOrder ?? b.id))).forEach(p => {
        const key = (p.date || '') + '||' + (p.client || '');
        let g = groups.find(q => q.key === key);
        if (!g) { g = { key, date: p.date, client: p.client, contact: p.clientContact, note: '', items: [] }; groups.push(g); }
        if (!g.note && p.quoteNote) g.note = p.quoteNote;
        g.items.push(p);
    });

    let open = true;
    try { open = localStorage.getItem('inq_q_open') !== '0'; } catch (_) {}
    const won = n => Number(n || 0).toLocaleString() + '원';
    const dash = '<span class="inq-qt-dash">-</span>';
    const unitTag = (n, v) => `<small>단가 ${won(n)}</small><small class="${v === 'VAT 포함' ? 'inc' : ''}">${v === 'VAT 포함' ? 'VAT포함' : 'VAT별도'}</small>`;
    const marginCell = (r, s) => {
        if (!s) return dash;
        const m = r - s, pct = r > 0 ? Math.round(m / r * 100) : 0;
        return `<b class="${m >= 0 ? 'pos' : 'neg'}">${won(m)}</b><small>${pct}%</small>`;   // 카드에서는 % 가 아래 작은 글씨
    };
    const sub = lines => lines.length ? `<div class="inq-qt-sub">${lines.map(l => `<div>+ ${escHtml(l)}</div>`).join('')}</div>` : '';

    const body = groups.map(g => {
        const gRev = g.items.reduce((s, p) => s + calcTempRevenueWithVat(p), 0);
        const gSup = g.items.reduce((s, p) => s + calcTempSupRevenueWithVat(p), 0);
        const done = g.items.some(p => p.transferredAt);
        return `
        <div class="inq-qg">
          <div class="inq-qg-head">
            <b>${escHtml(String(g.date || '').replace(/-/g, '.'))} 견적</b>
            <span>${escHtml(g.client || '')}${g.contact ? ' · ' + escHtml(g.contact) : ''} · ${g.items.length}품목</span>
            ${done ? '<span class="inq-q-done">매입매출 등록됨</span>' : ''}
            <div class="inq-spacer"></div>
            <button class="inq-mini" data-qedit="${escHtml(g.key)}">편집</button>
            <button class="inq-mini" data-qdoc="${escHtml(g.key)}">견적서</button>
          </div>
          <div class="inq-qi-list">${g.items.map(p => inqQuoteItemHtml(p)).join('')}
          ${g.items.length > 1 ? `<div class="inq-qi inq-qi-total"><div class="inq-qi-nums">
              <div><em>합계 판매 (VAT포함)</em><b class="rev">${won(gRev)}</b></div>
              <div><em>합계 매입 (VAT포함)</em>${gSup ? `<b class="sup">${won(gSup)}</b>` : dash}</div>
              <div><em>합계 마진</em>${marginCell(gRev, gSup)}</div>
          </div></div>` : ''}
          </div>
          ${g.note ? `<div class="inq-qg-note"><span>견적 메모</span>${escHtml(g.note)}</div>` : ''}
        </div>`;
    }).join('');

    const m = rev - sup, pct = rev > 0 ? Math.round(m / rev * 100) : 0;
    el.innerHTML = `
      <div class="inq-q-head">
        ${linked.length ? `<button class="inq-q-toggle ${open ? 'on' : ''}" id="inqQToggle" title="${open ? '접기' : '펼치기'}">
          <svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4" viewBox="0 0 24 24"><path d="M9 6l6 6-6 6"/></svg></button>` : ''}
        <b>연결된 견적</b>
        ${linked.length ? `<span class="inq-q-sum">
            <em>${groups.length}건 · ${linked.length}품목</em>
            <em>매출 <b class="rev">${won(rev)}</b></em>
            ${sup ? `<em>매입 <b class="sup">${won(sup)}</b></em><em>마진 <b class="${m >= 0 ? 'pos' : 'neg'}">${won(m)} (${pct}%)</b></em>` : ''}
          </span>` : '<span>아직 없음</span>'}
        <div class="inq-spacer"></div>
        ${cands.length ? `<button class="inq-mini" id="inqQLink">🔗 기존 견적 연결${cands.some(c => c.same) ? ` <b class="inq-qlink-n">${cands.filter(c => c.same).length}</b>` : ''}</button>` : ''}
        <button class="inq-mini primary" id="inqQStart">+ 이 상담으로 견적 작성</button>
      </div>
      ${linked.length && open ? `<div class="inq-q-body">${body}</div>` : ''}`;
    document.getElementById('inqQStart').addEventListener('click', () => inqStartQuote(x.id));
    const lk = document.getElementById('inqQLink');
    if (lk) lk.addEventListener('click', () => inqOpenQuoteLinkPicker(x));
    const tg = document.getElementById('inqQToggle');
    if (tg) tg.addEventListener('click', () => {
        try { localStorage.setItem('inq_q_open', open ? '0' : '1'); } catch (_) {}
        inqRenderQuotes(x);
    });
    const byKey = k => { const i = k.indexOf('||'); return inqQuoteGroupIndex(k.slice(0, i), k.slice(i + 2)); };
    el.querySelectorAll('[data-qedit]').forEach(b => b.addEventListener('click', () => { const gi = byKey(b.dataset.qedit); if (gi >= 0) openTempGroupEdit(gi); }));
    el.querySelectorAll('[data-qdoc]').forEach(b => b.addEventListener('click', () => { const gi = byKey(b.dataset.qdoc); if (gi >= 0) openTempQuote(gi); }));
    inqRenderStage(x);
}

// 아직 상담에 연결 안 된 견적 묶음(날짜+매출처) — 같은 거래처((주)·공백 무시)가 먼저, 그다음 최근 순
function inqLinkCands(x) {
    const key = clientNameKey(x.client || '');
    const out = [];
    tempProjects.filter(p => !p.inquiryId).forEach(p => {
        const k = (p.date || '') + '||' + (p.client || '');
        let g = out.find(c => c.key === k);
        if (!g) {
            g = { key: k, date: p.date || '', client: p.client || '', contact: p.clientContact || '', items: [], rev: 0,
                  same: !!key && clientNameKey(p.client || '') === key };
            out.push(g);
        }
        g.items.push(p);
        g.rev += calcTempRevenueWithVat(p);
    });
    return out.sort((a, b) => (b.same - a.same) || String(b.date).localeCompare(String(a.date)));
}

// '🔗 기존 견적 연결' — 견적 고르기 창 (같은 거래처 먼저, 검색으로 다른 견적도)
function inqOpenQuoteLinkPicker(x) {
    const cands = inqLinkCands(x);
    if (!cands.length) { showToast('연결할 수 있는 견적이 없습니다 (모두 다른 상담에 연결됨)'); return; }
    const old = document.getElementById('inqQLinkPick');
    if (old) old.remove();
    const ov = document.createElement('div');
    ov.id = 'inqQLinkPick';
    ov.className = 'inq-qlp';
    ov.innerHTML = `
      <div class="inq-qlp-box" role="dialog" aria-label="기존 견적 연결">
        <div class="inq-qlp-head"><b>기존 견적 연결</b><span>${escHtml(x.client || '')} 상담에 먼저 만들어 둔 견적을 붙여요</span>
          <div class="inq-spacer"></div><button type="button" class="inq-qlp-x" data-qlp="close" aria-label="닫기">✕</button></div>
        <input type="search" class="inq-qlp-q" placeholder="거래처·품목·담당자로 찾기" autocomplete="off">
        <div class="inq-qlp-list"></div>
      </div>`;
    document.body.appendChild(ov);
    const listEl = ov.querySelector('.inq-qlp-list');
    const q = ov.querySelector('.inq-qlp-q');
    const won = n => Number(n || 0).toLocaleString() + '원';
    const row = c => `
        <button type="button" class="inq-qlp-row" data-key="${escHtml(c.key)}">
          <span class="inq-qlp-d">${escHtml(String(c.date).replace(/-/g, '.'))}</span>
          <span class="inq-qlp-m"><b>${escHtml(c.client || '(거래처 없음)')}</b>${c.contact ? `<em>${escHtml(c.contact)}</em>` : ''}
            <small>${escHtml(c.items.map(p => p.item + (p.qty ? ' ' + Number(p.qty).toLocaleString() + '개' : '')).slice(0, 3).join(' · '))}${c.items.length > 3 ? ` 외 ${c.items.length - 3}` : ''}</small></span>
          <span class="inq-qlp-r">${won(c.rev)}<small>${c.items.length}품목</small></span>
        </button>`;
    const draw = () => {
        const t = q.value.trim().toLowerCase();
        const hit = c => !t || [c.client, c.contact, c.date, ...c.items.map(p => p.item)].some(v => String(v || '').toLowerCase().includes(t));
        const same = cands.filter(c => c.same && hit(c));
        const other = cands.filter(c => !c.same && hit(c)).slice(0, t ? 60 : 20);
        listEl.innerHTML =
            (same.length ? `<div class="inq-qlp-sec">같은 거래처</div>${same.map(row).join('')}` : '') +
            (other.length ? `<div class="inq-qlp-sec">${t ? '찾은 견적' : '다른 거래처 · 최근 견적'}</div>${other.map(row).join('')}` : '') +
            (!same.length && !other.length ? '<div class="inq-qlp-empty">찾는 견적이 없어요</div>' : '');
    };
    draw();
    const close = () => { ov.remove(); document.removeEventListener('keydown', onKey, true); };
    const onKey = e => { if (e.key === 'Escape') { e.stopPropagation(); close(); } };
    document.addEventListener('keydown', onKey, true);
    q.addEventListener('input', draw);
    setTimeout(() => q.focus(), 0);
    ov.addEventListener('click', async e => {
        if (e.target === ov || e.target.closest('[data-qlp="close"]')) { close(); return; }
        const b = e.target.closest('.inq-qlp-row');
        if (!b) return;
        const c = cands.find(v => v.key === b.dataset.key);
        if (!c) return;
        if (!c.same && !confirm(`견적 거래처(${c.client || '없음'})가 이 상담(${x.client || '없음'})과 달라요.\n그래도 이 견적을 연결할까요?`)) return;
        close();
        await inqLinkGroup(x.id, c.date, c.client);
    });
}

async function inqLinkGroup(id, date, client) {
    const x = inqFind(id);
    if (!x) return;
    const cl = client === undefined ? x.client : client;
    const rows = tempProjects.filter(p => !p.inquiryId && (p.client || '') === (cl || '') && (p.date || '') === (date || ''));
    if (!rows.length) return;
    const { error } = await sb.from('projects_temp').update({ inquiry_id: id }).in('id', rows.map(p => p.id));
    if (error) { showToast('연결 실패: ' + error.message); return; }
    rows.forEach(p => { p.inquiryId = id; });
    const sum = rows.reduce((s, p) => s + calcTempRevenueWithVat(p), 0);
    await inqAddLog(id, { direction: 'system', body: `견적 연결 · ${String(date).replace(/-/g, '.')} 견적 ${rows.length}품목 (${sum.toLocaleString()}원)` });
    if (rows.every(p => p.transferredAt) && x.status !== '수주') {
        await inqPatch(id, { status: '수주' }, `상태 변경 · ${x.status} → 수주`);
    } else if (['신규', '상담중'].includes(x.status)) {
        await inqPatch(id, { status: '견적발송' }, `상태 변경 · ${x.status} → 견적발송`);
    }
    renderTempProjects();
    inqRenderDetail();
    showToast('견적을 연결했습니다');
}

function inqStartQuote(id) {
    const x = inqFind(id);
    if (!x) return;
    tpSetView('quote');
    _inqPendingLink = id;                 // tpSetView('quote') 이후에 지정 (inq 전환 시 해제되므로)
    const set = (elId, v) => { const e = document.getElementById(elId); if (e) e.value = v; };
    set('tempInDate', getTodayStr());
    set('tempInClient', x.client || '');
    set('tempInClientContact', x.contact_name || x.client_contact || '');
    const it0 = (x.items || []).find(i => i && i.name);
    if (it0) { set('tempInItem', it0.name); set('tempInQty', it0.qty && !it0.tbd ? Number(it0.qty).toLocaleString() : ''); }
    inqRenderLinkBanner();
    const it = document.getElementById('tempInItem');
    if (it) it.focus();
}

function inqRenderLinkBanner() {
    const el = document.getElementById('inqLinkBanner');
    if (!el) return;
    const x = _inqPendingLink ? inqFind(_inqPendingLink) : null;
    if (!x) { el.style.display = 'none'; el.innerHTML = ''; return; }
    el.style.display = '';
    el.innerHTML = `
      <svg width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" viewBox="0 0 24 24"><path d="M10 14a4 4 0 0 0 5.66 0l3-3a4 4 0 0 0-5.66-5.66l-1 1M14 10a4 4 0 0 0-5.66 0l-3 3a4 4 0 0 0 5.66 5.66l1-1"/></svg>
      <span><b>${escHtml(x.client || '상담')}</b> 상담에 연결해서 작성 중 — 아래 첫 줄에서 추가하는 품목은 상담 기록에 자동으로 남습니다</span>
      <div class="inq-spacer"></div>
      <button class="inq-mini" id="inqBannerBack">상담으로 돌아가기</button>
      <button class="inq-mini" id="inqBannerOff">연결 해제</button>`;
    document.getElementById('inqBannerBack').addEventListener('click', () => { _inqSel = x.id; tpSetView('inq'); });
    document.getElementById('inqBannerOff').addEventListener('click', () => { _inqPendingLink = null; inqRenderLinkBanner(); });
}

// 견적 목록에서 '상담 보기'
function inqOpenFromQuote(id) {
    _inqSel = id;
    _inqFilter = 'all';
    tpSetView('inq');
}

// 견적 품목이 추가될 때 (projects_temp insert 직후)
async function inqOnQuoteAdded(id, row) {
    if (!id) return;
    const amt = (row.revenue || 0).toLocaleString();
    await inqAddLog(id, { direction: 'system', body: `견적 품목 추가 · ${row.item || '품목'} ${Number(row.qty || 0).toLocaleString()}개 (${amt}원)` });
    let x = inqFind(id);
    if (!x) {
        const { data } = await sb.from('inquiries').select('*').eq('id', id).maybeSingle();
        x = data;
    }
    const patch = { last_contact_at: new Date().toISOString() };
    const bump = x && ['신규', '상담중'].includes(x.status);
    if (bump) patch.status = '견적발송';
    await inqPatch(id, patch, bump ? `상태 변경 · ${x.status} → 견적발송` : null);
}

// 견적 묶음이 매입매출로 넘어갈 때
async function inqOnTransferred(id, count) {
    if (!id) return;
    await inqAddLog(id, { direction: 'system', body: `국내 프로젝트로 등록 · ${count}건` });
    // 상태 '수주'로 바꾸기·기록은 DB 트리거(inq_sync_stage)가 이미 함 → 새로 읽기만
    const fresh = await inqReloadInquiry(id);
    const x = inqFind(id);
    if (x && _inqSel === id && document.getElementById('inqStage')) {
        if (fresh) Object.assign(x, fresh);
        await inqLoadDeal(x);
        await inqLoadLogs(id);
    }
}

// ---------- 새 상담 ----------
// F2 — 새 상담. 이미 새 상담 작성 중이면 내용 지우지 않고 거래처 칸으로만 이동
function inqShortcutNew() {
    const iv = document.getElementById('tpInqView');
    if (iv && iv.style.display !== 'none') {
        if (_inqSel === 'new' && document.getElementById('inqNClient')) { document.getElementById('inqNClient').focus(); return; }
        inqOpenNew();
        return;
    }
    _inqSel = 'new';      // inqEnter가 'new'를 유지해서 새 상담 칸을 그린다
    tpSetView('inq');
}

function inqOpenNew() {
    _inqSel = 'new';
    inqRenderList();
    inqRenderNewForm();
}

function inqRenderNewForm() {
    const el = document.getElementById('inqDetail');
    if (!el) return;
    const people = inqPeople();
    const me = currentUser && currentUser.name;
    _inqNewImages.length = 0;
    el.innerHTML = `
      <div class="inq-new inq-new2">
        <div class="inq-new-main">
          <h3>새 상담 등록</h3>
          <div class="inq-new-sec first">메일·카톡 붙여넣기 <em>붙여넣으면 AI가 읽고 아래 칸을 채워요 · 전화 상담이면 건너뛰고 오른쪽 순서대로 물어보세요</em></div>
          <div class="inq-new-full">
            <textarea id="inqNBody" rows="5" placeholder="고객이 보낸 내용을 그대로 붙여넣으세요.&#10;사진도 Ctrl+V로 붙여넣거나 여기로 끌어다 놓을 수 있습니다."></textarea>
            <div class="inq-auto-hint" id="inqNAutoHint"></div>
            <div class="inq-img-notice" id="inqNImgNotice" hidden></div>
            <div class="inq-thumbs" id="inqNThumbs"></div>
          </div>
          <div class="inq-new-sec">기본</div>
          <div class="inq-new-grid">
            <label class="span2"><span>거래처 *</span><input id="inqNClient" list="tempClientList" placeholder="거래처 DB에서 고르거나 직접 입력" autocomplete="off"></label>
            <label><span>문의 경로</span><select id="inqNChannel">${inqOpt(INQ_CHANNELS, '전화')}</select></label>
            <label><span>우리 담당</span><select id="inqNAssignee"><option value="">-</option>${inqOpt(people, people.includes(me) ? me : '')}</select></label>
            <label class="span3"><span>무엇을 문의했나요? <em>비워두면 품목·수량으로 자동</em></span><input id="inqNTitle" placeholder="예) 손목시계 300개 각인 견적"></label>
            <label><span>거래처 등급</span><select id="inqNGrade">${clientGradeOptions('')}</select></label>
          </div>
          <div class="inq-new-sec">고객 담당자</div>
          <div class="inq-new-grid c5">
            <label><span>담당자 이름</span><input id="inqNCName" placeholder="홍길동"></label>
            <label><span>직함</span><input id="inqNCTitle" placeholder="예) 과장"></label>
            <label><span>부서</span><input id="inqNCDept" placeholder="예) 총무팀"></label>
            <label><span>연락처</span><input id="inqNCPhone" inputmode="tel" placeholder="010-0000-0000"></label>
            <label><span>이메일</span><input id="inqNCEmail" type="email" placeholder="name@company.com"></label>
          </div>
          <div class="inq-new-sec">고객 회사 정보 <em>거래처 DB에 없던 회사면 주소·팩스도 같이 등록돼요</em></div>
          <div class="inq-new-grid">
            <label class="span2"><span>회사 주소</span><input id="inqNAddr" placeholder="예) 서울시 강서구 까치산로 23"></label>
            <label><span>팩스</span><input id="inqNFax" inputmode="tel" placeholder="02-0000-0000"></label>
            <label><span>홈페이지</span><input id="inqNWeb" placeholder="예) www.company.co.kr"></label>
          </div>
          <div class="inq-new-sec">요청 사항</div>
          <div class="inq-req-lab">품목 · 수량</div>
          <div class="inq-it-list" id="inqNItems">${inqItemRowHtml({})}</div>
          <button type="button" class="inq-todo-link" id="inqNItemAdd">+ 품목 추가</button>
          <div class="inq-new-grid" style="margin-top:12px">
            <label><span>희망 납기</span><input type="date" id="inqNDue"></label>
            <label><span>예산 · 희망 단가</span><input id="inqNBudget" placeholder="예) 개당 1만원 내외"></label>
            <label><span>용도 · 행사</span><input id="inqNPurpose" placeholder="예) 창립 20주년 기념품"></label>
            <label><span>샘플</span><select id="inqNSample">${inqOpt(['', '필요', '불필요'], '')}</select></label>
            <label class="span2"><span>인쇄 · 각인</span><input id="inqNPrint" placeholder="예) 문자판 로고 인쇄, 뒷면 이름 각인"></label>
            <label class="span2"><span>포장</span><input id="inqNPack" placeholder="예) 고급 케이스 + 쇼핑백"></label>
            <label class="span4"><span>배송지</span><input id="inqNDelivery" placeholder="회사 주소와 다르면 적어주세요"></label>
          </div>
          <div class="inq-new-actions">
            <button type="button" class="btn-ghost" id="inqNCancel">취소</button>
            <button type="button" class="btn-primary" id="inqNSave">등록</button>
          </div>
        </div>
        <aside class="inq-check" id="inqNCheck"></aside>
      </div>`;
    const $ = id => document.getElementById(id);
    $('inqNCancel').addEventListener('click', () => {
        _inqSel = null;
        const first = inqFiltered()[0];
        if (first) _inqSel = first.id;
        inqRenderList(); inqRenderDetail();
    });
    $('inqNSave').addEventListener('click', inqCreate);

    // 자동 입력된 칸을 사람이 고치면 그 칸은 더 이상 자동으로 덮어쓰지 않는다
    ['inqNClient', 'inqNTitle', 'inqNCName', 'inqNCDept', 'inqNCTitle', 'inqNCPhone', 'inqNCEmail', 'inqNAddr', 'inqNFax', 'inqNWeb',
     'inqNDue', 'inqNBudget', 'inqNPurpose', 'inqNSample', 'inqNPrint', 'inqNPack', 'inqNDelivery'].forEach(id => {
        $(id).addEventListener('input', () => { delete $(id).dataset.auto; $(id).classList.remove('inq-autofilled'); });
    });
    ['inqNCPhone', 'inqNFax'].forEach(id => $(id).addEventListener('change', () => { $(id).value = inqNormPhone($(id).value); }));
    $('inqNClient').addEventListener('change', () => inqFillFromClientDb($('inqNClient').value));

    // 품목 줄
    const items = $('inqNItems');
    inqBindItemRows(items, inqRenderNewCheck);
    $('inqNItemAdd').addEventListener('click', () => {
        items.insertAdjacentHTML('beforeend', inqItemRowHtml({}));
        inqBindItemRows(items, inqRenderNewCheck);
        items.lastElementChild.querySelector('input').focus();
    });

    // 체크리스트는 칸이 바뀔 때마다 다시
    let tc = null;
    const main = el.querySelector('.inq-new-main');
    main.addEventListener('input', () => { clearTimeout(tc); tc = setTimeout(inqRenderNewCheck, 150); });
    main.addEventListener('change', () => { clearTimeout(tc); tc = setTimeout(inqRenderNewCheck, 50); });
    inqRenderNewCheck();

    // 규칙으로 바로 채우고(0.25초), 잠시 멈추면 AI가 한 번 더 읽어 보강(0.9초)
    let t = null, ta = null;
    _inqAiLast = '';
    const body = $('inqNBody');
    body.addEventListener('input', () => {
        clearTimeout(t); t = setTimeout(inqAutofillNew, 250);
        clearTimeout(ta); ta = setTimeout(inqAiExtract, 900);
    });
    inqBindImageInput(body, _inqNewImages, () => inqThumbs(_inqNewImages, 'inqNThumbs'), 'inqNImgNotice');
    $('inqNClient').focus();
}

async function inqCreate() {
    const v = id => (document.getElementById(id).value || '').trim();
    const client = v('inqNClient');
    if (!client) { showToast('거래처를 입력해주세요'); document.getElementById('inqNClient').focus(); return; }
    const channel = v('inqNChannel');
    const body = v('inqNBody');
    const btn = document.getElementById('inqNSave');
    const items = inqReadItems(document.getElementById('inqNItems'));
    const title = v('inqNTitle') || (items.length ? inqItemsSummary(items) + ' 문의' : '');
    btn.disabled = true;
    const { data, error } = await sb.from('inquiries').insert({
        client, channel, assignee: v('inqNAssignee'), title, grade: v('inqNGrade'),
        contact_name: v('inqNCName'), contact_dept: v('inqNCDept'), contact_title: v('inqNCTitle'),
        contact_phone: inqNormPhone(v('inqNCPhone')), contact_email: v('inqNCEmail'),
        company_address: v('inqNAddr'), company_fax: inqNormPhone(v('inqNFax')), company_website: v('inqNWeb'),
        items, due_date: v('inqNDue') || null, budget: v('inqNBudget'), purpose: v('inqNPurpose'),
        print_request: v('inqNPrint'), packaging_request: v('inqNPack'), sample_needed: v('inqNSample'), delivery_address: v('inqNDelivery'),
        status: '신규', started_at: getTodayStr(),
        last_contact_at: new Date().toISOString(),
        created_by: (currentUser && currentUser.name) || ''
    }).select().single();
    if (error) { btn.disabled = false; showToast('등록 실패: ' + error.message); return; }
    clientAutoAddNotice([client]);

    const author = (currentUser && currentUser.name) || '';
    // 한 번에 넣는 행들은 칸 구성이 같아야 한다 (images는 NOT NULL이라 빠지면 전체 거부됨)
    const logs = [{ inquiry_id: data.id, direction: 'system', channel: '', body: `상담 시작 · ${inqJosaRo(channel)} 문의`, images: [], author: '' }];
    if (body || _inqNewImages.length) logs.push({ inquiry_id: data.id, direction: 'in', channel, body, images: _inqNewImages.slice(), author });
    const { error: lErr } = await sb.from('inquiry_logs').insert(logs);
    if (lErr) showToast('첫 문의 내용 저장 실패: ' + lErr.message);
    _inqNewImages.length = 0;

    _inqList.unshift(data);
    _inqSel = data.id;
    if (_inqFilter !== 'all' && _inqFilter !== 'active' && _inqFilter !== '신규') _inqFilter = 'active';
    inqRenderChips(); inqRenderList(); inqUpdateSwitchCount();
    await inqRenderDetail();
    showToast('상담을 등록했습니다');
}
// ---------- 사진: 붙여넣기 · 끌어놓기 · 파일 선택 ----------
const INQ_MAX_IMAGES = 10;

async function inqAddImageFiles(files, arr, onDone) {
    const list = Array.from(files || []).filter(f => f && f.type && f.type.startsWith('image/'));
    if (!list.length) return false;
    for (const f of list) {
        if (arr.length >= INQ_MAX_IMAGES) { showToast(`사진은 한 번에 ${INQ_MAX_IMAGES}장까지 넣을 수 있습니다`); break; }
        try {
            const raw = await inqBlobToDataUrl(f);
            arr.push(await _shrinkDataUrl(raw, 1200, 0.8));   // 업로드 전 자동 압축
        } catch (e) { showToast('사진 처리 실패: ' + e.message); }
    }
    if (onDone) onDone();
    return true;
}

function inqBlobToDataUrl(blob) {
    return new Promise((res, rej) => {
        const r = new FileReader();
        r.onload = e => res(e.target.result);
        r.onerror = () => rej(new Error('파일을 읽지 못했습니다'));
        r.readAsDataURL(blob);
    });
}

// 복사한 메일 본문(HTML) 속 사진 주소 — 이모지·추적용 1px 그림은 뺀다
function inqHtmlImageSrcs(html) {
    if (!html || !/<img/i.test(html)) return [];
    const doc = new DOMParser().parseFromString(html, 'text/html');
    const seen = new Set();
    return Array.from(doc.images).filter(img => {
        const src = img.getAttribute('src') || '';
        if (!/^(data:image\/|https?:)/i.test(src) || seen.has(src)) return false;
        const w = parseInt(img.getAttribute('width'), 10), h = parseInt(img.getAttribute('height'), 10);
        if ((w && w <= 32) || (h && h <= 32)) return false;
        if (/emoji|emoticon|sticker|spacer|pixel|tracking/i.test(src + ' ' + (img.className || '') + ' ' + (img.alt || ''))) return false;
        seen.add(src);
        return true;
    }).map(img => img.getAttribute('src'));
}

// 주소로 사진 가져오기 — 메일 서비스 사진은 로그인 보안 때문에 대부분 막힌다(실패 개수 반환)
async function inqAddImageUrls(urls, arr, onDone) {
    let ok = 0, fail = 0;
    for (const src of urls) {
        if (arr.length >= INQ_MAX_IMAGES) break;
        try {
            let dataUrl = src;
            if (!/^data:image\//i.test(src)) {
                const ctl = new AbortController();
                const tm = setTimeout(() => ctl.abort(), 8000);
                const r = await fetch(src, { mode: 'cors', credentials: 'omit', signal: ctl.signal });
                clearTimeout(tm);
                if (!r.ok) throw new Error('HTTP ' + r.status);
                const b = await r.blob();
                if (!b.type.startsWith('image/')) throw new Error('사진이 아님');
                dataUrl = await inqBlobToDataUrl(b);
            }
            arr.push(await _shrinkDataUrl(dataUrl, 1200, 0.8));
            ok++;
        } catch (_) { fail++; }
    }
    if (ok && onDone) onDone();
    return { ok, fail };
}

function inqImgNotice(id, n) {
    const el = document.getElementById(id);
    if (!el) return;
    if (!n) { el.hidden = true; el.innerHTML = ''; return; }
    el.hidden = false;
    el.innerHTML = `<b>메일 속 사진 ${n}장은 메일 보안 때문에 자동으로 못 가져왔어요.</b>
        <span>메일에서 사진에 마우스 오른쪽 → <b>이미지 복사</b> → 여기서 <b>Ctrl+V</b> 하거나, 사진을 이 칸으로 끌어다 놓으세요.</span>
        <button type="button" title="닫기">×</button>`;
    el.querySelector('button').addEventListener('click', () => inqImgNotice(id, 0));
}

// ---------- 붙여넣은 글 정리 ----------
// 메일·웹페이지에서 복사한 HTML → 화면에 보이던 줄바꿈 그대로의 글
function inqHtmlToText(html) {
    const doc = new DOMParser().parseFromString(String(html || ''), 'text/html');
    doc.querySelectorAll('script,style,head,title,meta,link,noscript').forEach(n => n.remove());
    const BLOCK = /^(P|DIV|H[1-6]|UL|OL|LI|TABLE|THEAD|TBODY|TFOOT|TR|BLOCKQUOTE|PRE|SECTION|ARTICLE|HEADER|FOOTER|ADDRESS|DL|DT|DD|HR|FIGURE|FIGCAPTION|CENTER|FORM|FIELDSET|MAIN|NAV|ASIDE)$/;
    let out = '';
    const nl = () => { out = out.replace(/[ \t]+$/, ''); if (out && !out.endsWith('\n')) out += '\n'; };
    const walk = (n) => {
        if (n.nodeType === 3) {
            let s = n.nodeValue.replace(/[\r\n\t]+/g, ' ').replace(/[ ]{2,}/g, ' ');
            const blank = !s.replace(/ /g, '').trim();
            s = s.replace(/ /g, ' ');
            if (blank) { if (out && !/\s$/.test(out)) out += ' '; return; }
            if (!out || out.endsWith('\n')) s = s.replace(/^ +/, '');
            out += s;
            return;
        }
        if (n.nodeType !== 1) return;
        const tag = n.tagName;
        if (tag === 'BR') { out = out.replace(/[ \t]+$/, '') + '\n'; return; }
        if (tag === 'IMG') return;
        if (tag === 'TD' || tag === 'TH') {
            if (out && !out.endsWith('\n') && !out.endsWith('\t')) out = out.replace(/ +$/, '') + '\t';
            n.childNodes.forEach(walk);
            return;
        }
        const block = BLOCK.test(tag);
        if (block) nl();
        const start = out.length;
        if (tag === 'LI') out += '• ';
        n.childNodes.forEach(walk);
        if (block) {
            // 내용 없이 &nbsp; 만 든 문단(<p>&nbsp;</p>)은 빈 줄 한 줄
            if (!out.slice(start).trim() && / /.test(n.textContent || '')) out += '\n';
            nl();
        }
    };
    walk(doc.body || doc.documentElement);
    return inqTidyText(out);
}

function inqTidyText(s) {
    return String(s || '').replace(/\r\n?/g, '\n')
        .split('\n').map(l => l.replace(/[ \t ]+$/, '')).join('\n')
        .replace(/\n{3,}/g, '\n\n')
        .replace(/^\n+|\n+$/g, '');
}

// 글만 복사된 경우 — 모든 줄 사이에 빈 줄이 끼어 있으면(문단마다 두 줄) 한 줄로 줄인다
function inqTidyPlain(s) {
    let t = String(s || '').replace(/\r\n?/g, '\n');
    const doubles = (t.match(/\n\n/g) || []).length;
    const singles = (t.replace(/\n{2,}/g, '').match(/\n/g) || []).length;
    if (doubles >= 3 && singles === 0) t = t.replace(/\n\n/g, '\n');
    return inqTidyText(t);
}

// 커서 위치에 글 넣기 (되돌리기 Ctrl+Z 가 되도록 execCommand 먼저)
function inqInsertText(el, text) {
    el.focus();
    let done = false;
    try { done = document.execCommand('insertText', false, text); } catch (_) { done = false; }
    if (!done) {
        const s = el.selectionStart, e = el.selectionEnd;
        el.setRangeText(text, s, e, 'end');
        el.dispatchEvent(new Event('input', { bubbles: true }));
    }
}

// 글 입력칸: 붙여넣기(글 정리 + 사진) · 끌어놓기
function inqBindImageInput(el, arr, onDone, noticeId) {
    if (!el) return;
    const afterUrls = (r) => { inqImgNotice(noticeId, r.fail); };
    el.addEventListener('paste', (e) => {
        const cd = e.clipboardData;
        if (!cd) return;
        const files = [];
        for (const it of (cd.items || [])) {
            if (it.kind === 'file' && it.type && it.type.startsWith('image/')) {
                const f = it.getAsFile();
                if (f) files.push(f);
            }
        }
        const html = cd.getData('text/html') || '';
        const plain = cd.getData('text/plain') || '';
        let text = '';
        if (html && /<(p|div|br|tr|td|li|table|span|font|b|strong|a|img)\b/i.test(html)) text = inqHtmlToText(html);
        if (!text && plain) text = inqTidyPlain(plain);
        if (text) { e.preventDefault(); inqInsertText(el, text); }

        if (files.length) { inqImgNotice(noticeId, 0); inqAddImageFiles(files, arr, onDone); }
        else {
            const srcs = inqHtmlImageSrcs(html);
            if (srcs.length) inqAddImageUrls(srcs, arr, onDone).then(afterUrls);
        }
    });
    el.addEventListener('dragover', (e) => {
        const types = Array.from((e.dataTransfer && e.dataTransfer.types) || []);
        if (types.includes('Files')) { e.preventDefault(); el.classList.add('inq-drop'); }
    });
    el.addEventListener('dragleave', () => el.classList.remove('inq-drop'));
    el.addEventListener('drop', (e) => {
        el.classList.remove('inq-drop');
        const dt = e.dataTransfer;
        if (!dt) return;
        if (dt.files && dt.files.length) { e.preventDefault(); inqImgNotice(noticeId, 0); inqAddImageFiles(dt.files, arr, onDone); return; }
        // 다른 창의 사진을 끌어온 경우 — 주소로 시도
        const srcs = inqHtmlImageSrcs(dt.getData('text/html') || '');
        if (srcs.length) { e.preventDefault(); inqAddImageUrls(srcs, arr, onDone).then(afterUrls); }
    });
}

function inqThumbs(arr, boxId) {
    const box = document.getElementById(boxId);
    if (!box) return;
    box.innerHTML = arr.map((src, i) =>
        `<div class="inq-c-img"><img src="${escHtml(src)}" alt="첨부 ${i + 1}"><button type="button" data-rm="${i}" title="빼기">×</button></div>`).join('');
    box.querySelectorAll('[data-rm]').forEach(b => b.addEventListener('click', () => {
        arr.splice(Number(b.dataset.rm), 1);
        inqThumbs(arr, boxId);
    }));
}

// ---------- 붙여넣은 문의에서 연락처 뽑기 ----------
function inqNormPhone(v) {
    const s = String(v || '').trim();
    const d = s.replace(/[^0-9]/g, '');
    if (/^01[016789]\d{7,8}$/.test(d)) return d.length === 11 ? `${d.slice(0, 3)}-${d.slice(3, 7)}-${d.slice(7)}` : `${d.slice(0, 3)}-${d.slice(3, 6)}-${d.slice(6)}`;
    if (/^02\d{7,8}$/.test(d)) return d.length === 10 ? `02-${d.slice(2, 6)}-${d.slice(6)}` : `02-${d.slice(2, 5)}-${d.slice(5)}`;
    if (/^0[3-9]\d\d{7,8}$/.test(d)) return d.length === 11 ? `${d.slice(0, 3)}-${d.slice(3, 7)}-${d.slice(7)}` : `${d.slice(0, 3)}-${d.slice(3, 6)}-${d.slice(6)}`;
    if (/^1[5-9]\d{6}$/.test(d)) return `${d.slice(0, 4)}-${d.slice(4)}`;   // 1588-0000
    return s;
}

const INQ_LABELS = {
    company: ['회사명', '회사', '업체명', '업체', '상호명', '상호', '기업명', '기업', '기관명', '기관', '단체명', '소속', 'company name', 'company'],
    name: ['담당자 성함', '담당자명', '담당자', '성함', '성명', '이름', '고객명', '신청자', '문의자', '작성자', 'name'],
    dept: ['부서명', '부서', '팀명', '소속 부서', '소속부서', 'department', 'dept'],
    title: ['직함', '직책', '직급', 'position', 'job title'],
    phone: ['휴대폰 번호', '휴대폰번호', '휴대폰', '휴대전화', '핸드폰', '연락처', '전화번호', '전화', 'phone', 'mobile', 'tel'],
    email: ['이메일 주소', '이메일', 'e-mail', 'email', '메일 주소', '메일주소', '메일'],
    subject: ['문의 제목', '문의제목', '제목', '문의 유형', '문의유형', '문의 종류', 'subject']
};
// 긴 것부터 맞춰야 '선임매니저'가 '선임'+'매니저'로 쪼개지지 않는다
const INQ_TITLE_LIST = ['대표이사', '대표님', '대표', '부사장', '사장', '전무', '상무', '이사', '본부장', '부장', '차장', '과장', '대리', '주임', '사원',
    '팀장', '실장', '파트장', '그룹장', '센터장', '국장', '원장', '소장', '매니저', '매니져', '선임매니저', '책임매니저', '수석매니저',
    '선임연구원', '책임연구원', '수석연구원', '주임연구원', '연구원', '선임', '책임', '수석', '프로', '디자이너', '컨설턴트',
    '교수', '선생님', '사무장', '총무', '계장', '주무관', '팀원'].sort((a, b) => b.length - a.length);
const INQ_JOB_TITLES = INQ_TITLE_LIST.join('|');
const INQ_NOT_NAMES = ['저희', '우리', '담당', '담당자', '해당', '저는', '제가', '귀사', '회사', '안녕', '문의', '관련', '이번', '다음',
    '감사', '감사해요', '말씀', '연락', '안내', '예정', '수고', '드림', '올림', '참조', '회신', '전체', '원활', '업무', '가능', '여부', '최소', '단가', '제작', '기간', '고객', '대표님'];
const INQ_FREE_MAIL = /^(gmail|googlemail|naver|daum|hanmail|kakao|nate|hotmail|outlook|live|msn|yahoo|icloud|me|korea|empal|dreamwiz|lycos|paran|hanmir|chol|freechal|hanafos|unitel|netian)$/i;
const INQ_DEPT_RE = /^[가-힣A-Za-z0-9&·\s]{1,20}(?:팀|부|실|본부|센터|그룹|파트|사업부|사업본부|과|국|처|연구소|연구실|사무국)$/;

function inqIsTitle(w) { return INQ_TITLE_LIST.includes(w); }
function inqNameOk(w) {
    return !!w && /^[가-힣]{2,4}$/.test(w) && !inqIsTitle(w) && !INQ_NOT_NAMES.includes(w)
        && !INQ_TITLE_LIST.some(tt => tt.length >= 2 && w.endsWith(tt) && w.length - tt.length < 2);
}

function inqParseContact(text) {
    const t = String(text || '');
    const out = {};
    const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const lines = t.split(/\r?\n/).map(l => l.trim());
    // 1) '이름 : 홍길동' 형태 (콜론·탭 구분자가 있어야 인정 — '연락처 알려주세요' 같은 문장은 무시)
    const segs = [];
    lines.forEach(line => line.split(/\s[|/]\s/).forEach(s => segs.push(s)));
    Object.keys(INQ_LABELS).forEach(k => {
        const labs = INQ_LABELS[k].slice().sort((a, b) => b.length - a.length).map(esc).join('|');
        const re = new RegExp('^[\\s\\[\\(<*•·#\\-]*(?:' + labs + ')\\s*[\\]\\)>]*\\s*(?:[:：]|\\t)\\s*(.+?)\\s*$', 'i');
        for (const s of segs) {
            const m = s.match(re);
            if (m && m[1]) { out[k] = m[1].trim(); break; }
        }
    });

    // 값 다듬기
    if (out.email) { const m = out.email.match(/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/); out.email = m ? m[0] : ''; }
    if (out.phone) { const m = out.phone.match(/0\d{1,2}[\s.\-)]*\d{3,4}[\s.\-]*\d{4}|1[5-9]\d{2}[\s.\-]*\d{4}/); out.phone = m ? inqNormPhone(m[0]) : ''; }
    if (out.name) {
        const nm = out.name.replace(/님$/, '').trim();
        const m = nm.match(new RegExp('^([가-힣A-Za-z]{2,10})\\s*(' + INQ_JOB_TITLES + ')$'));
        if (m && !inqIsTitle(m[1])) { out.name = m[1]; if (!out.title) out.title = m[2]; }
        else out.name = nm.slice(0, 30);
    }
    ['company', 'subject', 'dept', 'title'].forEach(k => { if (out[k]) out[k] = out[k].slice(0, k === 'subject' ? 80 : 60); });
    Object.keys(out).forEach(k => { if (!out[k]) delete out[k]; });

    // 2) 서명 줄 — 'HR마케팅2팀 | 선임매니저', '김규리/HR마케팅2팀/NHR', '총무팀 과장'
    for (const line of lines) {
        if (!line || line.length > 60) continue;
        let parts = line.split(/\s*[|/·ㅣ]\s*/).filter(Boolean);
        if (parts.length === 1) {
            const m = line.match(new RegExp('^(.+?(?:팀|부|실|본부|센터|그룹|파트|과))\\s+(' + INQ_JOB_TITLES + ')$'));
            if (m) parts = [m[1], m[2]];
        }
        if (parts.length < 2 || parts.length > 4) continue;
        let dept = '', title = '', name = '', rest = [];
        parts.forEach(p => {
            if (!title && inqIsTitle(p)) title = p;
            else if (!dept && INQ_DEPT_RE.test(p)) dept = p;
            else if (!name && inqNameOk(p)) name = p;
            else rest.push(p);
        });
        if (!dept && !title) continue;
        if (dept && !out.dept) out.dept = dept;
        if (title && !out.title) out.title = title;
        if (name && !out.name) out.name = name;
        if (!out.company && rest.length === 1 && /^[A-Za-z0-9&.\-]{2,20}$|주식회사|㈜|\(주\)/.test(rest[0])) out.company = rest[0];
        if (out.dept && out.title) break;
    }

    // 3) 본문 어디서든 — 이메일 · 연락처(휴대폰 우선, 팩스 제외)
    if (!out.email) { const m = t.match(/[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/); if (m) out.email = m[0]; }
    if (!out.phone) {
        const mob = t.match(/01[016789][\s.\-]?\d{3,4}[\s.\-]?\d{4}/);
        if (mob) out.phone = inqNormPhone(mob[0]);
        else {
            const re = /0\d{1,2}[\s.\-)]\s?\d{3,4}[\s.\-]\d{4}/g;
            let m;
            while ((m = re.exec(t))) {
                const before = t.slice(Math.max(0, m.index - 8), m.index);
                if (/(?:^|[\s(])(?:F|FAX|Fax|fax|팩스)[\s.:)]*$/.test(before)) continue;
                out.phone = inqNormPhone(m[0]);
                break;
            }
        }
    }

    // 4) 이름 — 맺음말 'OOO 드림' → 자기소개 'NHR 김규리 선임입니다' → 연락처 바로 위 이름 한 줄 → '김규리 선임'
    if (!out.name) {
        const m = t.match(new RegExp('([가-힣]{2,4})\\s?(?:(' + INQ_JOB_TITLES + ')\\s?)?(?:드림|올림)\\s*$', 'm'));
        if (m && inqNameOk(m[1])) { out.name = m[1]; if (!out.title && m[2]) out.title = m[2]; }
    }
    {
        const intro = new RegExp('(?:^|[\\s,.])((?:주식회사|㈜|\\(주\\))\\s?[가-힣A-Za-z0-9&]+|[가-힣A-Za-z0-9&]+(?:주식회사|㈜|\\(주\\))|[A-Za-z][A-Za-z0-9&.\\-]{1,19}|[가-힣A-Za-z0-9&]+(?:상사|산업|전자|테크|기업|그룹|재단|협회|학교|대학교|병원|은행|공사|공단|시청|구청|군청|도청|컴퍼니|코리아))?\\s*([가-힣]{2,4})\\s?(' + INQ_JOB_TITLES + ')?\\s?(?:입니다|이에요|예요|이라고 합니다|라고 합니다)', 'm');
        const m = t.match(intro);
        if (m && (m[1] || m[3]) && inqNameOk(m[2])) {   // 회사나 직함이 같이 있어야 인정('예정입니다' 같은 오탐 방지)
            if (!out.name) out.name = m[2];
            if (!out.title && m[3]) out.title = m[3];
            if (!out.company && m[1]) out.company = m[1].trim();
        }
    }
    if (!out.name) {
        const m = t.match(/(?:저는|제 이름은)\s*([가-힣]{2,4})(?:입니다|이에요|예요|이라고)/);
        if (m && inqNameOk(m[1])) out.name = m[1];
    }
    if (!out.name) {
        const idx = lines.findIndex(l => /@|01[016789][\s.\-]?\d{3,4}/.test(l));
        for (let i = idx - 1; i >= 0 && i >= idx - 4; i--) {
            if (inqNameOk(lines[i])) { out.name = lines[i]; break; }
        }
    }
    if (!out.name) {
        const re = new RegExp('([가-힣]{2,4})\\s?(' + INQ_JOB_TITLES + ')(?=님|입니다|이에요|예요|$|[\\s,.)!])', 'm');
        const m = t.match(re);
        if (m && inqNameOk(m[1])) { out.name = m[1]; if (!out.title) out.title = m[2]; }
    }

    // 5) 회사 — '주식회사 한빛' / '한빛 주식회사' → 없으면 회사 메일 주소(nhr.kr → NHR)
    if (!out.company) {
        const m = t.match(/(?:주식회사|\(주\)|㈜)[ \t]?[가-힣A-Za-z0-9&]+/) || t.match(/[가-힣A-Za-z0-9&]+[ \t]?(?:주식회사|\(주\)|㈜)/);
        if (m) out.company = m[0].trim();
    }
    if (!out.company && out.email) {
        const dom = out.email.split('@')[1].split('.')[0];
        if (dom && !INQ_FREE_MAIL.test(dom) && dom.length <= 5) out.company = dom.toUpperCase();
    }
    return out;
}

// 거래처 DB에 같은 이름이 있으면 DB 표기로 ('nhr' → 'NHR', '한빛테크' → '(주)한빛테크')
function inqMatchClient(name) {
    const norm = s => String(s || '').replace(/주식회사|\(주\)|㈜|\(유\)|유한회사|\s/g, '').toLowerCase();
    const n = norm(name);
    if (!n) return name;
    const opts = Array.from(document.querySelectorAll('#tempClientList option')).map(o => o.value);
    const hit = opts.find(v => norm(v) === n);
    return hit || name;
}

// 새 상담 — 붙여넣은 문의 내용에서 위 칸 채우기 (비었거나 이전에 자동으로 채운 칸만)
const INQ_AUTO_MAP = [
    ['company', 'inqNClient', '거래처'], ['subject', 'inqNTitle', '문의 내용'],
    ['name', 'inqNCName', '담당자'], ['title', 'inqNCTitle', '직함'], ['dept', 'inqNCDept', '부서'],
    ['phone', 'inqNCPhone', '연락처'], ['email', 'inqNCEmail', '이메일'],
    ['company_address', 'inqNAddr', '회사 주소'], ['company_fax', 'inqNFax', '팩스'], ['company_website', 'inqNWeb', '홈페이지'],
    ['due_date', 'inqNDue', '희망 납기'], ['budget', 'inqNBudget', '예산'], ['purpose', 'inqNPurpose', '용도'],
    ['print_request', 'inqNPrint', '인쇄·각인'], ['packaging_request', 'inqNPack', '포장'], ['sample_needed', 'inqNSample', '샘플'],
    ['delivery_address', 'inqNDelivery', '배송지']
];
const INQ_CHECK_SVG = '<svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.6" viewBox="0 0 24 24"><path d="M5 12l5 5L20 7"/></svg>';

function inqApplyAuto(p) {
    const filled = [];
    INQ_AUTO_MAP.forEach(([k, id, label]) => {
        const el = document.getElementById(id);
        let v = p[k];
        if (!el || !v) return;
        if (k === 'phone' || k === 'company_fax') v = inqNormPhone(v);
        if (k === 'company') v = inqMatchClient(v);
        if (el.value.trim() && el.dataset.auto !== '1') return;   // 사람이 쓴 칸은 건드리지 않음
        el.value = v;
        el.dataset.auto = '1';
        el.classList.add('inq-autofilled');
        filled.push(label);
    });
    inqRenderNewCheck();
    return filled;
}

function inqAutoHint(html) {
    const hint = document.getElementById('inqNAutoHint');
    if (hint) hint.innerHTML = html || '';
}

function inqAutofillNew() {
    const body = document.getElementById('inqNBody');
    if (!body) return;
    const filled = inqApplyAuto(Object.assign(inqParseContact(body.value), inqParseExtra(body.value)));
    if (filled.length) inqAutoHint(`${INQ_CHECK_SVG} 붙여넣은 내용에서 자동 입력 — <b>${filled.join(' · ')}</b> <span>틀리면 바로 고쳐주세요</span>`);
    else if (!body.value.trim()) inqAutoHint('');
}

// AI로 한 번 더 — 보낸 사람 정보 + '무엇을 문의했는지' 한 줄 (실패하면 위 규칙 결과만 남긴다)
let _inqAiSeq = 0;
let _inqAiLast = '';
async function inqAiExtract() {
    const body = document.getElementById('inqNBody');
    if (!body) return;
    const content = body.value.trim();
    if (content.length < 20 || content === _inqAiLast) return;
    _inqAiLast = content;
    const seq = ++_inqAiSeq;
    inqAutoHint('<span class="inq-ai-spin"></span> AI가 문의 내용을 읽는 중…');
    try {
        const { data: sess } = await sb.auth.getSession();
        const token = sess && sess.session && sess.session.access_token;
        if (!token) throw new Error('no session');
        const s = (currentCompany && currentCompany.settings) || {};
        const res = await fetch('/api/meeting-summarize?kind=inquiry', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
            body: JSON.stringify({ content, today: getTodayStr(), ourCompany: s.brandName || (currentCompany && currentCompany.name) || '' })
        });
        const d = await res.json().catch(() => ({}));
        if (seq !== _inqAiSeq || !document.getElementById('inqNBody')) return;   // 그사이 내용이 바뀜
        if (!res.ok) throw new Error(d.error || ('HTTP ' + res.status));
        const filled = inqApplyAuto({
            company: d.company, subject: d.inquiry_title, name: d.contact_name, dept: d.contact_dept,
            title: d.contact_title, phone: d.contact_phone, email: d.contact_email,
            company_address: d.company_address, company_fax: d.company_fax, company_website: d.company_website,
            due_date: d.due_date, budget: d.budget, purpose: d.purpose, print_request: d.print_request,
            packaging_request: d.packaging_request, sample_needed: d.sample_needed, delivery_address: d.delivery_address
        });
        if (inqApplyItems(d.items)) filled.push('품목·수량');
        inqRenderNewCheck();
        const got = INQ_AUTO_MAP.filter(([, id]) => { const el = document.getElementById(id); return el && el.dataset.auto === '1'; }).map(a => a[2]);
        const itBox = document.getElementById('inqNItems');
        if (itBox && itBox.dataset.auto === '1') got.push('품목·수량');
        inqAutoHint(got.length || filled.length
            ? `${INQ_CHECK_SVG} AI 자동 입력 — <b>${(got.length ? got : filled).join(' · ')}</b> <span>틀리면 바로 고쳐주세요</span>`
            : '');
    } catch (e) {
        if (seq !== _inqAiSeq) return;
        _inqAiLast = '';   // 다음에 다시 시도할 수 있게
        inqAutofillNew();  // 규칙으로 뽑은 결과 안내로 되돌림
    }
}

// ---------- 다음 할 일 — 여러 개 · 담당자 · 일일계획표 자동 등록 (migration 037) ----------
// 일일계획표(daily_tasks)와 연결된 할 일은 완료 여부를 daily_tasks.done에서 읽는다(단일 원본).
// inquiries.next_action / next_action_date 는 목록·정렬용 요약('가장 급한 미완료 할 일 외 N건')
let _inqTodos = [];

// 상담 담당자·할 일 담당자 목록 — 회의록과 같은 기준(KLP는 대표님 포함). companyPeople()은 실무자 4명뿐이라 대표님이 빠짐
function inqPeople() { return meetingStaffList(); }
function inqMe() { const n = (currentUser && currentUser.name) || ''; return DISPLAY_NAME_MAP[n] || n; }
function inqPeopleOpts(v) {
    const p = inqPeople().slice();
    if (v && !p.includes(v)) p.push(v);
    return inqOpt(p, v);
}
function inqTodoDailyText(x, task) { return x && x.client ? `[${x.client}] ${task}` : task; }
function inqTodoSort(a, b) {
    if (a.done !== b.done) return a.done ? 1 : -1;
    const ad = a.due_date || '9999', bd = b.due_date || '9999';
    return ad.localeCompare(bd) || (a.id - b.id);
}
function inqDailyLocal(id) {
    try { return (typeof dailyTasks !== 'undefined' && dailyTasks) ? dailyTasks.find(d => d.id === id) : null; } catch (_) { return null; }
}

function inqDailyRemoveLocal(id) {
    try { const i = dailyTasks.findIndex(d => d.id === id); if (i >= 0) dailyTasks.splice(i, 1); } catch (_) {}
}

async function inqLoadTodos(x) {
    const el = document.getElementById('inqTodos');
    const { data, error } = await sb.from('inquiry_todos').select('*').eq('inquiry_id', x.id).order('id');
    if (_inqSel !== x.id) return;
    if (error) { if (el) el.innerHTML = `<div class="inq-todo-err">할 일을 불러오지 못했습니다: ${escHtml(error.message)}</div>`; return; }
    _inqTodos = data || [];
    // 일일계획표에서 완료 체크한 것 반영
    const ids = _inqTodos.map(t => t.daily_task_id).filter(Boolean);
    if (ids.length) {
        const { data: d } = await sb.from('daily_tasks').select('id, done').in('id', ids);
        const m = new Map((d || []).map(r => [r.id, r]));
        _inqTodos.forEach(t => { const r = m.get(t.daily_task_id); if (r) t.done = !!r.done; });
    }
    if (_inqSel !== x.id) return;
    inqRenderTodos(x);
    inqSyncNextSummary(x);
}

function inqRenderTodos(x) {
    const el = document.getElementById('inqTodos');
    if (!el) return;
    const today = getTodayStr();
    const list = _inqTodos.slice().sort(inqTodoSort);
    const open = list.filter(t => !t.done).length;
    el.innerHTML = `
      <div class="inq-todo-head">
        <b>다음 할 일</b>${open ? `<span>${open}</span>` : ''}
        <em>추가하면 담당자 일일계획표에 자동으로 들어가요</em>
      </div>
      ${list.map(t => `
      <div class="inq-todo ${t.done ? 'done' : ''} ${!t.done && t.due_date && t.due_date <= today ? 'late' : ''}" data-tid="${t.id}">
        <input type="checkbox" data-k="done" ${t.done ? 'checked' : ''} title="완료">
        <input class="inq-todo-task" data-k="task" value="${escHtml(t.task)}">
        <input type="date" data-k="due_date" value="${escHtml(t.due_date || '')}" title="할 날짜">
        <select data-k="assignee" title="담당자">${inqPeopleOpts(t.assignee || '')}</select>
        ${t.daily_task_id
            ? '<span class="inq-todo-linked" title="담당자 일일계획표에 등록됨">계획표 ✓</span>'
            : '<button type="button" class="inq-todo-link" data-link title="담당자 일일계획표에 등록">+ 일일계획표</button>'}
        <button type="button" class="inq-todo-del" data-del title="삭제">×</button>
      </div>`).join('')}
      <div class="inq-todo add">
        <span class="inq-todo-plus">+</span>
        <input class="inq-todo-task" id="inqTNew" placeholder="할 일 추가 — 예) 샘플 사진 보내기 (Enter)">
        <input type="date" id="inqTNewDate" value="${today}" title="할 날짜">
        <select id="inqTNewWho" title="담당자">${inqPeopleOpts(inqMe())}</select>
        <button type="button" class="inq-mini primary" id="inqTNewAdd">추가</button>
      </div>`;

    el.querySelectorAll('[data-tid]').forEach(row => {
        const t = _inqTodos.find(v => v.id === Number(row.dataset.tid));
        if (!t) return;
        row.querySelectorAll('[data-k]').forEach(inp => inp.addEventListener('change', () => {
            const k = inp.dataset.k;
            if (k === 'done') { inqTodoToggle(x, t, inp.checked); return; }
            let v = inp.value.trim();
            if (k === 'task' && !v) { inp.value = t.task; return; }
            if (k === 'due_date') v = v || null;
            if ((t[k] || null) === (v || null)) return;
            inqTodoUpdate(x, t, { [k]: v });
        }));
        const task = row.querySelector('[data-k="task"]');
        task.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); task.blur(); } });
        const link = row.querySelector('[data-link]');
        if (link) link.addEventListener('click', () => inqTodoLinkDaily(x, t));
        row.querySelector('[data-del]').addEventListener('click', () => inqTodoDelete(x, t));
    });
    const add = () => inqTodoAdd(x);
    document.getElementById('inqTNewAdd').addEventListener('click', add);
    document.getElementById('inqTNew').addEventListener('keydown', e => {
        if (e.key === 'Enter' && !e.isComposing) { e.preventDefault(); add(); }
    });
}

// 담당자 일일계획표에 할 일 한 줄 만들기 → 저장된 daily_task id
async function inqTodoCreateDaily(x, task, due, who) {
    const saved = await dbInsertTask({
        task: inqTodoDailyText(x, task),
        date: due || getTodayStr(),
        assignee: who, target: '',
        label: '회사 업무',
        client: x.client || '',
        note: '상담: ' + (x.title || x.client || ''),
        priority: '🟡 보통',
        done: false
    });
    if (!saved || !saved.id) return null;
    try { dailyTasks.push(saved); } catch (_) {}
    tbxSyncViews();
    return saved.id;
}

async function inqTodoAdd(x) {
    const inp = document.getElementById('inqTNew');
    const task = (inp.value || '').trim();
    if (!task) { inp.focus(); return; }
    const due = document.getElementById('inqTNewDate').value || null;
    const who = document.getElementById('inqTNewWho').value || inqMe();
    const btn = document.getElementById('inqTNewAdd');
    btn.disabled = true;
    const dailyId = who ? await inqTodoCreateDaily(x, task, due, who) : null;
    const { data, error } = await sb.from('inquiry_todos').insert({
        inquiry_id: x.id, task, due_date: due, assignee: who, daily_task_id: dailyId, created_by: inqMe()
    }).select().single();
    btn.disabled = false;
    if (error) {
        showToast('할 일 저장 실패: ' + error.message);
        if (dailyId) { await dbDeleteTask(dailyId); inqDailyRemoveLocal(dailyId); tbxSyncViews(); }
        return;
    }
    _inqTodos.push(data);
    inqRenderTodos(x);
    document.getElementById('inqTNew').focus();
    showToast(dailyId ? `${who} 일일계획표(${inqMD(due || getTodayStr())})에 등록했습니다` : '할 일을 추가했습니다 (일일계획표 등록은 실패)');
    await inqAddLog(x.id, { direction: 'system', body: `할 일 추가 · ${task} (${who}${due ? ' · ' + inqMD(due) : ''})` });
    inqSyncNextSummary(x);
}

async function inqTodoUpdate(x, t, patch) {
    const { error } = await sb.from('inquiry_todos').update(patch).eq('id', t.id);
    if (error) { showToast('저장 실패: ' + error.message); inqRenderTodos(x); return false; }
    Object.assign(t, patch);
    if (t.daily_task_id) {
        const dp = {};
        if ('task' in patch) dp.task = inqTodoDailyText(x, patch.task);
        if ('due_date' in patch) dp.date = patch.due_date || getTodayStr();
        if ('assignee' in patch) dp.assignee = patch.assignee;
        if ('done' in patch) { dp.done = patch.done; dp.completedAt = patch.done ? new Date().toISOString() : null; }
        await dbUpdateTask(t.daily_task_id, dp);
        const g = inqDailyLocal(t.daily_task_id);
        if (g) Object.assign(g, dp);
        tbxSyncViews();
    }
    inqRenderTodos(x);
    inqSyncNextSummary(x);
    return true;
}

async function inqTodoToggle(x, t, done) {
    const ok = await inqTodoUpdate(x, t, { done, done_at: done ? new Date().toISOString() : null });
    if (ok && done) await inqAddLog(x.id, { direction: 'system', body: `할 일 완료 · ${t.task}${t.assignee ? ' (' + t.assignee + ')' : ''}` });
}

// 예전 '다음 할 일'에서 옮겨온 것처럼 일일계획표 연결이 없는 할 일 → 지금 등록
async function inqTodoLinkDaily(x, t) {
    const who = t.assignee || inqMe();
    const id = await inqTodoCreateDaily(x, t.task, t.due_date, who);
    if (!id) return;
    const { error } = await sb.from('inquiry_todos').update({ daily_task_id: id, assignee: who }).eq('id', t.id);
    if (error) { showToast('연결 실패: ' + error.message); return; }
    t.daily_task_id = id; t.assignee = who;
    inqRenderTodos(x);
    showToast(`${who} 일일계획표에 등록했습니다`);
}

async function inqTodoDelete(x, t) {
    if (!confirm(t.daily_task_id ? `'${t.task}' 할 일을 지울까요?\n${t.assignee || '담당자'} 일일계획표에서도 함께 지워집니다.` : `'${t.task}' 할 일을 지울까요?`)) return;
    if (t.daily_task_id) {
        await dbDeleteTask(t.daily_task_id);
        inqDailyRemoveLocal(t.daily_task_id);
        tbxSyncViews();
    }
    const { error } = await sb.from('inquiry_todos').delete().eq('id', t.id);
    if (error) { showToast('삭제 실패: ' + error.message); return; }
    _inqTodos = _inqTodos.filter(v => v.id !== t.id);
    inqRenderTodos(x);
    inqSyncNextSummary(x);
}

// 목록에 보이는 '다음 할 일' 요약 갱신
async function inqSyncNextSummary(x) {
    const open = _inqTodos.filter(t => !t.done).sort(inqTodoSort);
    const na = open.length ? open[0].task + (open.length > 1 ? ` 외 ${open.length - 1}건` : '') : '';
    const nd = open.length ? (open[0].due_date || null) : null;
    const cur = inqFind(x.id) || x;
    if ((cur.next_action || '') === na && (cur.next_action_date || null) === nd) return;
    const d = await inqPatch(x.id, { next_action: na, next_action_date: nd });
    if (d) Object.assign(x, d);
}

// ---------- 거래 흐름: 상담 → 견적 → 수주 → 디자인확인 → 작업요청 → 납품·정산 (migration 038) ----------
// 국내 프로젝트(projects_domestic.inquiry_id)를 상담에 연결해 한 화면에서 끝까지 진행.
// 체크 날짜(check_dates)·타임라인 자동 기록·상담 상태(수주→제작중→납품완료→정산완료)는 DB 트리거가 처리.
let _inqProjs = [];
let _inqProjsFor = null;
const INQ_SETTLE_KEYS = ['delivered', 'finalPayment', 'invoice', 'supplierPayment'];
// 단계 막대 뒤쪽 5칸: [단계 key, 표시 이름, 국내 체크 key]
const INQ_PAY_STAGES = [
    ['ap', '선금 입금', 'advancePayment'],
    ['fp', '잔금 입금', 'finalPayment'],
    ['inv', '계산서 발행', 'invoice'],
    ['sp', '공급처 송금', 'supplierPayment'],
    ['dlv', '납품', 'delivered']
];

async function inqLoadDeal(x) {
    const { data, error } = await sb.from('projects_domestic').select('*').eq('inquiry_id', x.id).order('id');
    if (_inqSel !== x.id) return;
    if (error) { console.error('연결된 국내 프로젝트 로드 실패', error); return; }
    _inqProjs = (data || []).filter(r => r.status !== '취소');
    _inqProjsFor = x.id;
    inqRenderProjs(x);
    inqRenderStage(x);
}

// 트리거가 바꾼 상담 상태·기록을 다시 읽어온다
async function inqReloadInquiry(id) {
    const { data } = await sb.from('inquiries').select('*').eq('id', id).maybeSingle();
    if (!data) return null;
    const i = _inqList.findIndex(v => v.id === id);
    if (i >= 0) _inqList[i] = data; else _inqList.unshift(data);
    inqRenderChips(); inqRenderList(); inqUpdateSwitchCount();
    const sel = document.getElementById('inqFStatus');
    if (sel && _inqSel === id) { sel.value = data.status; sel.className = 'inq-h-status ' + (INQ_STATUS_CLS[data.status] || ''); }
    return data;
}

function inqDateOf(ts) { return ts ? String(ts).slice(0, 10) : ''; }
function inqMaxDate(arr) { return arr.filter(Boolean).sort().slice(-1)[0] || ''; }
function inqMinDate(arr) { return arr.filter(Boolean).sort()[0] || ''; }

// 단계 계산 — done / cur / todo + 날짜·보조 문구
function inqStages(x) {
    const quotes = tempProjects.filter(p => p.inquiryId === x.id);
    const projs = _inqProjsFor === x.id ? _inqProjs : [];
    const n = projs.length;
    const cnt = k => projs.filter(p => p.checks && p.checks[k]).length;
    const kDate = k => inqMaxDate(projs.map(p => (CHECK_INFO[k] && p[CHECK_INFO[k].col + '_date']) || inqDateOf((p.check_dates || {})[k])));   // 직접 입력한 날짜 우선
    const st = [];
    st.push({ key: 'talk', label: '상담', done: true, sub: x.started_at ? inqMD(x.started_at) : '' });
    const qDone = quotes.length > 0 || ['견적발송', '수주', '제작중', '납품완료', '정산완료'].includes(x.status);
    const pre = x.pre_estimate && (x.pre_estimate.items || []).length ? x.pre_estimate : null;
    st.push({ key: 'quote', label: '견적', done: qDone,
        sub: quotes.length ? inqMD(inqMinDate(quotes.map(q => q.date))) + ' 발송' : (pre && pre.sent_at ? '가견적 ' + inqMD(inqDateOf(pre.sent_at)) : (pre ? '가견적 작성' : '')) });
    st.push({ key: 'won', label: '수주', done: n > 0, sub: n ? inqMD(inqMinDate(projs.map(p => inqDateOf(p.created_at)))) + (n > 1 ? ` · ${n}건` : '') : '' });
    const stepK = (key, label, k) => {
        const c = cnt(k);
        st.push({ key, label, done: n > 0 && c === n, sub: n && c === n ? (inqMD(kDate(k)) || '완료') : (c ? `${c}/${n}` : '') });
    };
    {
        const c = cnt('design');
        const dDate = inqMaxDate(projs.map(p => p.design_confirm_date || inqDateOf((p.check_dates || {}).design)));
        const ch = [...new Set(projs.map(p => p.design_confirm_channel).filter(Boolean))].join('·');
        st.push({ key: 'design', label: '디자인확인', done: n > 0 && c === n,
            sub: n && c === n ? [inqMD(dDate), ch].filter(Boolean).join(' ') || '완료' : (c ? `${c}/${n}` : '') });
    }
    {
        const c = cnt('workOrder');
        const wDate = inqMaxDate(projs.map(p => p.work_order_date || inqDateOf((p.check_dates || {}).workOrder)));
        const ch = [...new Set(projs.map(p => p.work_order_channel).filter(Boolean))].join('·');
        st.push({ key: 'wo', label: '작업요청', done: n > 0 && c === n,
            sub: n && c === n ? [inqMD(wDate), ch].filter(Boolean).join(' ') || '완료' : (c ? `${c}/${n}` : '') });
    }
    // 납품·정산은 체크마다 따로 (2026-10 현호님 요청) — 날짜는 체크할 때 입력한 날짜
    INQ_PAY_STAGES.forEach(([key, label, k]) => stepK(key, label, k));
    const ci = st.findIndex(s => !s.done);
    st.forEach((s, i) => { s.state = s.done ? 'done' : (i === ci ? 'cur' : 'todo'); });
    return { st, cur: ci < 0 ? null : st[ci], quotes, projs };
}

function inqRenderStage(x) {
    const el = document.getElementById('inqStage');
    if (!el || _inqSel !== x.id) return;
    const { st, cur, quotes, projs } = inqStages(x);
    const stopped = x.status === '보류' || x.status === '실패';
    const bar = `<div class="inq-stage-bar ${stopped ? 'stopped' : ''}">${st.map(s => `
        <div class="inq-stg ${s.state}">
          <i></i>
          <b>${escHtml(s.label)}</b>
          <span>${escHtml(s.sub || (s.state === 'cur' ? '진행 중' : ''))}</span>
        </div>`).join('')}</div>`;

    // 지금 할 일 — 현재 단계에 맞는 버튼
    let msg = '', btns = [];
    const firstLack = k => projs.find(p => !(p.checks && p.checks[k]));
    if (stopped) msg = `${x.status} 상태입니다${x.status === '실패' && x.fail_reason ? ' · ' + x.fail_reason : ''}`;
    else if (!cur) msg = '모든 단계가 끝났습니다';
    else if (cur.key === 'quote') {
        const pe = x.pre_estimate;
        if (pe && (pe.items || []).length) {
            if (pe.sent_at) { msg = '디자인이 확정되면 확정 견적을 작성하세요'; btns.push(['pre-copy', '가견적 안내문 복사']); btns.push(['pre-quote', '가견적으로 견적 작성', 1]); }
            else { msg = '가견적을 고객에게 안내하세요'; btns.push(['pre-copy', '안내문 복사']); btns.push(['pre-send', '안내 기록', 1]); }
        } else {
            msg = '가격이 확정 전이면 가견적을, 확정됐으면 견적을 보내세요';
            btns.push(['pre-new', '가견적 안내']);
            if (inqLinkCands(x).length) btns.push(['quote-link', '🔗 기존 견적 연결']);
            btns.push(['quote-new', '+ 이 상담으로 견적 작성', 1]);
        }
    }
    else if (cur.key === 'won') {
        msg = '견적이 확정되면 국내 프로젝트로 넘기세요 (수주)';
        if (quotes.length) { btns.push(['quote-doc', '견적서 보기']); btns.push(['transfer', '국내로 넘기기 · 수주', 1]); }
        else {
            if (inqLinkCands(x).length) btns.push(['quote-link', '🔗 기존 견적 연결']);
            btns.push(['quote-new', '+ 이 상담으로 견적 작성', 1]);
        }
    } else if (cur.key === 'design') {
        const p = firstLack('design');
        msg = `디자인확인서를 만들고 고객 컨펌을 받으세요${projs.length > 1 ? ` · ${p.product_name || ''}` : ''}`;
        btns.push([`dc:${p.id}`, p.source_doc_number ? '디자인확인서 열기' : '디자인확인서 만들기', 1]);
        btns.push([`chk:${p.id}:design`, '컨펌 완료 체크']);
    } else if (cur.key === 'wo') {
        const p = firstLack('workOrder');
        msg = `공장에 작업요청서를 보내세요${projs.length > 1 ? ` · ${p.product_name || ''}` : ''}`;
        btns.push([`wr:${p.id}`, '작업요청서 열기·만들기', 1]);
        btns.push([`chk:${p.id}:workOrder`, '발송 완료 체크']);
    } else {
        const ps = INQ_PAY_STAGES.find(v => v[0] === cur.key);
        if (ps) {
            // 순서가 바뀌어도(납품 먼저 등) 바로 체크할 수 있게 남은 것 전부 버튼으로, 지금 단계가 강조
            const p = firstLack(ps[2]);
            const lack = INQ_PAY_STAGES.filter(v => !(p.checks && p.checks[v[2]]));
            msg = `${ps[1]} 확인 — 끝났으면 체크하세요${projs.length > 1 ? ` · ${p.product_name || ''}` : ''}`;
            lack.forEach(v => btns.push([`chk:${p.id}:${v[2]}`, v[1] + ' ✓', v[0] === ps[0] ? 1 : 0]));
        }
    }
    const nowHtml = `
      <div class="inq-now ${stopped ? 'stopped' : !cur ? 'done' : ''}">
        <span class="inq-now-lab">지금 할 일</span>
        <span class="inq-now-msg">${escHtml(msg)}</span>
        <div class="inq-spacer"></div>
        ${btns.map(([a, l, pri]) => `<button class="inq-mini ${pri ? 'primary' : ''}" data-act="${escHtml(a)}">${escHtml(l)}</button>`).join('')}
      </div>`;
    const nowEl = document.getElementById('inqNow');
    if (nowEl) { el.innerHTML = bar; nowEl.innerHTML = nowHtml; }
    else el.innerHTML = bar + nowHtml;
    [el, nowEl].forEach(box => { if (box) box.querySelectorAll('[data-act]').forEach(b => b.addEventListener('click', () => inqDealAction(x, b.dataset.act, b))); });
}

// 국내 프로젝트가 전역 projects 배열에 없으면(페이지 밖) 넣어준다 — 문서 만들기·상세 모달이 projects를 쓰기 때문
function inqEnsureProject(row) {
    if (!row) return null;
    let p = projects.find(v => v.id === row.id);
    if (!p) { p = _projectsDomesticRowToObj(row); projects.push(p); }
    return p;
}

async function inqDealAction(x, act, btn) {
    const [kind, idStr, key] = act.split(':');
    const row = idStr ? _inqProjs.find(p => p.id === Number(idStr)) : null;
    if (kind === 'quote-new') { inqStartQuote(x.id); return; }
    if (kind === 'quote-link') { inqOpenQuoteLinkPicker(x); return; }
    if (kind.startsWith('pre-')) { await inqPreAction(x, kind.slice(4)); return; }
    if (kind === 'quote-doc' || kind === 'transfer') {
        const q = tempProjects.filter(p => p.inquiryId === x.id).sort((a, b) => String(b.date).localeCompare(String(a.date)))[0];
        if (!q) return;
        const gi = inqQuoteGroupIndex(q.date, q.client);
        if (gi < 0) return;
        if (kind === 'quote-doc') openTempQuote(gi);
        else { await transferGroupToDomestic(gi); }
        return;
    }
    if (kind === 'dc' || kind === 'wr') {
        // 이미 만든 문서는 보기 화면으로 (편집·덮어쓰기 확인 없이), 없을 때만 만들기
        const num = row ? await inqSavedDocNumber(row, kind) : null;
        if (num) { await viewSavedDoc(num, kind === 'dc' ? '디자인확인서' : '작업요청서', kind === 'dc' ? x : null); return; }
        if (inqEnsureProject(row)) createDocFromProject(row.id, kind);
        return;
    }
    if (kind === 'po') {
        if (!row) return;
        const num = await inqSavedDocNumber(row, 'po');
        if (num) { if (confirm(`해외 PO(${num})를 문서 생성기에서 열까요?`)) location.href = 'doc-generator.html#edit-' + encodeURIComponent(num); return; }
        if (confirm('아직 해외 PO가 없습니다. 새로 만들까요?\n(디자인확인서·해외 매입 정보를 불러와요 — 문서 생성기로 이동)')) location.href = 'doc-generator.html#po-new' + (row.source_doc_number ? '-' + encodeURIComponent(row.source_doc_number) : '');
        return;
    }
    if (kind === 'ps') {
        if (!row) return;
        const num = await inqSavedDocNumber(row, 'ps');
        if (num) { await viewSavedDoc(num, '제작진행표', null); return; }
        if (!row.source_doc_number) { showToast('디자인확인서를 먼저 만들어주세요 (제작진행표는 디자인확인서 내용을 불러와요)'); return; }
        if (confirm('아직 제작진행표가 없습니다. 디자인확인서 내용으로 새로 만들까요?\n(문서 생성기로 이동해요)')) location.href = 'doc-generator.html#ps-new-' + encodeURIComponent(row.source_doc_number);
        return;
    }
    if (kind === 'open') { if (inqEnsureProject(row)) showProjectDetail(row.id); return; }
    if (kind === 'chk') { if (btn) btn.disabled = true; await inqToggleProjCheck(x, row, key); }
}

// 상담 화면에서 국내 체크 — 국내 메뉴와 같은 규칙(전부 체크되면 '완료')
async function inqToggleProjCheck(x, row, key) {
    if (!row) return;
    const checks = Object.assign({}, row.checks || {});
    const update = { checks };
    const ci = CHECK_INFO[key];
    if (ci) {
        if (!checks[key]) {
            const info = await askCheckInfo(key, { channel: row[ci.col + '_channel'], date: row[ci.col + '_date'] });
            if (!info) { inqRenderStage(x); inqRenderProjs(x); return; }
            if (!ci.noChannel) update[ci.col + '_channel'] = info.channel;
            update[ci.col + '_date'] = info.date || null;
        } else {
            if (!ci.noChannel) update[ci.col + '_channel'] = '';
            update[ci.col + '_date'] = null;
        }
    }
    checks[key] = !checks[key];
    if (CHECK_ITEMS.every(it => !!checks[it.key]) && row.status !== '완료') update.status = '완료';
    const { data, error } = await sb.from('projects_domestic').update(update).eq('id', row.id).select().single();
    if (error) { showToast('저장 실패: ' + error.message); inqRenderStage(x); return; }
    Object.assign(row, data);
    const gp = projects.find(v => v.id === row.id);
    if (gp) {
        gp.checks = data.checks; if (update.status) gp.status = update.status;
        gp.designConfirmChannel = data.design_confirm_channel || ''; gp.designConfirmDate = data.design_confirm_date || '';
        gp.workOrderChannel = data.work_order_channel || ''; gp.workOrderDate = data.work_order_date || '';
        gp.advancePaymentDate = data.advance_payment_date || ''; gp.finalPaymentDate = data.final_payment_date || '';
        gp.invoiceDate = data.invoice_date || ''; gp.deliveredDate = data.delivered_date || '';
        gp.supplierPaymentDate = data.supplier_payment_date || '';
        try { renderProjects(); } catch (_) {}
    }
    const it = CHECK_ITEMS.find(c => c.key === key);
    showToast(`${it ? it.label : key} ${checks[key] ? '체크' : '해제'}`);
    inqRenderProjs(x);
    inqRenderStage(x);
    const fresh = await inqReloadInquiry(x.id);   // 트리거가 상태를 바꿨을 수 있음
    if (fresh) Object.assign(x, fresh);
    inqRenderStage(x);
    await inqLoadLogs(x.id);                      // 트리거가 남긴 기록
}

function inqRenderProjs(x) {
    const el = document.getElementById('inqProjs');
    if (!el || _inqSel !== x.id) return;
    const projs = _inqProjsFor === x.id ? _inqProjs : [];
    if (!projs.length) { el.innerHTML = ''; return; }
    const won = n => Number(n || 0).toLocaleString() + '원';
    const open = inqCardOpen('pj');
    el.innerHTML = `
      <div class="inq-q-head">${inqCardToggleBtn('pj', open)}<b>국내 진행</b><span class="inq-q-sum"><em>${projs.length}건 · 매출 <b class="rev">${won(projs.reduce((s, p) => s + (p.revenue || 0), 0))}</b></em></span></div>
      ${open ? `<div class="inq-pj-list">${projs.map(p => {
          const cd = p.check_dates || {};
          const done = CHECK_ITEMS.filter(it => p.checks && p.checks[it.key]).length;
          return `
        <div class="inq-pj">
          <div class="inq-pj-top">
            <b>${escHtml(p.product_name || '(품목 없음)')}</b>
            <span>${p.quantity ? Number(p.quantity).toLocaleString() + (p.unit || '개') : ''}${p.supplier ? ' · ' + escHtml(p.supplier) : ''}${p.supplier_overseas ? ` · <b class="inq-ovs" title="해외 매입 (달러)">🌏 $${Number(p.supplier_overseas.unit || 0).toLocaleString(undefined, { maximumFractionDigits: 2 })}</b>` : ''}</span>
            <span class="inq-pj-amt">${won(p.revenue)}</span>
            <span class="inq-pj-prog">${done}/${CHECK_ITEMS.length}</span>
            <div class="inq-spacer"></div>
            ${p.supplier_overseas ? `<button class="inq-mini" data-act="po:${p.id}" title="해외 공장에 보내는 영문 발주서(PO) — 있으면 열기, 없으면 만들기">🌏 해외 PO</button>` : ''}
            <button class="inq-mini" data-act="ps:${p.id}" title="시계 제작 주문 내부 문서 — 있으면 보기, 없으면 만들기">🕐 제작진행표</button>
            <button class="inq-mini" data-act="open:${p.id}">국내에서 보기</button>
          </div>
          <div class="inq-pj-docs">${['dc', 'wr'].map(k => inqDocTileHtml(p, k)).join('')}</div>
          <div class="inq-pj-checks">${CHECK_ITEMS.map(it => {
              const on = !!(p.checks && p.checks[it.key]);
              const ciK = CHECK_INFO[it.key];
              const d = ciK && on && (p[ciK.col + '_channel'] || p[ciK.col + '_date'])
                  ? [p[ciK.col + '_channel'], p[ciK.col + '_date'] ? inqMD(p[ciK.col + '_date']) : ''].filter(Boolean).join(' · ')
                  : (cd[it.key] ? inqMD(inqDateOf(cd[it.key])) : '');
              return `<button class="inq-ck ${on ? 'on' : ''}" data-act="chk:${p.id}:${it.key}" title="${escHtml(it.label)}${on ? (d ? ' · ' + d + ' 체크' : ' · 완료') : ' — 누르면 체크'}">
                  <i>${on ? '✓' : ''}</i>${escHtml(it.label)}${d ? `<em>${d}</em>` : ''}</button>`;
          }).join('')}</div>
        </div>`;
      }).join('')}</div>` : ''}`;
    inqBindCardToggle(el, 'pj', () => inqRenderProjs(x));
    el.querySelectorAll('[data-act]').forEach(b => b.addEventListener('click', () => inqDealAction(x, b.dataset.act, b)));
    if (open) inqFillDocTiles(x);
}

// ---------- 국내 진행 카드의 디자인확인서·작업요청서 미리보기 (누르면 크게 = viewSavedDoc) ----------
const _inqDocNum = new Map();   // 'dc:DC번호' / 'wr:DC번호' → 저장된 문서번호(없으면 null)
function inqDocTileState(p, kind) {
    if (!p.source_doc_number) return { st: kind === 'wr' ? 'needdc' : 'empty' };
    const ck = kind + ':' + p.source_doc_number;
    if (!_inqDocNum.has(ck)) return { st: 'loading' };
    const num = _inqDocNum.get(ck);
    if (!num) return { st: 'empty' };
    const th = _savedDocThumb.get(num);
    if (th) return { st: 'img', src: th, num };
    if (_savedDocFail.has(num)) return { st: 'err', num };
    return { st: 'loading', num };
}
function inqDocTileInner(kind, t) {
    const label = kind === 'dc' ? '디자인확인서' : '작업요청서';
    if (t.st === 'img') return `<img src="${t.src}" alt="${label} 미리보기"><span class="inq-doc-lb">${label}</span>`;
    if (t.st === 'empty') return `<div class="inq-doc-ph"><b>＋</b>${label} 만들기</div>`;
    if (t.st === 'needdc') return `<div class="inq-doc-ph"><b>＋</b>${label}<em>디자인확인서를 먼저 만들어주세요</em></div>`;
    if (t.st === 'err') return `<div class="inq-doc-ph">미리보기를 못 그렸어요<em>눌러서 열기</em></div><span class="inq-doc-lb">${label}</span>`;
    return `<div class="inq-doc-ph"><i class="inq-doc-spin"></i>불러오는 중…</div><span class="inq-doc-lb">${label}</span>`;
}
function inqDocTileHtml(p, kind) {
    const t = inqDocTileState(p, kind);
    const empty = t.st === 'empty' || t.st === 'needdc';
    return `<button type="button" class="inq-doc-th ${empty ? 'empty' : ''}" data-act="${kind}:${p.id}" data-doctile="${kind}:${p.id}"
        title="${kind === 'dc' ? '디자인확인서' : '작업요청서'}${empty ? ' 만들기' : ' — 누르면 크게 보기'}">${inqDocTileInner(kind, t)}</button>`;
}
function inqSetDocTile(p, kind) {
    const b = document.querySelector(`#inqProjs [data-doctile="${kind}:${p.id}"]`);
    if (!b) return;
    const t = inqDocTileState(p, kind);
    b.classList.toggle('empty', t.st === 'empty' || t.st === 'needdc');
    b.innerHTML = inqDocTileInner(kind, t);
}
async function inqFillDocTiles(x) {
    const projs = _inqProjsFor === x.id ? _inqProjs.slice() : [];
    for (const p of projs) for (const kind of ['dc', 'wr']) {
        if (_inqSel !== x.id) return;
        if (!p.source_doc_number) continue;
        const ck = kind + ':' + p.source_doc_number;
        if (!_inqDocNum.has(ck)) {
            try { _inqDocNum.set(ck, await inqSavedDocNumber(p, kind)); } catch (_) { continue; }
            inqSetDocTile(p, kind);
        }
        const num = _inqDocNum.get(ck);
        if (!num || _savedDocThumb.has(num) || _savedDocFail.has(num)) continue;
        try { await getSavedDoc(num, kind === 'dc' ? '디자인확인서' : '작업요청서'); }
        catch (e) { console.warn('문서 미리보기 실패', num, e); _savedDocFail.add(num); }
        inqSetDocTile(p, kind);
    }
}

// 고객 정보 한 줄 요약 (접힌 상태)
function inqContactSummary(x) {
    const who = [x.contact_name || x.client_contact, [x.contact_dept, x.contact_title].filter(Boolean).join(' ')].filter(Boolean).join(' · ');
    const parts = [who, x.contact_phone, x.contact_email].filter(Boolean);
    const meta = [x.channel ? inqJosaRo(x.channel) + ' 문의' : '', x.assignee ? '담당 ' + x.assignee : '', x.started_at ? inqMD(x.started_at) + ' 시작' : ''].filter(Boolean);
    return `<span class="inq-ci-main">${parts.length ? parts.map(v => `<span>${escHtml(v)}</span>`).join('<i>·</i>') : '<em>고객 연락처 없음</em>'}</span><span class="inq-ci-meta">${meta.map(escHtml).join(' · ')}</span>`;
}

// ---------- 가견적 — 디자인 확정 전 예상가 범위 안내 (migration 039) ----------
// inquiries.pre_estimate jsonb: { items:[{item, qty, min, max}], vat, lead, note, updated_at, sent_at, sent_count }
// 견적(projects_temp)과 분리 — 매출·마진·국내 등록에 섞이지 않는다
const INQ_PRE_NOTE = '디자인 확정 전 예상 금액이며, 디자인 확정 후 정확한 견적을 드리겠습니다.';
let _inqPreEditing = null;   // 편집 중인 상담 id

function inqPreNum(v) { return Number(String(v == null ? '' : v).replace(/[^0-9]/g, '')) || 0; }
function inqPreWon(n) { return Number(n || 0).toLocaleString() + '원'; }
function inqPreRange(a, b) {
    a = a || 0; b = b || 0;
    if (a && b && a !== b) return `${Number(Math.min(a, b)).toLocaleString()} ~ ${inqPreWon(Math.max(a, b))}`;
    return inqPreWon(a || b);
}
// 화면용 — '~' 앞에서만 줄바꿈 (좁은 칸에서 숫자가 쪼개지지 않게)
function inqPreRangeHtml(a, b) {
    a = a || 0; b = b || 0;
    if (a && b && a !== b) return `<span class="nw">${Number(Math.min(a, b)).toLocaleString()} ~</span> <span class="nw">${inqPreWon(Math.max(a, b))}</span>`;
    return `<span class="nw">${inqPreWon(a || b)}</span>`;
}
function inqPreTotals(pe) {
    let lo = 0, hi = 0;
    (pe.items || []).forEach(it => {
        const q = it.qty || 0, a = it.min || it.max || 0, b = it.max || it.min || 0;
        lo += q * Math.min(a, b); hi += q * Math.max(a, b);
    });
    return { lo, hi };
}

// 고객에게 보낼 안내문 (메일·카톡에 붙여넣기)
function inqPreText(x) {
    const pe = x.pre_estimate || {};
    const s = (currentCompany && currentCompany.settings) || {};
    const brand = s.brandName || (currentCompany && currentCompany.name) || '';
    const vat = pe.vat || 'VAT 별도';
    const lines = [`[${x.client || '고객'}] 가견적 안내`, ''];
    (pe.items || []).forEach(it => {
        lines.push(`■ ${it.item || '품목'}${it.qty ? ` · ${Number(it.qty).toLocaleString()}개` : ''}`);
        lines.push(`  개당 ${inqPreRange(it.min, it.max)} (${vat})`);
        if (it.qty) lines.push(`  예상 합계 ${inqPreRange(it.qty * (it.min || it.max), it.qty * (it.max || it.min))}`);
        lines.push('');
    });
    if ((pe.items || []).length > 1) {
        const t = inqPreTotals(pe);
        lines.push(`총 예상 금액 ${inqPreRange(t.lo, t.hi)} (${vat})`, '');
    }
    if (pe.lead) lines.push(`· 제작기간: ${pe.lead}`);
    lines.push(`· ${pe.note || INQ_PRE_NOTE}`);
    if (brand) lines.push('', `${brand} 드림`);
    return lines.join('\n');
}

function inqRenderPre(x) {
    const el = document.getElementById('inqPre');
    if (!el || _inqSel !== x.id) return;
    const pe = x.pre_estimate;
    if (_inqPreEditing === x.id) { inqRenderPreEditor(x); return; }
    if (!pe || !(pe.items || []).length) { el.innerHTML = ''; return; }
    const vat = pe.vat || 'VAT 별도';
    const t = inqPreTotals(pe);
    const open = inqCardOpen('pre');
    el.innerHTML = `
      <div class="inq-q-head">
        ${inqCardToggleBtn('pre', open)}
        <b>가견적</b>
        <span class="inq-q-sum">
          <em>예상 합계 <b class="pre">${inqPreRangeHtml(t.lo, t.hi)}</b> (${escHtml(vat)})</em>
          ${pe.sent_at ? `<em class="inq-pre-sent">${inqMD(inqDateOf(pe.sent_at))} 안내함${pe.sent_count > 1 ? ` · ${pe.sent_count}회` : ''}</em>` : '<em class="inq-pre-unsent">아직 안내 안 함</em>'}
        </span>
        <div class="inq-spacer"></div>
        <button class="inq-mini" data-pre="copy">안내문 복사</button>
        <button class="inq-mini" data-pre="send">${pe.sent_at ? '다시 안내 기록' : '안내 기록'}</button>
        <button class="inq-mini" data-pre="edit">수정</button>
      </div>
      ${open ? `<div class="inq-qg inq-pre-box">
        <div class="inq-qi-list">${pe.items.map(it => `<div class="inq-qi">
          <div class="inq-qi-top"><b>${escHtml(it.item || '-')}</b>${it.qty ? `<span>${Number(it.qty).toLocaleString()}개</span>` : ''}</div>
          <div class="inq-qi-nums two">
            <div><em>개당 예상 (${escHtml(vat)})</em><b class="pre">${inqPreRangeHtml(it.min, it.max)}</b></div>
            <div><em>예상 합계</em>${it.qty ? `<b>${inqPreRangeHtml(it.qty * (it.min || it.max), it.qty * (it.max || it.min))}</b>` : '<span class="inq-qt-dash">-</span>'}</div>
          </div>
        </div>`).join('')}</div>
        ${pe.lead || pe.note ? `<div class="inq-qg-note">${pe.lead ? `<span>제작기간</span>${escHtml(pe.lead)}<br>` : ''}<span>안내</span>${escHtml(pe.note || INQ_PRE_NOTE)}</div>` : ''}
      </div>` : ''}`;
    inqBindCardToggle(el, 'pre', () => inqRenderPre(x));
    el.querySelectorAll('[data-pre]').forEach(b => b.addEventListener('click', () => inqPreAction(x, b.dataset.pre)));
}

function inqRenderPreEditor(x) {
    const el = document.getElementById('inqPre');
    if (!el) return;
    const pe = x.pre_estimate || {};
    // 품목 기본값 = 문의 제목에서 '제작 문의 (…)' 같은 꼬리를 뗀 것 ('미니 시계 키링 제작 문의 (단가…)' → '미니 시계 키링')
    const guess = String(x.title || '').replace(/\s*\(.*$/, '').replace(/(\s*(제작|주문|구매|대량|문의|견적|요청|건))+\s*$/, '').trim();
    const items = (pe.items && pe.items.length) ? pe.items : [{ item: guess, qty: '', min: '', max: '' }];
    const fmt = n => n ? Number(n).toLocaleString() : '';
    const row = it => `<div class="inq-pre-row">
        <input data-f="item" placeholder="품목 — 예) 미니 시계 키링" value="${escHtml(it.item || '')}">
        <input data-f="qty" inputmode="numeric" placeholder="수량" value="${fmt(it.qty)}">
        <input data-f="min" inputmode="numeric" placeholder="최저 단가" value="${fmt(it.min)}">
        <span>~</span>
        <input data-f="max" inputmode="numeric" placeholder="최고 단가" value="${fmt(it.max)}">
        <button type="button" class="inq-todo-del" data-rm title="빼기">×</button>
      </div>`;
    el.innerHTML = `
      <div class="inq-q-head"><b>가견적 ${pe.items ? '수정' : '작성'}</b><span>디자인 확정 전 예상가 범위 — 매출·마진에는 들어가지 않아요</span></div>
      <div class="inq-pre-edit">
        <div class="inq-pre-head"><span>품목</span><span>수량</span><span>개당 예상 단가 (범위)</span></div>
        <div id="inqPreRows">${items.map(row).join('')}</div>
        <button type="button" class="inq-todo-link" id="inqPreAdd">+ 품목 추가</button>
        <div class="inq-pre-opts">
          <label><span>부가세</span><select id="inqPreVat">${inqOpt(['VAT 별도', 'VAT 포함'], pe.vat || 'VAT 별도')}</select></label>
          <label class="grow"><span>제작기간</span><input id="inqPreLead" placeholder="예) 디자인 확정 후 약 3~4주" value="${escHtml(pe.lead || '')}"></label>
        </div>
        <label class="inq-pre-note"><span>안내 문구</span><textarea id="inqPreNote" rows="2">${escHtml(pe.note || INQ_PRE_NOTE)}</textarea></label>
        <div class="inq-edit-act">
          ${pe.items ? '<button type="button" class="btn-ghost" id="inqPreDel" style="margin-right:auto;color:var(--red)">가견적 삭제</button>' : '<span></span>'}
          <button type="button" class="btn-ghost" id="inqPreCancel">취소</button>
          <button type="button" class="btn-ghost" id="inqPreSave">저장</button>
          <button type="button" class="btn-primary" id="inqPreSaveSend">저장하고 안내 기록</button>
        </div>
      </div>`;
    const $ = id => document.getElementById(id);
    const bindRows = () => {
        $('inqPreRows').querySelectorAll('.inq-pre-row').forEach(r => {
            r.querySelectorAll('[data-f="qty"],[data-f="min"],[data-f="max"]').forEach(i => i.oninput = () => { const n = inqPreNum(i.value); i.value = n ? n.toLocaleString() : ''; });
            r.querySelector('[data-rm]').onclick = () => { if ($('inqPreRows').children.length > 1) r.remove(); };
        });
    };
    bindRows();
    $('inqPreAdd').addEventListener('click', () => {
        $('inqPreRows').insertAdjacentHTML('beforeend', row({}));
        bindRows();
        $('inqPreRows').lastElementChild.querySelector('input').focus();
    });
    $('inqPreCancel').addEventListener('click', () => { _inqPreEditing = null; inqRenderPre(x); });
    if ($('inqPreDel')) $('inqPreDel').addEventListener('click', async () => {
        if (!confirm('가견적을 삭제할까요? (이미 남긴 안내 기록은 그대로 남습니다)')) return;
        const d = await inqPatch(x.id, { pre_estimate: null }, '가견적 삭제');
        if (d) { Object.assign(x, d); _inqPreEditing = null; inqRenderPre(x); inqRenderStage(x); }
    });
    const collect = () => {
        const items = [];
        $('inqPreRows').querySelectorAll('.inq-pre-row').forEach(r => {
            const g = f => r.querySelector(`[data-f="${f}"]`).value;
            const it = { item: g('item').trim(), qty: inqPreNum(g('qty')), min: inqPreNum(g('min')), max: inqPreNum(g('max')) };
            if (it.item || it.min || it.max) items.push(it);
        });
        return items;
    };
    const save = async (send) => {
        const items = collect();
        if (!items.length) { showToast('품목과 예상 단가를 입력해주세요'); return; }
        if (items.some(it => !it.min && !it.max)) { showToast('예상 단가를 입력해주세요 (한 가격이면 최저 칸만 적어도 됩니다)'); return; }
        const next = Object.assign({}, x.pre_estimate || {}, {
            items, vat: $('inqPreVat').value, lead: $('inqPreLead').value.trim(),
            note: $('inqPreNote').value.trim() || INQ_PRE_NOTE, updated_at: new Date().toISOString()
        });
        const d = await inqPatch(x.id, { pre_estimate: next });
        if (!d) return;
        Object.assign(x, d);
        _inqPreEditing = null;
        inqRenderPre(x);
        inqRenderStage(x);
        if (send) await inqPreAction(x, 'send');
        else showToast('가견적을 저장했습니다');
    };
    $('inqPreSave').addEventListener('click', () => save(false));
    $('inqPreSaveSend').addEventListener('click', () => save(true));
    const first = $('inqPreRows').querySelector('[data-f="min"]');
    if (first && !first.value) first.focus();
}

async function inqPreAction(x, act) {
    if (act === 'edit' || act === 'new') { _inqPreEditing = x.id; inqRenderPre(x); const el = document.getElementById('inqPre'); if (el) el.scrollIntoView({ block: 'nearest' }); return; }
    const pe = x.pre_estimate;
    if (!pe || !(pe.items || []).length) { inqPreAction(x, 'new'); return; }
    if (act === 'copy') {
        const text = inqPreText(x);
        try { await navigator.clipboard.writeText(text); showToast('안내문을 복사했습니다 — 메일·카톡에 붙여넣으세요'); }
        catch (_) { prompt('아래 안내문을 복사하세요 (Ctrl+C)', text); }
        return;
    }
    if (act === 'send') {
        if (await inqPreMarkSent(x, x.channel || '', inqPreText(x))) showToast('가견적 안내를 기록했습니다 · 안내문 복사로 고객에게 보내세요');
        return;
    }
    if (act === 'quote') {

        // 가견적 품목으로 확정 견적 시작 — 단가는 확정가로 직접 입력
        inqStartQuote(x.id);
        const it = pe.items[0];
        const set = (id, v) => { const e = document.getElementById(id); if (e) e.value = v; };
        set('tempInItem', it.item || '');
        set('tempInQty', it.qty ? Number(it.qty).toLocaleString() : '');
        const up = document.getElementById('tempInUnitPrice');
        if (up) { up.value = ''; up.placeholder = `확정 단가 (가견적 ${inqPreRange(it.min, it.max)})`; up.focus(); }
        showToast(pe.items.length > 1 ? `첫 품목을 채웠어요. 나머지 ${pe.items.length - 1}개 품목도 추가해주세요` : '가견적 품목을 채웠어요 — 확정 단가를 입력하세요');
    }
}

// 가견적 안내를 보냈다고 기록: 우리 답변 + 안내 날짜·횟수 + 상태 신규·상담중 → 가견적
async function inqPreMarkSent(x, channel, text) {
    const pe = x.pre_estimate || {};
    const saved = await inqAddLog(x.id, { direction: 'out', channel: channel || '', body: text, images: [] });
    if (!saved) return false;
    const next = Object.assign({}, pe, { sent_at: new Date().toISOString(), sent_count: (pe.sent_count || 0) + 1 });
    const patch = { pre_estimate: next, last_contact_at: new Date().toISOString() };
    const bump = ['신규', '상담중'].includes(x.status);
    if (bump) patch.status = '가견적';
    const d = await inqPatch(x.id, patch, bump ? `상태 변경 · ${x.status} → 가견적` : null);
    if (d) {
        Object.assign(x, d);
        const sel = document.getElementById('inqFStatus');
        if (sel) { sel.value = d.status; sel.className = 'inq-h-status ' + (INQ_STATUS_CLS[d.status] || ''); }
    }
    inqRenderPre(x); inqRenderStage(x);
    return true;
}

// ---------- 보내기 (send-kit.js) — 견적서 · 가견적 안내 · 안내 메시지 · 디자인확인서/작업요청서(문서 생성기) ----------
function inqSendVars(x, extra) {
    const items = Array.isArray(x.items) ? x.items.filter(i => i && i.name) : [];
    const itemLabel = items.length ? items[0].name + (items.length > 1 ? ` 외 ${items.length - 1}건` : '') : (x.title || '');
    const qty = items.length && items[0].qty && !items[0].tbd ? Number(items[0].qty).toLocaleString() + '개' : '';
    return Object.assign({
        거래처: x.client || '', 담당자: [x.contact_name || x.client_contact, x.contact_title].filter(Boolean).join(' '),
        품목: itemLabel, 수량: qty, 합계: '', 납기: x.due_date ? inqMD(x.due_date) : '', 문서번호: '',
        작성자: (currentUser && currentUser.name) || '', 작성자직함: sendMyTitle(), 내용: ''
    }, extra || {});
}
function inqSendTo(x) {
    const cli = sendFindClient(x.client);
    return {
        email: x.contact_email || (cli && (cli.staffEmail || cli.email)) || '',
        phone: x.contact_phone || (cli && (cli.staffMobile || cli.mobile)) || ''
    };
}
function inqSendMenu(x, btn) {
    const old = document.getElementById('inqSendMenu');
    if (old) { old.remove(); return; }
    x = inqFind(x.id) || x;                                                      // 화면이 다시 그려졌어도 최신 상담으로
    if (!btn || !btn.isConnected) btn = document.getElementById('inqFSend') || btn;
    const groups = [];
    tempProjects.filter(p => p.inquiryId === x.id).forEach(p => {
        const k = (p.date || '') + '||' + (p.client || '');
        let g = groups.find(v => v.k === k);
        if (!g) { g = { k, date: p.date, n: 0 }; groups.push(g); }
        g.n++;
    });
    groups.sort((a, b) => String(b.date).localeCompare(String(a.date)));
    const projs = _inqProjsFor === x.id ? _inqProjs : [];
    const hasPre = x.pre_estimate && (x.pre_estimate.items || []).length;
    const rows = [];
    rows.push('<div class="inq-send-cap">고객에게</div>');
    groups.forEach(g => rows.push(`<button data-s="quote:${escHtml(g.k)}">📄 견적서 <em>${escHtml(inqMD(g.date))} · ${g.n}품목 · PDF 첨부</em></button>`));
    if (!groups.length) rows.push('<div class="inq-send-empty">연결된 견적서가 없어요 — 견적을 만들면 여기서 보낼 수 있어요</div>');
    if (hasPre) rows.push('<button data-s="pre">💡 가견적 안내 <em>금액 범위 · 첨부 없음</em></button>');
    rows.push('<button data-s="msg">✉️ 안내 메시지 <em>글만 · 양식에서 시작</em></button>');
    projs.forEach(p => rows.push(`<button data-s="dc:${p.id}">🎨 디자인확인서 <em>${escHtml(p.product_name || '')} · ${p.source_doc_number ? escHtml(p.source_doc_number) + ' 저장된 문서 그대로' : '아직 없음 — 만들기'}</em></button>`));
    if (projs.length) {
        rows.push('<div class="inq-send-cap">공장·공급처에게</div>');
        projs.forEach(p => rows.push(`<button data-s="wr:${p.id}">📋 작업요청서 <em>${escHtml(p.product_name || '')}${p.supplier ? ' → ' + escHtml(p.supplier) : ''} · ${p.source_doc_number ? '저장된 문서 그대로' : '디자인확인서 먼저'}</em></button>`));
    }
    const m = document.createElement('div');
    m.id = 'inqSendMenu';
    m.className = 'inq-send-menu';
    m.innerHTML = rows.join('');
    document.body.appendChild(m);
    const r = btn.getBoundingClientRect();
    m.style.top = Math.max(8, Math.min(r.bottom + 6, window.innerHeight - m.offsetHeight - 8)) + 'px';
    m.style.left = Math.max(8, Math.min(window.innerWidth - m.offsetWidth - 8, r.right - m.offsetWidth)) + 'px';
    const off = e => { if (!m.contains(e.target) && e.target !== btn) { m.remove(); document.removeEventListener('mousedown', off, true); } };
    setTimeout(() => document.addEventListener('mousedown', off, true), 0);
    m.addEventListener('click', e => {
        const b = e.target.closest('[data-s]');
        if (!b) return;
        m.remove();
        document.removeEventListener('mousedown', off, true);
        inqSendGo(x, b.dataset.s);
    });
}
async function inqSendGo(x, what) {
    if (!window.SendKit) { showToast('보내기 기능을 불러오지 못했습니다. 새로고침 해주세요'); return; }
    sendKitSetup();
    if (what.startsWith('quote:')) {
        const [date, client] = what.slice(6).split('||');
        const gi = inqQuoteGroupIndex(date, client);
        if (gi < 0) { showToast('견적서를 찾지 못했습니다'); return; }
        openTempQuote(gi);
        await sendTempQuote();
        return;
    }
    if (what.startsWith('dc:') || what.startsWith('wr:')) {
        const [kind, id] = what.split(':');
        const row = _inqProjs.find(p => p.id === Number(id));
        if (row) await inqSendSavedDoc(row, kind, x);
        return;
    }
    if (what === 'pre') {
        // 안내문에서 제목 줄과 끝 서명은 빼고 품목·금액 부분만 {내용}으로
        let lines = inqPreText(x).split('\n').slice(2);
        while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
        if (lines.length && / 드림$/.test(lines[lines.length - 1])) { lines.pop(); while (lines.length && !lines[lines.length - 1].trim()) lines.pop(); }
        SendKit.open({
            docType: 'pre', title: `${x.client || '고객'} · 가견적 안내`,
            vars: inqSendVars(x, { 내용: lines.join('\n') }), to: inqSendTo(x),
            sentLabel: '✓ 보냈어요 — 가견적 안내로 기록',
            onSent: async ({ channel, text }) => { if (!(await inqPreMarkSent(x, channel, text))) throw new Error('기록 저장 실패'); }
        });
        return;
    }
    SendKit.open({
        docType: 'msg', title: `${x.client || '고객'} · 안내 메시지`,
        vars: inqSendVars(x), to: inqSendTo(x),
        onSent: async ({ channel, text }) => { await inqSendLogged(x, channel, text); }
    });
}
// 이미 저장된 디자인확인서·작업요청서를 그대로 열어 보내기 창까지 (문서 생성기 #send-문서번호)
// — '만들기'(createDocFromProject)는 프로젝트 데이터로 덮어쓸지 묻기 때문에 보내기에서는 쓰지 않음
// 상담에 연결된 국내 품목의 저장된 디자인확인서·작업요청서 문서번호 (없으면 null)
async function inqSavedDocNumber(row, kind) {
    if (!row || !row.source_doc_number) return null;
    if (kind === 'dc') return row.source_doc_number;
    const prefix = row.source_doc_number + '_';
    const st = kind === 'ps' ? '제작진행표' : kind === 'po' ? '해외작업요청서' : '작업요청서';
    const { data, error } = await sb.from('confirmations').select('doc_number, created_at, status')
        .like('doc_number', prefix + '%').order('created_at', { ascending: false });
    if (error) { showToast(st + ' 찾기 실패: ' + error.message); return null; }
    const wr = (data || []).find(d => d.status === st && String(d.doc_number || '').startsWith(prefix));
    return wr ? wr.doc_number : null;
}
async function inqSendSavedDoc(row, kind, x) {
    const label = kind === 'dc' ? '디자인확인서' : '작업요청서';
    const make = () => { if (inqEnsureProject(row)) createDocFromProject(row.id, kind); };
    if (kind === 'wr' && !row.source_doc_number) { showToast('디자인확인서를 먼저 만들어주세요'); return; }
    const num = await inqSavedDocNumber(row, kind);
    if (!num) { if (confirm(`아직 ${label}가 없습니다. 지금 만들까요?`)) make(); return; }
    await sendSavedDocHere(num, kind === 'dc' ? x : null, label);   // 작업요청서는 공장에 보내는 거라 상담 기록은 안 남김
}

// 화면 이동 없이: 문서 생성기를 숨은 창(iframe, #render-문서번호)으로 열어 저장된 문서를 그리고 보내기 정보를 받아옴
let _sendDocBusy = false;
async function loadSavedDocOpts(docNumber, label, quiet) {
    if (!quiet) showToast(`${label} 불러오는 중…`);
    const old = document.getElementById('docRenderFrame');
    if (old) old.remove();
    const fr = document.createElement('iframe');
    fr.id = 'docRenderFrame';
    fr.setAttribute('aria-hidden', 'true');
    fr.tabIndex = -1;
    fr.style.cssText = 'position:fixed;left:-12000px;top:0;width:1000px;height:1400px;border:0;';
    fr.src = 'doc-generator.html#render-' + encodeURIComponent(docNumber);
    document.body.appendChild(fr);
    await new Promise((ok, no) => { fr.onload = ok; setTimeout(() => no(new Error('불러오기 시간 초과')), 25000); });
    const ready = fr.contentWindow && fr.contentWindow.klpDocReady;
    if (!ready) throw new Error('문서 생성기를 열지 못했습니다 (로그인 확인)');
    const opts = await Promise.race([ready, new Promise((_, no) => setTimeout(() => no(new Error('문서 그리기 시간 초과')), 25000))]);
    if (!opts) throw new Error('문서 내용을 읽지 못했습니다');
    return opts;
}
// 문서번호 → Promise<{ jpg(원본), thumb(작은 그림), opts(보내기 정보 — makeCanvas는 원본 그림에서 다시 만듦) }>
// 이 화면에 있는 동안만 기억 (문서를 고치려면 문서 생성기로 이동 → 돌아오면 새로 그림)
const _savedDocCache = new Map();
const _savedDocThumb = new Map();
const _savedDocFail = new Set();
let _docFrameChain = Promise.resolve();
function getSavedDoc(docNumber, label) {
    if (_savedDocCache.has(docNumber)) return _savedDocCache.get(docNumber);
    const job = _docFrameChain.then(async () => {
        const opts = await loadSavedDocOpts(docNumber, label, true);
        const canvas = await opts.makeCanvas();
        const jpg = canvas.toDataURL('image/jpeg', 0.92);
        const tw = 480, th = Math.max(1, Math.round(canvas.height * tw / canvas.width));
        const t = document.createElement('canvas');
        t.width = tw; t.height = th;
        const g = t.getContext('2d');
        g.imageSmoothingQuality = 'high';
        g.drawImage(canvas, 0, 0, tw, th);
        const thumb = t.toDataURL('image/jpeg', 0.86);
        opts.makeCanvas = () => new Promise((ok, no) => {
            const im = new Image();
            im.onload = () => { const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight; c.getContext('2d').drawImage(im, 0, 0); ok(c); };
            im.onerror = () => no(new Error('문서 그림을 읽지 못했습니다'));
            im.src = jpg;
        });
        const fr = document.getElementById('docRenderFrame');
        if (fr) fr.remove();
        _savedDocThumb.set(docNumber, thumb);
        _savedDocFail.delete(docNumber);
        return { jpg, thumb, opts };
    });
    _docFrameChain = job.catch(() => {});
    _savedDocCache.set(docNumber, job);
    job.catch(() => _savedDocCache.delete(docNumber));
    return job;
}
function savedDocOnSent(opts, x, label) {
    if (!x) return opts;
    opts.onSent = async ({ channel, text }) => {
        const saved = await inqAddLog(x.id, { direction: 'out', channel, body: `[${label} 발송]\n${text}` });
        if (!saved) throw new Error('기록 저장 실패');
        await inqPatch(x.id, { last_contact_at: new Date().toISOString() });
    };
    return opts;
}
async function sendSavedDocHere(docNumber, x, label) {
    if (_sendDocBusy) return;
    if (!window.SendKit) { showToast('보내기 기능을 불러오지 못했습니다. 새로고침 해주세요'); return; }
    _sendDocBusy = true;
    try {
        if (!_savedDocThumb.has(docNumber)) showToast(`${label} 불러오는 중…`);
        const d = await getSavedDoc(docNumber, label);
        const opts = savedDocOnSent(Object.assign({}, d.opts), x, label);
        sendKitSetup();
        SendKit.open(opts);
    } catch (e) {
        console.error('문서 보내기 준비 실패', e);
        showToast(`${label} 불러오기 실패: ${e.message}`);
    } finally {
        _sendDocBusy = false;
    }
}

// 저장된 디자인확인서·작업요청서 '보기' (편집 화면으로 가지 않음) — 보내기·PDF·JPG·편집 버튼
async function viewSavedDoc(docNumber, label, x) {
    if (_sendDocBusy) return;
    _sendDocBusy = true;
    try {
        if (!_savedDocThumb.has(docNumber)) showToast(`${label} 불러오는 중…`);
        const d = await getSavedDoc(docNumber, label);
        const opts = savedDocOnSent(Object.assign({}, d.opts), x, label);
        const jpg = d.jpg;
        const old = document.getElementById('docViewOverlay');
        if (old) old.remove();
        const ov = document.createElement('div');
        ov.id = 'docViewOverlay';
        ov.className = 'docview';
        ov.innerHTML = `
          <div class="docview-bar">
            <b>${escHtml(label)} <em>${escHtml(docNumber)}</em></b>
            <span class="docview-t">${escHtml(opts.title || '')}</span>
            <div class="inq-spacer"></div>
            ${opts.docType === 'ps' ? '<span class="docview-t">내부 문서 · 외부 발송 금지</span>' : '<button data-v="send" class="primary">📤 보내기</button>'}
            <button data-v="pdf">PDF</button>
            <button data-v="jpg">JPG</button>
            <button data-v="edit">✏️ 편집</button>
            <button data-v="close" aria-label="닫기">✕</button>
          </div>
          <div class="docview-body"><img src="${jpg}" alt="${escHtml(label)}"></div>`;
        document.body.appendChild(ov);
        const close = () => { ov.remove(); document.removeEventListener('keydown', onKey, true); };
        const onKey = e => { if (e.key === 'Escape' && !document.getElementById('skWrap')) { e.stopPropagation(); close(); } };
        document.addEventListener('keydown', onKey, true);
        ov.addEventListener('click', e => {
            if (e.target === ov) { close(); return; }
            const b = e.target.closest('[data-v]');
            if (!b) return;
            const v = b.dataset.v;
            if (v === 'close') close();
            else if (v === 'send') { if (window.SendKit) { sendKitSetup(); SendKit.open(opts); } }
            else if (v === 'jpg') { const a = document.createElement('a'); a.href = jpg; a.download = (opts.fileBase || label) + '.jpg'; a.click(); }
            else if (v === 'pdf') {
                const pdf = new jspdf.jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
                pdf.addImage(jpg, 'JPEG', 0, 0, pdf.internal.pageSize.getWidth(), pdf.internal.pageSize.getHeight());
                pdf.save((opts.fileBase || label) + '.pdf');
            }
            else if (v === 'edit') { if (confirm(`${label}(${docNumber}) 편집 화면으로 이동할까요?`)) location.href = 'doc-generator.html#edit-' + encodeURIComponent(docNumber); }
        });
    } catch (e) {
        console.error('문서 보기 실패', e);
        showToast(`${label} 불러오기 실패: ${e.message}`);
    } finally {
        _sendDocBusy = false;
    }
}

// 보낸 글을 '우리' 기록으로 + 마지막 연락 + 신규 → 상담중
async function inqSendLogged(x, channel, text) {
    const saved = await inqAddLog(x.id, { direction: 'out', channel, body: text });
    if (!saved) throw new Error('기록 저장 실패');
    const patch = { last_contact_at: new Date().toISOString() };
    const bump = x.status === '신규';
    if (bump) patch.status = '상담중';
    const d = await inqPatch(x.id, patch, bump ? '상태 변경 · 신규 → 상담중' : null);
    if (d) {
        Object.assign(x, d);
        const sel = document.getElementById('inqFStatus');
        if (sel) { sel.value = d.status; sel.className = 'inq-h-status ' + (INQ_STATUS_CLS[d.status] || ''); }
    }
}

// ---------- 오른쪽 거래 패널 카드 접기/펴기 (사람마다 브라우저에 기억) ----------
function inqCardOpen(key) { try { return localStorage.getItem('inq_card_' + key) !== '0'; } catch (_) { return true; } }
function inqCardToggleBtn(key, open) {
    return `<button type="button" class="inq-q-toggle ${open ? 'on' : ''}" data-cardtoggle="${key}" title="${open ? '접기' : '펼치기'}">
      <svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4" viewBox="0 0 24 24"><path d="M9 6l6 6-6 6"/></svg></button>`;
}
function inqBindCardToggle(el, key, rerender) {
    const b = el.querySelector(`[data-cardtoggle="${key}"]`);
    if (!b) return;
    b.addEventListener('click', () => {
        try { localStorage.setItem('inq_card_' + key, inqCardOpen(key) ? '0' : '1'); } catch (_) {}
        rerender();
    });
}

// ---------- 거래처 상세: 상담 · 견적 · 프로젝트 이력 (DB에서 직접 조회) ----------
// 예전엔 화면에 불러온 프로젝트(최근 200건)에서만 찾고, 상담·견적은 아예 안 보여줬음.
// 이름 표기가 조금 달라도('(주)삼인물산' / '삼인물산주식회사') 같은 거래처로 본다.
function clientNameKey(n) {
    return String(n || '').replace(/주식회사|유한회사|\(주\)|\(유\)|㈜|\s/g, '').toLowerCase();
}

async function clientHistoryFetch(name) {
    const key = clientNameKey(name);
    const core = String(name || '').replace(/주식회사|유한회사|\(주\)|\(유\)|㈜/g, '').trim();
    const like = '%' + core.replace(/[%_\\]/g, m => '\\' + m) + '%';
    const same = v => clientNameKey(v) === key;
    const [inq, tmp, domC, domS] = await Promise.all([
        sb.from('inquiries').select('id, client, title, status, assignee, started_at, last_contact_at').ilike('client', like).limit(500),
        sb.from('projects_temp').select('*').ilike('client', like).limit(1000),
        sb.from('projects_domestic').select('*').ilike('client', like).limit(500),
        sb.from('projects_domestic').select('*').ilike('supplier', like).limit(500)
    ]);
    const doms = new Map();
    (domC.data || []).filter(r => same(r.client)).forEach(r => doms.set(r.id, { r, role: '매출' }));
    (domS.data || []).filter(r => same(r.supplier)).forEach(r => {
        const had = doms.get(r.id);
        doms.set(r.id, { r, role: had ? '매출+매입' : '매입' });
    });
    return {
        inquiries: (inq.data || []).filter(r => same(r.client)).sort((a, b) => String(b.last_contact_at || '').localeCompare(String(a.last_contact_at || ''))),
        quotes: (tmp.data || []).filter(r => same(r.client)).map(_projectsTempRowToObj),
        projects: [...doms.values()].sort((a, b) => String(b.r.created_at || '').localeCompare(String(a.r.created_at || ''))),
        error: inq.error || tmp.error || domC.error || domS.error
    };
}

async function renderClientHistory(c) {
    const box = document.getElementById('clientHistBox');
    if (!box) return;
    const esc = s => (s || '').toString().replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
    let h;
    try { h = await clientHistoryFetch(c.companyName); }
    catch (e) { box.innerHTML = `<div style="color:var(--red);font-size:13px">이력을 불러오지 못했습니다: ${esc(e.message || e)}</div>`; return; }
    if (!document.getElementById('clientHistBox')) return;
    const empty = t => `<div style="color:var(--text-tertiary);font-size:13px;padding:8px 0">${t}</div>`;
    const won = n => Number(n || 0).toLocaleString() + '원';
    const md = d => d ? String(d).slice(0, 10).replace(/-/g, '.') : '-';

    // 상담
    const inqHtml = !h.inquiries.length ? empty('상담 기록이 없습니다') : `<table class="data-table" style="margin-top:8px">
        <thead><tr><th style="width:96px">시작일</th><th>문의 내용</th><th style="width:84px">상태</th><th style="width:80px">담당</th></tr></thead>
        <tbody>${h.inquiries.map(q => `<tr data-hinq="${q.id}" style="cursor:pointer">
            <td>${md(q.started_at)}</td><td><strong>${esc(q.title || '(제목 없음)')}</strong></td>
            <td><span class="inq-st ${INQ_STATUS_CLS[q.status] || ''}">${esc(q.status)}</span></td><td>${esc(q.assignee) || '-'}</td>
        </tr>`).join('')}</tbody></table>`;

    // 견적 — 날짜별 묶음
    const groups = [];
    h.quotes.forEach(p => {
        let g = groups.find(x => x.date === p.date);
        if (!g) { g = { date: p.date, items: [] }; groups.push(g); }
        g.items.push(p);
    });
    groups.sort((a, b) => String(b.date).localeCompare(String(a.date)));
    const quoteHtml = !groups.length ? empty('견적 기록이 없습니다') : `<table class="data-table" style="margin-top:8px">
        <thead><tr><th style="width:96px">견적일</th><th>품목</th><th style="width:120px">매출 (VAT포함)</th><th style="width:84px">국내 등록</th></tr></thead>
        <tbody>${groups.map((g, gi) => `<tr data-hquote="${gi}" style="cursor:pointer">
            <td>${md(g.date)}</td>
            <td><strong>${esc(g.items[0].item || '-')}</strong>${g.items.length > 1 ? ` <span style="color:var(--text-tertiary)">외 ${g.items.length - 1}품목</span>` : ''}</td>
            <td>${won(g.items.reduce((s, p) => s + calcTempRevenueWithVat(p), 0))}</td>
            <td>${g.items.some(p => p.transferredAt) ? '✅' : '-'}</td>
        </tr>`).join('')}</tbody></table>`;

    // 국내 프로젝트
    const roleBadge = role => role === '매출' ? '<span class="badge badge-blue">매출</span>' : `<span class="badge badge-purple">${role}</span>`;
    const projHtml = !h.projects.length ? empty('연동된 프로젝트가 없습니다') : `<table class="data-table" style="margin-top:8px">
        <thead><tr><th style="width:90px">역할</th><th>품명</th><th style="width:84px">상태</th><th style="width:100px">납기</th><th style="width:120px">금액</th></tr></thead>
        <tbody>${h.projects.map(({ r, role }) => `<tr data-hproj="${r.id}" style="cursor:pointer">
            <td>${roleBadge(role)}</td><td><strong>${esc(r.product_name || '-')}</strong></td><td>${esc(r.status)}</td>
            <td>${esc(r.delivery_date) || '-'}</td><td>${won(role === '매입' ? r.supplier_revenue : r.revenue)}</td>
        </tr>`).join('')}</tbody></table>`;

    box.innerHTML = `
        <div class="form-section-title">💬 상담 (${h.inquiries.length}건)</div>${inqHtml}
        <div class="form-section-title" style="margin-top:16px">🧾 견적 (${groups.length}건)</div>${quoteHtml}
        <div class="form-section-title" style="margin-top:16px">📦 국내 프로젝트 (${h.projects.length}건)</div>${projHtml}`;

    box.querySelectorAll('[data-hinq]').forEach(tr => tr.addEventListener('click', () => {
        _inqSel = Number(tr.dataset.hinq); _inqFilter = 'all';
        try { localStorage.setItem('tp_view', 'inq'); } catch (_) {}
        closeModal(); switchTab('projects-temp');
    }));
    box.querySelectorAll('[data-hquote]').forEach(tr => tr.addEventListener('click', () => {
        try { localStorage.setItem('tp_view', 'quote'); } catch (_) {}
        closeModal(); switchTab('projects-temp');
        const g = groups[Number(tr.dataset.hquote)];
        setTimeout(() => { const gi = g ? inqQuoteGroupIndex(g.date, g.items[0].client) : -1; if (gi >= 0) openTempQuote(gi); }, 400);
    }));
    box.querySelectorAll('[data-hproj]').forEach(tr => tr.addEventListener('click', () => {
        const hit = h.projects.find(v => v.r.id === Number(tr.dataset.hproj));
        closeModal(); switchTab('projects-domestic');
        setTimeout(() => { if (inqEnsureProject(hit && hit.r)) showProjectDetail(hit.r.id); }, 100);
    }));
}

// ---------- 거래처 자동 추가 알림 (migration 040 트리거가 실제 추가) ----------
// 저장 직후, 방금(1분 안) 거래처 DB에 새로 생긴 이름이 있으면 알려주고 거래처 목록 캐시를 새로 고친다
async function clientAutoAddNotice(names) {
    const keys = [...new Set((names || []).map(n => clientNameKey(n)).filter(k => k.length >= 2))];
    if (!keys.length) return;
    await new Promise(r => setTimeout(r, 400));
    const since = new Date(Date.now() - 60000).toISOString();
    const { data } = await sb.from('clients').select('company_name, category, created_at').gte('created_at', since).limit(50);
    const added = (data || []).filter(r => keys.includes(clientNameKey(r.company_name)));
    if (!added.length) return;
    try { invalidateClientNamesCache(); buildTempClientDatalist(); } catch (_) {}
    showToast(`국내 거래처 DB에 새로 추가했어요 · ${added.map(r => r.company_name + (r.category ? `(${r.category})` : '')).join(', ')}`);
}

// ---------- 새 고객사: 사업자등록증(사진·PDF·복사한 글)으로 자동 입력 ----------
// AI 읽기: /api/meeting-summarize?kind=bizreg → api/_bizreg-extract.js
const BIZREG_MAP = [
    ['company_name', 'cliCompanyName', '회사명'], ['ceo', 'cliCeo', '대표자'], ['business_no', 'cliBusinessNo', '사업자번호'],
    ['address', 'cliAddress', '주소'], ['biz_type', 'cliBizType', '업태'], ['biz_item', 'cliBizItem', '업종'],
    ['phone', 'cliPhone', '전화'], ['email', 'cliEmail', '이메일']
];
let _bizregSeq = 0;

function bizregBoxHtml() {
    return `
      <div class="biz-drop" id="cliBizDrop">
        <div class="biz-drop-top">
          <svg width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/></svg>
          <div><b>사업자등록증으로 자동 입력</b><span>사진·PDF를 여기로 끌어다 놓거나, 아래 칸에 Ctrl+V (사진도 됨) · 글을 복사해 붙여넣어도 됩니다</span></div>
          <label class="biz-file-btn">파일 선택<input type="file" id="cliBizFile" accept="image/*,application/pdf" hidden></label>
        </div>
        <textarea id="cliBizText" rows="2" placeholder="여기를 누르고 Ctrl+V — 사업자등록증 사진 또는 글"></textarea>
        <div class="biz-status" id="cliBizStatus"></div>
      </div>`;
}

function bizregStatus(html, kind) {
    const el = document.getElementById('cliBizStatus');
    if (!el) return;
    el.className = 'biz-status' + (kind ? ' ' + kind : '');
    el.innerHTML = html || '';
}

function bizregBind() {
    const box = document.getElementById('cliBizDrop');
    if (!box) return;
    const ta = document.getElementById('cliBizText');
    let t = null;
    ta.addEventListener('paste', (e) => {
        const items = (e.clipboardData && e.clipboardData.items) || [];
        for (const it of items) {
            if (it.kind === 'file' && it.type && (it.type.startsWith('image/') || it.type === 'application/pdf')) {
                const f = it.getAsFile();
                if (f) { e.preventDefault(); bizregFromFile(f); return; }
            }
        }
        const html = e.clipboardData && e.clipboardData.getData('text/html');
        if (html && /<(p|div|br|tr|td|table)\b/i.test(html)) {
            e.preventDefault();
            inqInsertText(ta, inqHtmlToText(html));
        }
    });
    ta.addEventListener('input', () => {
        clearTimeout(t);
        const v = ta.value.trim();
        if (v.length >= 20) t = setTimeout(() => bizregRun({ text: v }), 700);
    });
    document.getElementById('cliBizFile').addEventListener('change', (e) => {
        const f = e.target.files && e.target.files[0];
        if (f) bizregFromFile(f);
        e.target.value = '';
    });
    box.addEventListener('dragover', (e) => { if (Array.from((e.dataTransfer && e.dataTransfer.types) || []).includes('Files')) { e.preventDefault(); box.classList.add('over'); } });
    box.addEventListener('dragleave', () => box.classList.remove('over'));
    box.addEventListener('drop', (e) => {
        box.classList.remove('over');
        const f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
        if (f) { e.preventDefault(); bizregFromFile(f); }
    });
    // 사람이 고친 칸은 자동 입력이 다시 덮지 않게
    BIZREG_MAP.forEach(([, id]) => {
        const el = document.getElementById(id);
        if (el) el.addEventListener('input', () => { delete el.dataset.auto; el.classList.remove('biz-auto'); });
    });
}

async function bizregFromFile(f) {
    const isPdf = f.type === 'application/pdf' || /\.pdf$/i.test(f.name || '');
    if (!isPdf && !(f.type || '').startsWith('image/')) { bizregStatus('사진(JPG·PNG) 또는 PDF 파일만 읽을 수 있어요', 'err'); return; }
    if (isPdf && f.size > 5 * 1024 * 1024) { bizregStatus('PDF가 너무 커요 (5MB 이하). 사진으로 찍어 넣어주세요', 'err'); return; }
    bizregStatus('<span class="inq-ai-spin"></span> 파일 준비 중…', 'busy');
    try {
        let dataUrl = await inqBlobToDataUrl(f);
        if (!isPdf) dataUrl = await _shrinkDataUrl(dataUrl, 2000, 0.88);   // 글자가 읽힐 만큼만 줄여서 전송
        const m = /^data:([^;,]+)/.exec(dataUrl);
        const mediaType = isPdf ? 'application/pdf' : (m ? m[1] : 'image/jpeg');
        if (!isPdf && !['image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(mediaType)) {
            bizregStatus('이 사진 형식은 읽을 수 없어요. 캡처(Win+Shift+S)해서 붙여넣어 주세요', 'err'); return;
        }
        await bizregRun({ file: { data: dataUrl.split(',')[1], mediaType }, name: f.name || '' });
    } catch (e) { bizregStatus('파일을 읽지 못했어요: ' + escHtml(e.message || String(e)), 'err'); }
}

// 글만 있을 때 AI가 안 되면 쓰는 최소 규칙 (라벨 사이 띄어쓰기 허용)
function bizregParseText(t) {
    const s = String(t || '');
    const lab = (w) => w.split('').map(ch => ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('\\s*');
    const unspace = v => /^([가-힣]\s){1,5}[가-힣]$/.test(v) ? v.replace(/\s/g, '') : v;   // '홍 길 동' → '홍길동'
    const get = (labels) => {
        for (const l of labels) {
            const m = s.match(new RegExp(lab(l) + '\\s*[:：]?\\s*([^\\n]+)'));
            if (m && m[1].trim()) return m[1].trim();
        }
        return '';
    };
    const bn = s.match(/\d{3}\s*-\s*\d{2}\s*-\s*\d{5}/);
    return {
        business_no: bn ? bn[0].replace(/\s/g, '') : '',
        company_name: get(['법인명(단체명)', '법인명', '상호']).replace(/\s*(성\s*명|대\s*표\s*자).*$/, ''),
        ceo: unspace(get(['대표자', '성명'])).replace(/\s*(생\s*년|주\s*민|법\s*인).*$/, ''),
        address: get(['사업장소재지', '사업장 소재지']),
        biz_type: get(['업태']).replace(/\s*종\s*목.*$/, ''),
        biz_item: get(['종목'])
    };
}

async function bizregRun(payload) {
    const seq = ++_bizregSeq;
    bizregStatus('<span class="inq-ai-spin"></span> AI가 사업자등록증을 읽는 중…', 'busy');
    let d = null, fail = '';
    try {
        const { data: sess } = await sb.auth.getSession();
        const token = sess && sess.session && sess.session.access_token;
        if (!token) throw new Error('로그인이 필요합니다');
        const res = await fetch('/api/meeting-summarize?kind=bizreg', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
            body: JSON.stringify({ text: payload.text || '', file: payload.file || null })
        });
        const j = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(j.error || ('HTTP ' + res.status));
        d = j;
    } catch (e) {
        fail = e.message || String(e);
        if (payload.text) d = bizregParseText(payload.text);   // 글이면 규칙으로라도
    }
    if (seq !== _bizregSeq || !document.getElementById('cliCompanyName')) return;
    if (!d) { bizregStatus('읽지 못했어요 — ' + escHtml(fail), 'err'); return; }

    const filled = [], kept = [];
    BIZREG_MAP.forEach(([k, id, label]) => {
        const el = document.getElementById(id);
        const v = String(d[k] || '').trim();
        if (!el || !v) return;
        if (el.value.trim() && el.dataset.auto !== '1') { if (el.value.trim() !== v) kept.push(label); return; }
        el.value = v;
        el.dataset.auto = '1';
        el.classList.add('biz-auto');
        filled.push(label);
    });
    if (!filled.length) {
        bizregStatus(d.is_certificate === false ? '사업자등록증이 아닌 것 같아요. 다른 파일로 다시 시도해주세요' : '새로 채울 정보가 없어요' + (kept.length ? ` (이미 입력된 칸: ${kept.join(' · ')})` : ''), 'err');
        return;
    }
    let msg = `${INQ_CHECK_SVG} 자동 입력 — <b>${filled.join(' · ')}</b> <span>틀리면 바로 고쳐주세요</span>`;
    if (kept.length) msg += `<div class="biz-kept">이미 입력돼 있어 그대로 둔 칸: ${kept.join(' · ')}</div>`;
    if (fail) msg += `<div class="biz-kept">AI 연결이 안 돼 글에서 찾은 것만 넣었어요</div>`;
    bizregStatus(msg, 'ok');
    bizregDupCheck(d);
}

// 이미 등록된 거래처인지 (사업자번호 또는 이름)
async function bizregDupCheck(d) {
    const bn = String(d.business_no || '').replace(/[^0-9]/g, '');
    const key = clientNameKey(d.company_name);
    const editingId = Number((document.getElementById('cliBizDrop') || {}).dataset?.editing || 0);
    const hits = new Map();
    try {
        if (bn.length === 10) {
            const fmt = `${bn.slice(0, 3)}-${bn.slice(3, 5)}-${bn.slice(5)}`;
            const { data } = await sb.from('clients').select('id, company_name, business_no').in('business_no', [fmt, bn]).limit(5);
            (data || []).forEach(r => hits.set(r.id, r));
        }
        if (key.length >= 2) {
            const core = String(d.company_name).replace(/주식회사|유한회사|\(주\)|\(유\)|㈜/g, '').trim();
            const { data } = await sb.from('clients').select('id, company_name, business_no').ilike('company_name', '%' + core.replace(/[%_\\]/g, m => '\\' + m) + '%').limit(20);
            (data || []).filter(r => clientNameKey(r.company_name) === key).forEach(r => hits.set(r.id, r));
        }
    } catch (_) { return; }
    const list = [...hits.values()].filter(r => r.id !== editingId);
    if (!list.length || !document.getElementById('cliBizStatus')) return;
    const el = document.getElementById('cliBizStatus');
    el.insertAdjacentHTML('beforeend', `<div class="biz-dup">⚠️ 이미 등록된 거래처일 수 있어요: ${list.map(r =>
        `<a href="#" data-cid="${r.id}">${escHtml(r.company_name)}${r.business_no ? ' (' + escHtml(r.business_no) + ')' : ''}</a>`).join(', ')} — 눌러서 기존 거래처 열기</div>`);
    el.querySelectorAll('[data-cid]').forEach(a => a.addEventListener('click', (e) => { e.preventDefault(); openClientDetail(Number(a.dataset.cid)); }));
}

// ---------- 연결된 견적: 품목별 판매·매입 명세 ----------
// 금액이 어디서 나왔는지 보이게 — 제품·인쇄·포장·라벨·택배를 판매/매입 나란히, 그 아래 공급가·부가세·합계·마진
function inqQuoteBreakdown(p) {
    const q = p.qty || 0;
    const supplyOf = (amt, vat) => vat === 'VAT 포함' ? Math.round(amt / 1.1) : amt;
    const fee = (unit, apply, vat) => {
        const amt = calcTempFeeTotal(unit, apply, q);
        return { amt, vat, calc: amt ? (apply === '1개당' ? `${Number(unit).toLocaleString()} × ${q.toLocaleString()}` : `일괄 (${q.toLocaleString()}개 전체)`) : '' };
    };
    const meth = (a, b, skip) => {
        const clean = v => (v && !skip.includes(v)) ? v : '';
        const x = clean(a), y = clean(b);
        return x && y && x !== y ? `판매 ${x} / 매입 ${y}` : (x || y);
    };
    const rows = [];
    rows.push({ label: '제품', sub: '',
        sale: { amt: (p.unitPrice || 0) * q, vat: p.unitPriceVat, calc: p.unitPrice ? `${Number(p.unitPrice).toLocaleString()} × ${q.toLocaleString()}` : '' },
        buy: { amt: (p.supplierUnitPrice || 0) * q, vat: p.supplierUnitPriceVat, calc: p.supplierUnitPrice ? `${Number(p.supplierUnitPrice).toLocaleString()} × ${q.toLocaleString()}` : '' } });
    rows.push({ label: '인쇄', sub: meth(p.printMethod, p.supPrintMethod, ['없음']),
        sale: fee(p.printFee, p.printFeeApply, p.printFeeVat), buy: fee(p.supPrintFee, p.supPrintFeeApply, p.supPrintFeeVat) });
    rows.push({ label: '포장', sub: meth(p.packMethod, p.supPackMethod, ['기본박스', '없음']),
        sale: fee(p.packagingFee, p.packagingFeeApply, p.packagingFeeVat), buy: fee(p.supPackagingFee, p.supPackagingFeeApply, p.supPackagingFeeVat) });
    rows.push({ label: '라벨', sub: '',
        sale: fee(p.labelFee, p.labelFeeApply || '1개당', p.labelFeeVat), buy: fee(p.supLabelFee, p.supLabelFeeApply || '1개당', p.supLabelFeeVat) });
    const ship = (boxes, per, vat) => ({ amt: (boxes || 0) * (per || 0), vat, calc: boxes && per ? `${boxes}박스 × ${Number(per).toLocaleString()}` : '' });
    rows.push({ label: '택배', sub: '',
        sale: ship(p.shippingBoxes, p.shippingFee, p.shippingFeeVat), buy: ship(p.supShippingBoxes, p.supShippingFee, p.supShippingFeeVat) });
    // 금액도 내용도 없는 줄은 뺀다 (제품 줄은 항상)
    const shown = rows.filter((r, i) => i === 0 || r.sale.amt || r.buy.amt || r.sub);
    const tot = side => {
        const total = side === 'sale' ? calcTempRevenueWithVat(p) : calcTempSupRevenueWithVat(p);
        const supply = rows.reduce((s, r) => s + supplyOf(r[side].amt, r[side].vat), 0);
        return { supply, vat: total - supply, total };
    };
    return { rows: shown, sale: tot('sale'), buy: tot('buy') };
}

function inqQuoteItemHtml(p) {
    const bd = inqQuoteBreakdown(p);
    const n = v => Number(v || 0).toLocaleString();
    const cell = (c, hasMethod) => {
        if (c.amt) return `<b>${n(c.amt)}</b>${c.calc ? `<small>${escHtml(c.calc)}${c.vat === 'VAT 포함' ? ' · VAT포함가' : ''}</small>` : ''}`;
        return hasMethod ? '<span class="inq-bd-inc" title="추가 금액 없이 제품 단가에 포함">단가에 포함</span>' : '<span class="inq-bd-none">–</span>';
    };
    const hasBuy = bd.buy.total > 0 || p.supplier;
    const m = bd.sale.total - bd.buy.total;
    const pct = bd.sale.total > 0 ? Math.round(m / bd.sale.total * 100) : 0;
    return `<div class="inq-qi">
      <div class="inq-qi-top"><b>${escHtml(p.item || '-')}</b>${p.qty ? `<span>${p.qty.toLocaleString()}개</span>` : ''}</div>
      <table class="inq-bd">
        <thead><tr><th></th><th class="sale">판매</th><th class="buy">매입${p.supplier ? `<small>${escHtml(p.supplier)}</small>` : ''}</th></tr></thead>
        <tbody>${bd.rows.map(r => `<tr>
            <td class="lab">${escHtml(r.label)}${r.sub ? `<small>${escHtml(r.sub)}</small>` : ''}</td>
            <td>${cell(r.sale, !!r.sub)}</td>
            <td>${hasBuy ? cell(r.buy, !!r.sub) : '<span class="inq-bd-none">–</span>'}</td>
        </tr>`).join('')}</tbody>
        <tfoot>
          <tr class="sub"><td class="lab">공급가</td><td>${n(bd.sale.supply)}</td><td>${hasBuy ? n(bd.buy.supply) : '–'}</td></tr>
          <tr class="sub"><td class="lab">부가세</td><td>${n(bd.sale.vat)}</td><td>${hasBuy ? n(bd.buy.vat) : '–'}</td></tr>
          <tr class="total"><td class="lab">합계 <small>VAT포함</small></td><td class="sale"><b>${n(bd.sale.total)}원</b></td><td class="buy">${hasBuy ? `<b>${n(bd.buy.total)}원</b>` : '–'}</td></tr>
        </tfoot>
      </table>
      ${hasBuy && bd.buy.total ? `<div class="inq-bd-margin ${m >= 0 ? 'pos' : 'neg'}">마진 <b>${n(m)}원</b> <span>${pct}%</span> <em>= 판매 합계 − 매입 합계</em></div>` : ''}
    </div>`;
}

// ---------- 사용법 안내: ① 따라하기 안내(가이드 투어) ② 마우스 올리면 뜨는 설명 — 상담·견적 화면 ----------
// 투어: 버튼을 일하는 순서대로 하나씩 강조하고 옆에 설명. 처음 들어온 사람에게 한 번 자동으로.
// 설명: [data-help] 에 마우스를 올리면 짧은 설명 (TP_HELP 선택자 목록을 화면이 다시 그려질 때마다 붙임)
const TOUR_TP_KEY = 'tour_tp_v1';

function _tourEl(sel) {
    const list = Array.isArray(sel) ? sel : [sel];
    for (const s of list) {
        if (!s) continue;
        const el = document.querySelector(s);
        if (el && el.offsetParent !== null && el.getBoundingClientRect().width > 0) return el;
    }
    return null;
}

let _tour = null;
function startTour(steps) {
    endTour();
    const wrap = document.createElement('div');
    wrap.className = 'tour-layer';
    wrap.innerHTML = `<div class="tour-block"></div><div class="tour-dim"></div><div class="tour-dim"></div><div class="tour-dim"></div><div class="tour-dim"></div><div class="tour-hole"></div>
      <div class="tour-pop" role="dialog" aria-live="polite">
        <div class="tour-count"></div><h4></h4><div class="tour-body"></div>
        <div class="tour-act">
          <button type="button" class="tour-skip">그만 보기</button>
          <div class="inq-spacer"></div>
          <button type="button" class="tour-prev">이전</button>
          <button type="button" class="tour-next">다음</button>
        </div>
      </div>`;
    document.body.appendChild(wrap);
    _tour = { steps, i: 0, wrap };
    wrap.querySelector('.tour-skip').onclick = endTour;
    wrap.querySelector('.tour-prev').onclick = () => tourGo(_tour.i - 1);
    wrap.querySelector('.tour-next').onclick = () => (_tour.i >= _tour.steps.length - 1 ? endTour() : tourGo(_tour.i + 1));
    _tour.onKey = (e) => {
        if (!_tour) return;
        if (e.key === 'Escape') endTour();
        else if (e.key === 'ArrowRight' || e.key === 'Enter') { e.preventDefault(); wrap.querySelector('.tour-next').click(); }
        else if (e.key === 'ArrowLeft') tourGo(_tour.i - 1);
    };
    _tour.onResize = () => { if (_tour) tourPlace(); };
    document.addEventListener('keydown', _tour.onKey, true);
    window.addEventListener('resize', _tour.onResize);
    tourGo(0);
}

function endTour() {
    if (!_tour) return;
    document.removeEventListener('keydown', _tour.onKey, true);
    window.removeEventListener('resize', _tour.onResize);
    _tour.wrap.remove();
    const done = _tour.onEnd;
    _tour = null;
    if (done) try { done(); } catch (_) {}
}

async function tourGo(i) {
    if (!_tour) return;
    i = Math.max(0, Math.min(_tour.steps.length - 1, i));
    _tour.i = i;
    const st = _tour.steps[i];
    if (st.prep) { try { await st.prep(); } catch (_) {} }
    if (!_tour || _tour.i !== i) return;
    const w = _tour.wrap;
    w.querySelector('.tour-count').textContent = `${i + 1} / ${_tour.steps.length}`;
    w.querySelector('h4').textContent = st.title;
    const el = st.sel ? _tourEl(st.sel) : null;
    w.querySelector('.tour-body').innerHTML = st.body + (st.sel && !el && st.missing ? `<p class="tour-miss">${st.missing}</p>` : '');
    w.querySelector('.tour-prev').disabled = i === 0;
    w.querySelector('.tour-next').textContent = i === _tour.steps.length - 1 ? '끝내기' : '다음';
    _tour.el = el;
    if (el) el.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    requestAnimationFrame(tourPlace);
}

function tourPlace() {
    if (!_tour) return;
    const w = _tour.wrap, hole = w.querySelector('.tour-hole'), pop = w.querySelector('.tour-pop');
    const el = _tour.el;
    const vw = window.innerWidth, vh = window.innerHeight, pad = 6;
    pop.style.visibility = 'hidden';
    pop.style.left = '0px'; pop.style.top = '0px';
    const pw = pop.offsetWidth, ph = pop.offsetHeight;
    let left, top;
    // 강조 영역 둘레를 어두운 사각형 4개로 덮는다 (큰 box-shadow는 환경에 따라 안 그려짐)
    const dims = w.querySelectorAll('.tour-dim');
    const setDims = (x, y, wd, ht) => {
        const R = [[0, 0, vw, y], [0, y + ht, vw, Math.max(0, vh - y - ht)], [0, y, x, ht], [x + wd, y, Math.max(0, vw - x - wd), ht]];
        dims.forEach((d, k) => { const [a, b, c, e] = R[k]; d.style.cssText = `left:${a}px;top:${b}px;width:${c}px;height:${e}px`; });
    };
    if (!el) {
        hole.style.cssText = 'display:none';
        setDims(0, vh, 0, 0);
        left = (vw - pw) / 2; top = (vh - ph) / 2;
    } else {
        const r = el.getBoundingClientRect();
        const x = Math.max(4, r.left - pad), y = Math.max(4, r.top - pad);
        const wd = Math.min(vw - 8, r.right + pad) - x, ht = Math.min(vh - 8, r.bottom + pad) - y;
        hole.style.cssText = `left:${x}px;top:${y}px;width:${wd}px;height:${ht}px`;
        setDims(x, y, wd, ht);
        // 아래 → 위 → 오른쪽 → 왼쪽 순으로 빈 곳에
        if (y + ht + 12 + ph < vh) { top = y + ht + 12; left = x; }
        else if (y - 12 - ph > 0) { top = y - 12 - ph; left = x; }
        else if (x + wd + 12 + pw < vw) { left = x + wd + 12; top = y; }
        else { left = x - 12 - pw; top = y; }
        left = Math.max(12, Math.min(vw - pw - 12, left));
        top = Math.max(12, Math.min(vh - ph - 12, top));
    }
    pop.style.left = left + 'px';
    pop.style.top = top + 'px';
    pop.style.visibility = 'visible';
}

// 상담 하나를 열어둔다 (투어가 상세 화면을 가리킬 수 있게)
async function _tourOpenInquiry() {
    tpSetView('inq');
    if (!_inqList.length) { try { await inqLoad(); } catch (_) {} }
    if (_inqSel === 'new') _inqSel = null;
    if (!_inqSel || !inqFind(_inqSel)) {
        const first = inqFiltered()[0] || _inqList[0];
        if (!first) return;
        _inqSel = first.id;
        inqRenderList();
    }
    if (!document.getElementById('inqStage')) await inqRenderDetail();
    await new Promise(r => setTimeout(r, 350));
}

